package main

import (
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"
)

const (
	buildCommit  = "d8d001054f77de5ac19385b0b62f7900a63d9eb8"
	buildDate    = "2026-06-11T19:35:54Z"
	buildSource  = "unknown"
	buildVersion = "d8d00105"
)

type cliArgs struct {
	repoPath      string
	filterPath    string
	gitArg        string
	version       bool
	debug         bool
	tailLogs      bool
	profile       bool
	printConfig   bool
	printCfgDir   bool
	useConfigDir  string
	workTree      string
	gitDir        string
	customConfig  string
	screenMode    string
	positional    []string
	trailing      []string
}

func progName() string {
	return filepath.Base(os.Args[0])
}

func main() {
	args := parseCLI(os.Args[1:])
	runApp(args)
}

func runApp(args *cliArgs) {
	if args.useConfigDir != "" {
		os.Setenv("CONFIG_DIR", args.useConfigDir)
	}
	if args.version {
		fmt.Printf("commit=%s, build date=%s, build source=%s, version=%s, os=%s, arch=%s, git version=%s\n",
			buildCommit, buildDate, buildSource, buildVersion, "linux", "amd64", gitVersionString())
		os.Exit(0)
	}
	if args.printConfig {
		os.Stdout.WriteString(defaultConfigYAML)
		os.Exit(0)
	}
	if args.printCfgDir {
		fmt.Printf("%s\n", configDir())
		os.Exit(0)
	}
	if args.tailLogs {
		tailLogs()
		os.Exit(0)
	}
	if args.repoPath != "" {
		if args.workTree != "" || args.gitDir != "" {
			log.Fatal("--path option is incompatible with the --work-tree and --git-dir options")
		}
		absPath, err := filepath.Abs(args.repoPath)
		if err != nil {
			log.Fatal(err)
		}
		realPath, err := filepath.EvalSymlinks(absPath)
		if err != nil {
			realPath = absPath
		}
		if st, err := os.Stat(filepath.Join(realPath, ".git")); err != nil || st == nil {
			log.Fatal(absPath + " is not a valid git repository.")
		}
		args.workTree = realPath
		args.gitDir = filepath.Join(realPath, ".git")
	}
	if args.customConfig != "" {
		os.Setenv("LG_CONFIG_FILE", args.customConfig)
	}
	if args.workTree != "" {
		if err := os.Chdir(args.workTree); err != nil {
			log.Fatalf("Failed to change directory to %s: %v", args.workTree, err)
		}
	}
	if args.gitArg != "" {
		switch args.gitArg {
		case "status", "branch", "log", "stash":
		default:
			log.Fatalf("Invalid git arg value: '%s'. Must be one of the following values: status, branch, log, stash. e.g. 'lazygit status'. See 'lazygit --help'.", args.gitArg)
		}
	}
	startApp(args)
}

func tailLogs() {
	logPath := filepath.Join(stateDir(), "development.log")
	fmt.Printf("Tailing log file %s\n\n", logPath)
	f, err := os.Open(logPath)
	if err != nil {
		log.Fatal("Log file does not exist. Run `lazygit --debug` first to create the log file")
	}
	buf := make([]byte, 4096)
	for {
		n, err := f.Read(buf)
		if n > 0 {
			os.Stdout.Write(buf[:n])
		}
		if err != nil {
			sleepMs(200)
		}
	}
}

