type cliFlag struct {
	short, long, desc string
	isBool             bool
	setStr             func(string)
	setBool            func(bool)
}

func helpText() string {
	name := progName()
	var b strings.Builder
	b.WriteString(name + "\n\n")
	b.WriteString("  Usage:\n")
	b.WriteString("    " + name + " [git-arg]\n\n")
	b.WriteString("  Positional Variables: \n")
	b.WriteString("    git-arg   Panel to focus upon opening lazygit. Accepted values (based on git terminology): status, branch, log, stash. Ignored if --filter arg is passed.\n")
	b.WriteString("  Flags: \n")
	flags := cliFlagDefs(nil)
	maxLong := 0
	for _, f := range flags {
		if len(f.long) > maxLong {
			maxLong = len(f.long)
		}
	}
	for _, f := range flags {
		b.WriteString("    ")
		if f.short != "" {
			b.WriteString("-" + f.short + " ")
		} else {
			b.WriteString("   ")
		}
		b.WriteString("--" + f.long)
		b.WriteString(strings.Repeat(" ", maxLong-len(f.long)))
		b.WriteString("   " + f.desc + "\n")
	}
	b.WriteString("\n")
	return b.String()
}

func cliFlagDefs(a *cliArgs) []*cliFlag {
	if a == nil {
		a = &cliArgs{}
	}
