					case btn&64 != 0:
						if btn&1 != 0 {
							e.MBtn = MouseWheelDown
						} else {
							e.MBtn = MouseWheelUp
						}
					case btn&32 != 0:
						e.MBtn = MouseMotion
					case final == 'm':
						e.MBtn = MouseRelease
