				case "12":
					return keyEv(KeyF2, mod), used, false
				case "13":
					return keyEv(KeyF3, mod), used, false
				case "14":
					return keyEv(KeyF4, mod), used, false
				case "15":
					return keyEv(KeyF5, mod), used, false
				case "17":
					return keyEv(KeyF6, mod), used, false
				case "18":
					return keyEv(KeyF7, mod), used, false
				case "19":
					return keyEv(KeyF8, mod), used, false
				case "20":
					return keyEv(KeyF9, mod), used, false
				case "21":
					return keyEv(KeyF10, mod), used, false
				case "23":
					return keyEv(KeyF11, mod), used, false
				case "24":
					return keyEv(KeyF12, mod), used, false
				}
				return nil, used, false
