	}
}

func (t *Terminal) readWithTimeout(buf []byte, d time.Duration) int {
	// use VTIME based read via a temporary termios change
	raw, err := tcget(t.tty.Fd())
	if err != nil {
		return 0
	}
	tmp := *raw
	tmp.Cc[syscall.VMIN] = 0
	tmp.Cc[syscall.VTIME] = uint8(d / (100 * time.Millisecond))
	if tmp.Cc[syscall.VTIME] == 0 {
		tmp.Cc[syscall.VTIME] = 1
	}
	tcset(t.tty.Fd(), &tmp)
	n, _ := t.tty.Read(buf)
	tcset(t.tty.Fd(), raw)
	return n
}

func indexBytes(b []byte, s string) int {
	return strings.Index(string(b), s)
}

// parseIncomplete handles a lone escape or partial sequence after timeout
func parseIncomplete(b []byte) (*Event, int) {
	if b[0] == 0x1b {
		if len(b) == 1 {
			return &Event{Type: EvKey, Key: Key{Code: KeyEsc}}, 1
		}
		// treat as alt + rest
		ev, used, inc := parseInput(b[1:])
		if inc || ev == nil {
			return &Event{Type: EvKey, Key: Key{Code: KeyEsc}}, 1
		}
		ev.Key.Mod |= ModAlt
		return ev, used + 1
	}
	_, size := utf8.DecodeRune(b)
	return nil, size
}

func keyEv(code KeyCode, mod Mod) *Event {
	return &Event{Type: EvKey, Key: Key{Code: code, Mod: mod}}
}

func csiMod(param string) Mod {
	n, err := strconv.Atoi(param)
	if err != nil || n < 2 {
		return 0
	}
	n--
	var m Mod
	if n&1 != 0 {
		m |= ModShift
	}
	if n&2 != 0 {
		m |= ModAlt
	}
	if n&4 != 0 {
		m |= ModCtrl
	}
	return m
}

// parseInput parses one event from the start of b.
func parseInput(b []byte) (ev *Event, used int, incomplete bool) {
	c := b[0]
	if c == 0x1b {
		if len(b) == 1 {
			return nil, 0, true
		}
		if b[1] == '[' {
			// CSI
			i := 2
			for i < len(b) && (b[i] >= 0x30 && b[i] <= 0x3f) {
				i++
			}
			for i < len(b) && (b[i] >= 0x20 && b[i] <= 0x2f) {
				i++
			}
			if i >= len(b) {
				return nil, 0, true
			}
			final := b[i]
			params := string(b[2:i])
			used = i + 1
			if strings.HasPrefix(params, "<") && (final == 'M' || final == 'm') {
				parts := strings.Split(params[1:], ";")
				if len(parts) == 3 {
					btn, _ := strconv.Atoi(parts[0])
					x, _ := strconv.Atoi(parts[1])
					y, _ := strconv.Atoi(parts[2])
					e := &Event{Type: EvMouse, MX: x - 1, MY: y - 1}
					switch {
					case btn&64 != 0:
						if btn&1 != 0 {
							e.MBtn = MouseWheelDown
						} else {
							e.MBtn = MouseWheelUp
						}
					case btn&32 != 0:
						e.MBtn = MouseMotion
					case final == 'm':
						e.MBtn = MouseRelease
					default:
						switch btn & 3 {
						case 0:
							e.MBtn = MouseLeft
						case 1:
							e.MBtn = MouseMiddle
						case 2:
							e.MBtn = MouseRight
						}
					}
					return e, used, false
				}
				return nil, used, false
			}
			ps := strings.Split(params, ";")
			mod := Mod(0)
			if len(ps) >= 2 {
				mod = csiMod(ps[1])
			}
			switch final {
			case 'A':
				return keyEv(KeyUp, mod), used, false
			case 'B':
				return keyEv(KeyDown, mod), used, false
			case 'C':
				return keyEv(KeyRight, mod), used, false
			case 'D':
				return keyEv(KeyLeft, mod), used, false
			case 'H':
				return keyEv(KeyHome, mod), used, false
			case 'F':
				return keyEv(KeyEnd, mod), used, false
			case 'Z':
				return keyEv(KeyBacktab, 0), used, false
			case 'P':
				return keyEv(KeyF1, mod), used, false
			case 'Q':
				return keyEv(KeyF2, mod), used, false
			case 'R':
				return keyEv(KeyF3, mod), used, false
			case 'S':
				return keyEv(KeyF4, mod), used, false
			case 'I', 'O':
				return nil, used, false // focus events
			case '~':
				switch ps[0] {
				case "1", "7":
					return keyEv(KeyHome, mod), used, false
				case "2":
					return keyEv(KeyInsert, mod), used, false
				case "3":
					return keyEv(KeyDelete, mod), used, false
				case "4", "8":
					return keyEv(KeyEnd, mod), used, false
				case "5":
					return keyEv(KeyPgUp, mod), used, false
				case "6":
					return keyEv(KeyPgDn, mod), used, false
				case "11":
					return keyEv(KeyF1, mod), used, false
				case "12":
					return keyEv(KeyF2, mod), used, false
				case "13":
					return keyEv(KeyF3, mod), used, false
				case "14":
					return keyEv(KeyF4, mod), used, false
				case "15":
					return keyEv(KeyF5, mod), used, false
				case "17":
					return keyEv(KeyF6, mod), used, false
				case "18":
					return keyEv(KeyF7, mod), used, false
				case "19":
					return keyEv(KeyF8, mod), used, false
				case "20":
					return keyEv(KeyF9, mod), used, false
				case "21":
					return keyEv(KeyF10, mod), used, false
				case "23":
					return keyEv(KeyF11, mod), used, false
				case "24":
					return keyEv(KeyF12, mod), used, false
				}
				return nil, used, false
			case 'u':
				// CSI u encoding
				code, _ := strconv.Atoi(ps[0])
				return &Event{Type: EvKey, Key: Key{Code: KeyRune, Ch: rune(code), Mod: mod}}, used, false
			}
			return nil, used, false
		}
		if b[1] == 'O' {
			if len(b) < 3 {
				return nil, 0, true
			}
			used = 3
			switch b[2] {
			case 'A':
				return keyEv(KeyUp, 0), used, false
			case 'B':
				return keyEv(KeyDown, 0), used, false
			case 'C':
				return keyEv(KeyRight, 0), used, false
			case 'D':
				return keyEv(KeyLeft, 0), used, false
			case 'H':
				return keyEv(KeyHome, 0), used, false
			case 'F':
				return keyEv(KeyEnd, 0), used, false
			case 'P':
				return keyEv(KeyF1, 0), used, false
			case 'Q':
				return keyEv(KeyF2, 0), used, false
			case 'R':
				return keyEv(KeyF3, 0), used, false
			case 'S':
				return keyEv(KeyF4, 0), used, false
			case 'M':
				return keyEv(KeyEnter, 0), used, false
			}
			return nil, used, false
		}
		if b[1] == 0x1b {
			// ESC ESC -> escape, then continue
			return keyEv(KeyEsc, 0), 1, false
		}
		// alt + key
		sub, u, inc := parseInput(b[1:])
		if inc {
			return nil, 0, true
		}
		if sub != nil && sub.Type == EvKey {
			sub.Key.Mod |= ModAlt
		}
		return sub, u + 1, false
	}
	switch {
	case c == 0x0d || c == 0x0a:
		return keyEv(KeyEnter, 0), 1, false
	case c == 0x09:
		return keyEv(KeyTab, 0), 1, false
	case c == 0x7f || c == 0x08:
		return keyEv(KeyBackspace, 0), 1, false
	case c == 0x00:
		return &Event{Type: EvKey, Key: Key{Code: KeyCtrl, Ch: ' '}}, 1, false
	case c < 0x20:
		var ch rune
		switch {
		case c >= 1 && c <= 26:
			ch = rune('a' + c - 1)
		case c == 0x1c:
			ch = '\\'
		case c == 0x1d:
			ch = ']'
		case c == 0x1e:
			ch = '^'
		case c == 0x1f:
			ch = '_'
		}
		return &Event{Type: EvKey, Key: Key{Code: KeyCtrl, Ch: ch}}, 1, false
	}
	if !utf8.FullRune(b) {
		return nil, 0, true
	}
	r, size := utf8.DecodeRune(b)
	return &Event{Type: EvKey, Key: Key{Code: KeyRune, Ch: r}}, size, false
}
EOF

