{"command":"cd /workspace/src; cat > screen.go <<'EOF'
package main

import (
	"math"
	"strconv"
	"strings"
)

type Color int32

const (
	ColorDefault Color = -1
	colorRGBFlag Color = 1 << 25
)

const (
	ColBlack Color = iota
	ColRed
	ColGreen
	ColYellow
	ColBlue
	ColMagenta
	ColCyan
	ColWhite
)

func RGB(r, g, b int) Color {
	return colorRGBFlag | Color(r<<16|g<<8|b)
}

func (c Color) isRGB() bool { return c >= 0 && c&colorRGBFlag != 0 }

func (c Color) rgb() (int, int, int) {
	if c.isRGB() {
		v := int(c &^ colorRGBFlag)
		return v >> 16 & 0xff, v >> 8 & 0xff, v & 0xff
	}
	if c >= 0 && c < 256 {
		return paletteRGB(int(c))
	}
	return 0, 0, 0
}

type Attr uint16

const (
	AttrBold Attr = 1 << iota
	AttrDim
	AttrItalic
	AttrUnderline
	AttrBlink
	AttrReverse
	AttrStrike
)

type Cell struct {
	Ch   rune // 0 => continuation of wide char
	Fg   Color
	Bg   Color
	Attr Attr
}

var blankCell = Cell{Ch: ' ', Fg: ColorDefault, Bg: ColorDefault}

type Screen struct {
	W, H  int
	cells []Cell
}

func NewScreen(w, h int) *Screen {
	s := &Screen{W: w, H: h, cells: make([]Cell, w*h)}
	s.Clear()
	return s
}

func (s *Screen) Clear() {
	for i := range s.cells {
		s.cells[i] = blankCell
	}
}

func (s *Screen) Set(x, y int, c Cell) {
	if x < 0 || y < 0 || x >= s.W || y >= s.H {
		return
	}
	i := y*s.W + x
	// if overwriting the second half of a wide char, blank the first half
	if s.cells[i].Ch == 0 && x > 0 {
		p := s.cells[i-1]
		p.Ch = ' '
		s.cells[i-1] = p
	}
	// if overwriting the first half of a wide char, blank the continuation
	if x+1 < s.W && s.cells[i+1].Ch == 0 && runeWidth(s.cells[i].Ch) == 2 {
		n := s.cells[i+1]
		n.Ch = ' '
		s.cells[i+1] = n
	}
	s.cells[i] = c
	if runeWidth(c.Ch) == 2 {
		if x+1 < s.W {
			cont := c
			cont.Ch = 0
			s.cells[i+1] = cont
		} else {
			s.cells[i].Ch = ' '
		}
	}
}

func (s *Screen) Get(x, y int) Cell {
	if x < 0 || y < 0 || x >= s.W || y >= s.H {
		return blankCell
	}
	return s.cells[y*s.W+x]
}

// ---- palette & color conversion ----

var basePalette = [16][3]int{
	{0, 0, 0}, {128, 0, 0}, {0, 128, 0}, {128, 128, 0}, {0, 0, 128}, {128, 0, 128}, {0, 128, 128}, {192, 192, 192},
	{128, 128, 128}, {255, 0, 0}, {0, 255, 0}, {255, 255, 0}, {0, 0, 255}, {255, 0, 255}, {0, 255, 255}, {255, 255, 255},
}

func paletteRGB(i int) (int, int, int) {
	if i < 16 {
		p := basePalette[i]
		return p[0], p[1], p[2]
	}
	if i < 232 {
		i -= 16
		lv := []int{0, 95, 135, 175, 215, 255}
		return lv[i/36], lv[(i/6)%6], lv[i%6]
	}
	v := 8 + (i-232)*10
	return v, v, v
}

func srgbLin(v float64) float64 {
	if v <= 0.04045 {
		return v / 12.92
	}
	return math.Pow((v+0.055)/1.055, 2.4)
}

func toLab(r, g, b int) (float64, float64, float64) {
	rl, gl, bl := srgbLin(float64(r)/255), srgbLin(float64(g)/255), srgbLin(float64(b)/255)
	x := 0.4124564*rl + 0.3575761*gl + 0.1804375*bl
	y := 0.2126729*rl + 0.7151522*gl + 0.0721750*bl
	z := 0.0193339*rl + 0.1191920*gl + 0.9503041*bl
	f := func(t float64) float64 {
		if t > 6.0/29*6.0/29*6.0/29 {
			return math.Cbrt(t)
		}
		return t/3*29/6*29/6 + 4.0/29
	}
	fx, fy, fz := f(x/0.95047), f(y/1.0), f(z/1.08883)
	return 1.16*fy - 0.16, 5 * (fx - fy), 2 * (fy - fz)
}

var findColorCache = map[[2]int]Color{}

func findColor(c Color, ncolors int) Color {
	key := [2]int{int(c), ncolors}
	if v, ok := findColorCache[key]; ok {
		return v
	}
	r, g, b := c.rgb()
	l1, a1, b1 := toLab(r, g, b)
	best := Color(0)
	bestD := math.Inf(1)
	for i := 0; i < ncolors && i < 256; i++ {
		pr, pg, pb := paletteRGB(i)
		l2, a2, b2 := toLab(pr, pg, pb)
		d := math.Sqrt((l1-l2)*(l1-l2) + (a1-a2)*(a1-a2) + (b1-b2)*(b1-b2))
		if d < bestD {
			bestD = d
			best = Color(i)
		}
	}
	findColorCache[key] = best
	return best
}

func (t *Terminal) colorCode(c Color, fg bool) string {
	if c == ColorDefault || c < 0 {
		if fg {
			return "39"
		}
		return "49"
	}
	n := t.colors
	if c.isRGB() {
		if n >= 1<<24 {
			r, g, b := c.rgb()
			p := "38;2;"
			if !fg {
				p = "48;2;"
			}
			return p + strconv.Itoa(r) + ";" + strconv.Itoa(g) + ";" + strconv.Itoa(b)
		}
		if n <= 0 {
			if fg {
				return "39"
			}
			return "49"
		}
		c = findColor(c, minInt(n, 256))
	} else if int(c) >= n && n < 256 {
		if n <= 0 {
			if fg {
				return "39"
			}
			return "49"
		}
		c = findColor(c, n)
	}
	i := int(c)
	if i < 8 {
		if fg {
			return strconv.Itoa(30 + i)
		}
		return strconv.Itoa(40 + i)
	}
	if i < 16 && n >= 16 {
		if fg {
			return strconv.Itoa(90 + i - 8)
		}
		return strconv.Itoa(100 + i - 8)
	}
	if fg {
		return "38;5;" + strconv.Itoa(i)
	}
	return "48;5;" + strconv.Itoa(i)
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func (t *Terminal) sgr(c Cell) string {
	var b strings.Builder
	b.WriteString("\x1b[0")
	if c.Attr&AttrBold != 0 {
		b.WriteString(";1")
	}
	if c.Attr&AttrDim != 0 {
		b.WriteString(";2")
	}
	if c.Attr&AttrItalic != 0 {
		b.WriteString(";3")
	}
	if c.Attr&AttrUnderline != 0 {
		b.WriteString(";4")
	}
	if c.Attr&AttrBlink != 0 {
		b.WriteString(";5")
	}
	if c.Attr&AttrReverse != 0 {
		b.WriteString(";7")
	}
	if c.Attr&AttrStrike != 0 {
		b.WriteString(";9")
	}
	if c.Fg != ColorDefault {
		b.WriteString(";" + t.colorCode(c.Fg, true))
	}
	if c.Bg != ColorDefault {
		b.WriteString(";" + t.colorCode(c.Bg, false))
	}
	b.WriteString("m")
	return b.String()
}

// Flush draws the differences between prev and cur to the terminal.
func (t *Terminal) Flush(prev, cur *Screen, full bool, cursorX, cursorY int, showCursor bool) {
	out := t.out
	if full || prev == nil || prev.W != cur.W || prev.H != cur.H {
		out.WriteString("\x1b[0m\x1b[H\x1b[2J")
		prev = nil
	}
	lastAttr := ""
	out.WriteString("\x1b[?25l")
	for y := 0; y < cur.H; y++ {
		x := 0
		cursorAt := -1
		for x < cur.W {
			c := cur.cells[y*cur.W+x]
			if prev != nil {
				p := prev.cells[y*cur.W+x]
				if p == c {
					x++
					continue
				}
			}
			if c.Ch == 0 {
				x++
				continue
			}
			if cursorAt != x {
				out.WriteString("\x1b[" + strconv.Itoa(y+1) + ";" + strconv.Itoa(x+1) + "H")
			}
			a := t.sgr(c)
			if a != lastAttr {
				out.WriteString(a)
				lastAttr = a
			}
			w := runeWidth(c.Ch)
			if w == 2 && x+1 >= cur.W {
				out.WriteRune(' ')
				w = 1
			} else {
				out.WriteRune(c.Ch)
			}
			if w < 1 {
				w = 1
			}
			x += w
			cursorAt = x
		}
	}
	out.WriteString("\x1b[0m")
	if showCursor {
		out.WriteString("\x1b[" + strconv.Itoa(cursorY+1) + ";" + strconv.Itoa(cursorX+1) + "H\x1b[?25h")
	}
	out.Flush()
}
EOF"}

