func applySGR(cur *Cell, params string) {
	if params == "" {
		cur.Fg, cur.Bg, cur.Attr = ColorDefault, ColorDefault, 0
		return
	}
	ps := strings.FieldsFunc(params, func(r rune) bool { return r == ';' || r == ':' })
	for k := 0; k < len(ps); k++ {
		n, err := strconv.Atoi(ps[k])
		if err != nil {
			continue
		}
		switch {
		case n == 0:
			cur.Fg, cur.Bg, cur.Attr = ColorDefault, ColorDefault, 0
		case n == 1:
			cur.Attr |= AttrBold
		case n == 2:
			cur.Attr |= AttrDim
		case n == 3:
			cur.Attr |= AttrItalic
		case n == 4:
			cur.Attr |= AttrUnderline
		case n == 5 || n == 6:
			cur.Attr |= AttrBlink
		case n == 7:
			cur.Attr |= AttrReverse
		case n == 9:
			cur.Attr |= AttrStrike
		case n == 21 || n == 22:
			cur.Attr &^= AttrBold | AttrDim
		case n == 23:
			cur.Attr &^= AttrItalic
		case n == 24:
			cur.Attr &^= AttrUnderline
		case n == 25:
			cur.Attr &^= AttrBlink
		case n == 27:
			cur.Attr &^= AttrReverse
		case n == 29:
