				for j < len(s) && ((s[j] >= '0' && s[j] <= '9') || s[j] == ';' || s[j] == ':' || s[j] == '?' || s[j] == '<' || s[j] == '>') {
					j++
				}
				if j < len(s) {
					if s[j] == 'm' {
						applySGR(&cur, s[i+2:j])
					}
					i = j + 1
					continue
				}
				i = len(s)
				continue
			}
			if i+1 < len(s) && s[i+1] == ']' {
				// OSC: skip until BEL or ST
				j := i + 2
				for j < len(s) {
					if s[j] == 0x07 {
						j++
						break
					}
					if s[j] == 0x1b && j+1 < len(s) && s[j+1] == '\\' {
						j += 2
						break
					}
					j++
				}
				i = j
				continue
			}
			i++
			continue
		}
		if c == '\t' {
			if tabWidth <= 0 {
				tabWidth = 4
			}
			n := tabWidth - col%tabWidth
			for k := 0; k < n; k++ {
				cc := cur
				cc.Ch = ' '
				cells = append(cells, cc)
				col++
			}
			i++
			continue
		}
		if c == '\r' {
			i++
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		i += size
		if r < 0x20 && r != '\t' {
			continue
		}
		w := runeWidth(r)
		if w == 0 {
			// combining: skip (approximation)
			continue
		}
		cc := cur
		cc.Ch = r
		cells = append(cells, cc)
		col++
		if w == 2 {
			cont := cur
			cont.Ch = 0
			cells = append(cells, cont)
			col++
		}
	}
	return cells
}

func applySGR(cur *Cell, params string) {
	if params == "" {
		cur.Fg, cur.Bg, cur.Attr = ColorDefault, ColorDefault, 0
		return
	}
	ps := strings.FieldsFunc(params, func(r rune) bool { return r == ';' || r == ':' })
	for k := 0; k < len(ps); k++ {
		n, err := strconv.Atoi(ps[k])
		if err != nil {
			continue
		}
		switch {
		case n == 0:
			cur.Fg, cur.Bg, cur.Attr = ColorDefault, ColorDefault, 0
		case n == 1:
			cur.Attr |= AttrBold
		case n == 2:
			cur.Attr |= AttrDim
		case n == 3:
			cur.Attr |= AttrItalic
		case n == 4:
			cur.Attr |= AttrUnderline
		case n == 5 || n == 6:
			cur.Attr |= AttrBlink
		case n == 7:
			cur.Attr |= AttrReverse
		case n == 9:
			cur.Attr |= AttrStrike
		case n == 21 || n == 22:
			cur.Attr &^= AttrBold | AttrDim
		case n == 23:
			cur.Attr &^= AttrItalic
		case n == 24:
			cur.Attr &^= AttrUnderline
		case n == 25:
			cur.Attr &^= AttrBlink
		case n == 27:
			cur.Attr &^= AttrReverse
		case n == 29:
			cur.Attr &^= AttrStrike
		case n >= 30 && n <= 37:
			cur.Fg = Color(n - 30)
		case n == 39:
			cur.Fg = ColorDefault
		case n >= 40 && n <= 47:
			cur.Bg = Color(n - 40)
		case n == 49:
			cur.Bg = ColorDefault
		case n >= 90 && n <= 97:
			cur.Fg = Color(n - 90 + 8)
		case n >= 100 && n <= 107:
			cur.Bg = Color(n - 100 + 8)
		case n == 38 || n == 48:
			var col Color = ColorDefault
			if k+1 < len(ps) && ps[k+1] == "5" && k+2 < len(ps) {
				v, _ := strconv.Atoi(ps[k+2])
				col = Color(v)
				k += 2
			} else if k+1 < len(ps) && ps[k+1] == "2" && k+4 < len(ps) {
				r, _ := strconv.Atoi(ps[k+2])
				g, _ := strconv.Atoi(ps[k+3])
				b, _ := strconv.Atoi(ps[k+4])
				col = RGB(r, g, b)
				k += 4
			}
			if n == 38 {
				cur.Fg = col
			} else {
				cur.Bg = col
			}
		}
	}
}

// decolorise strips ANSI escapes.
func decolorise(s string) string {
	if !strings.Contains(s, "\x1b") {
		return s
	}
	var b strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == 0x1b && i+1 < len(s) && s[i+1] == '[' {
			j := i + 2
			for j < len(s) && !((s[j] >= 0x40 && s[j] <= 0x7e)) {
				j++
			}
			i = j + 1
			continue
		}
		if s[i] == 0x1b && i+1 < len(s) && s[i+1] == ']' {
			j := i + 2
			for j < len(s) {
				if s[j] == 0x07 {
					j++
					break
				}
				if s[j] == 0x1b && j+1 < len(s) && s[j+1] == '\\' {
					j += 2
					break
				}
				j++
			}
			i = j
			continue
		}
		b.WriteByte(s[i])
		i++
	}
	return b.String()
}

func visibleWidth(s string) int {
	return stringWidth(decolorise(s))
}
