	var lines [][]Cell
	n := 0
	offset := 0
	lastWS := -1
	for i := 0; i < len(line); i++ {
		ch := line[i].Ch
		if ch == 0 {
			continue
		}
		rw := runeWidth(ch)
		n += rw
		if n > columns {
			if ch == ' ' {
				lines = append(lines, line[offset:i])
				offset = i + 1
				n = 0
			} else if lastWS != -1 && lastWS+1 != i {
				lines = append(lines, line[offset:lastWS])
				offset = lastWS + 1
				n = 0
				for _, c := range line[offset : i+1] {
					if c.Ch != 0 {
						n += runeWidth(c.Ch)
					}
				}
			} else {
				lines = append(lines, line[offset:i])
				offset = i
				n = rw
