	if !v.wrapDirty && v.wrapWidth == w && v.wrapCache != nil {
		return v.wrapCache, flattenSrc(v.wrapSrc)
	}
	var out [][]Cell
	var src [][]int
	for i, l := range v.lines {
		for _, wl := range lineWrap(l, w) {
			out = append(out, wl)
			src = append(src, []int{i})
		}
	}
	v.wrapCache = out
	v.wrapSrc = src
	v.wrapWidth = w
	v.wrapDirty = false
	return out, flattenSrc(src)
}

func flattenSrc(s [][]int) []int {
	r := make([]int, len(s))
	for i, x := range s {
		r[i] = x[0]
	}
	return r
}

func (v *View) ViewLinesHeight() int {
	l, _ := v.viewLines()
	return len(l)
}

func lineWrap(line []Cell, columns int) [][]Cell {
	if columns <= 0 {
		return [][]Cell{line}
	}
	var lines [][]Cell
	n := 0
	offset := 0
	lastWS := -1
	for i := 0; i < len(line); i++ {
		ch := line[i].Ch
		if ch == 0 {
			continue
		}
		rw := runeWidth(ch)
		n += rw
		if n > columns {
			if ch == ' ' {
				lines = append(lines, line[offset:i])
				offset = i + 1
				n = 0
			} else if lastWS != -1 && lastWS+1 != i {
				lines = append(lines, line[offset:lastWS])
				offset = lastWS + 1
				n = 0
				for _, c := range line[offset : i+1] {
					if c.Ch != 0 {
						n += runeWidth(c.Ch)
					}
				}
			} else {
				lines = append(lines, line[offset:i])
				offset = i
				n = rw
			}
			lastWS = -1
		} else if ch == ' ' {
			lastWS = i
		}
	}
	lines = append(lines, line[offset:])
	return lines
}

// wrapString wraps a plain string similarly (used for computing popup heights).
func wrapStringLines(s string, width int) []string {
	var res []string
	for _, l := range strings.Split(s, "\n") {
		cells := parseANSILine(l, 4)
		for _, wl := range lineWrap(cells, width) {
			var b strings.Builder
			for _, c := range wl {
				if c.Ch != 0 {
					b.WriteRune(c.Ch)
				}
			}
			res = append(res, b.String())
		}
	}
	return res
}

// draw renders the view onto the screen.
func (v *View) draw(s *Screen, activeTitle bool) {
	if !v.Visible {
		return
	}
	if v.X1 < v.X0 || v.Y1 < v.Y0 {
		return
	}
	iw, ih := v.InnerWidth(), v.InnerHeight()
	lines, src := v.viewLines()
	// content area
	for y := 0; y < ih; y++ {
		li := y + v.OY
		var line []Cell
		srcLine := -1
		if li >= 0 && li < len(lines) {
			line = lines[li]
			srcLine = src[li]
		}
		selected := v.Highlight && srcLine >= 0 && v.isSelected(srcLine)
		x := 0
		for ci := v.OX; ci < len(line) && x < iw; ci++ {
			c := line[ci]
			if c.Ch == 0 {
				if ci == v.OX {
					x++ // half of wide char cut off
				}
				continue
			}
			if c.Fg == ColorDefault {
				c.Fg = v.FgColor
			}
			if c.Bg == ColorDefault {
				c.Bg = v.BgColor
			}
			if selected {
				c.Bg = v.SelBg
				c.Attr |= v.SelAttr
			}
			if v.Mask != 0 {
				c.Ch = v.Mask
			}
			w := runeWidth(c.Ch)
			if x+w > iw {
				break
			}
			s.Set(v.X0+1+x, v.Y0+1+y, c)
			x += w
		}
		for ; x < iw; x++ {
			c := Cell{Ch: ' ', Fg: v.FgColor, Bg: v.BgColor}
			if selected {
				c.Bg = v.SelBg
				c.Attr |= v.SelAttr
			}
			s.Set(v.X0+1+x, v.Y0+1+y, c)
		}
	}
	if v.Frame {
		v.drawFrame(s, len(lines), ih)
	}
}

func (v *View) isSelected(line int) bool {
	if v.RangeStart >= 0 {
		a, b := v.RangeStart, v.RangeEnd
		if a > b {
			a, b = b, a
		}
		return line >= a && line <= b
	}
	return line == v.SelLine
}

func (v *View) drawFrame(s *Screen, contentLines, ih int) {
	fg := Cell{Fg: v.FrameFg, Bg: ColorDefault, Attr: v.FrameAttr}
	set := func(x, y int, r rune) {
		c := fg
		c.Ch = r
		s.Set(x, y, c)
	}
	h, vv := '─', '│'
	tl, tr, bl, br := '╭', '╮', '╰', '╯'
	switch borderStyle {
	case "single":
		tl, tr, bl, br = '┌', '┐', '└', '┘'
	case "double":
		h, vv = '═', '║'
		tl, tr, bl, br = '╔', '╗', '╚', '╝'
	case "bold":
		h, vv = '━', '┃'
		tl, tr, bl, br = '┏', '┓', '┗', '┛'
	case "hidden":
		h, vv = ' ', ' '
		tl, tr, bl, br = ' ', ' ', ' ', ' '
	}
	for x := v.X0 + 1; x < v.X1; x++ {
		set(x, v.Y0, h)
		set(x, v.Y1, h)
	}
	sbStart, sbEnd, showSB := v.scrollbarRange(contentLines, ih)
	for y := v.Y0 + 1; y < v.Y1; y++ {
		set(v.X0, y, vv)
		if showSB && y >= sbStart && y <= sbEnd {
			set(v.X1, y, '▐')
		} else {
			set(v.X1, y, vv)
		}
	}
	if v.X1 > v.X0 && v.Y1 > v.Y0 {
		set(v.X0, v.Y0, tl)
		set(v.X1, v.Y0, tr)
		set(v.X0, v.Y1, bl)
		set(v.X1, v.Y1, br)
	} else if v.Y1 == v.Y0 && v.X1 > v.X0 {
		set(v.X0, v.Y0, h)
		set(v.X1, v.Y0, h)
	}
	v.drawTitle(s)
	v.drawSubtitle(s)
	v.drawFooter(s)
}

func (v *View) scrollbarRange(contentLines, ih int) (int, int, bool) {
	if !v.Scrollbar {
		return 0, 0, false
	}
	height := ih
	full := contentLines
	if v.CanScrollPastBottom {
		full += height - 2
	}
	if height < 2 || height >= full {
		return 0, 0, false
	}
	start, sbh := calcScrollbar(full, height, v.OY, height-1)
	top := v.Y0 + 1
	return top + start, top + start + sbh, true
}

func calcScrollbar(listSize, pageSize, position, scrollAreaSize int) (int, int) {
	height := calcScrollbarHeight(listSize, pageSize, scrollAreaSize)
	maxPosition := listSize - pageSize
	if maxPosition <= 0 {
		return 0, height
	}
	if position >= maxPosition {
		return scrollAreaSize - height, height
	}
	start := int(math.Ceil((float64(position) / float64(maxPosition)) * float64(scrollAreaSize-height-1)))
	return start, height
}

func calcScrollbarHeight(listSize, pageSize, scrollAreaSize int) int {
	if pageSize >= listSize {
		return scrollAreaSize
	}
	return int((float64(pageSize) / float64(listSize)) * float64(scrollAreaSize))
}

func (v *View) drawTitle(s *Screen) {
	if v.Title == "" && len(v.Tabs) == 0 && v.TitlePrefix == "" {
		return
	}
	frameCell := Cell{Fg: v.FrameFg, Bg: ColorDefault, Attr: v.FrameAttr}
	x := v.X0 + 2
	put := func(ch rune, c Cell) bool {
		if x > v.X1-2 {
			return false
		}
		c.Ch = ch
		s.Set(x, v.Y0, c)
		x += maxInt(1, runeWidth(ch))
		return true
	}
	if v.TitlePrefix != "" {
		for _, ch := range v.TitlePrefix + "─" {
			if !put(ch, frameCell) {
				return
			}
		}
	}
	tabs := v.Tabs
	start, end := -1, -1
	if len(tabs) == 0 {
		tabs = []string{v.Title}
	} else {
		idx := 0
		for i, t := range tabs {
			if i == v.TabIndex {
				start = idx
				end = idx + len([]rune(t))
				break
			}
			idx += len([]rune(t)) + 3
		}
	}
	str := strings.Join(tabs, " - ")
	i := 0
	for _, ch := range str {
		c := frameCell
		if v.Focused && len(v.Tabs) > 0 {
			c = Cell{Fg: v.FgColor, Bg: ColorDefault}
		}
		if i >= start && i <= end {
			c = Cell{Fg: v.TabSelFg, Bg: ColorDefault, Attr: v.TabSelAttr}
			if !v.Focused {
				c.Attr &^= AttrBold
			}
		}
		if !put(ch, c) {
			return
		}
		i++
	}
}

func (v *View) drawSubtitle(s *Screen) {
	if v.Subtitle == "" {
		return
	}
	w := stringWidth(v.Subtitle)
	start := v.X1 - 1 - w
	if start < v.X0 {
		return
	}
	x := start
	for _, ch := range v.Subtitle {
		if x >= v.X1 {
			break
		}
		s.Set(x, v.Y0, Cell{Ch: ch, Fg: v.FrameFg, Bg: ColorDefault, Attr: v.FrameAttr})
		x += maxInt(1, runeWidth(ch))
	}
}

func (v *View) drawFooter(s *Screen) {
	if v.Footer == "" {
		return
	}
	w := stringWidth(v.Footer)
	start := v.X1 - 1 - w
	if start < v.X0 {
		return
	}
	x := start
	for _, ch := range v.Footer {
		if x >= v.X1 {
			break
		}
		s.Set(x, v.Y1, Cell{Ch: ch, Fg: v.FrameFg, Bg: ColorDefault, Attr: v.FrameAttr})
		x++
	}
}

var borderStyle = "rounded"
EOF

