	ConditionalDirection func(width, height int) int
	Window              string
	Size                int
	Weight              int
}

func (b *Box) isStatic() bool { return b.Size > 0 }

func ArrangeWindows(root *Box, x0, y0, width, height int) map[string]Dimensions {
