		avail = width
	} else {
		avail = height
	}
	sizes := calcSizes(children, avail)
	result := map[string]Dimensions{}
	offset := 0
	for i, child := range children {
		boxSize := sizes[i]
		var res map[string]Dimensions
		if direction == COLUMN {
