		} else {
			res = ArrangeWindows(child, x0, y0+offset, width, boxSize)
		}
		for k, v := range res {
			result[k] = v
		}
		offset += boxSize
	}
	return result
}

func (b *Box) getDirection(w, h int) int {
	if b.ConditionalDirection != nil {
		return b.ConditionalDirection(w, h)
	}
	return b.Direction
}

func (b *Box) getChildren(w, h int) []*Box {
	if b.ConditionalChildren != nil {
		return b.ConditionalChildren(w, h)
	}
	return b.Children
}

func calcSizes(boxes []*Box, availableSpace int) []int {
	weights := make([]int, len(boxes))
	for i, b := range boxes {
		weights[i] = b.Weight
	}
	normalized := normalizeWeights(weights)
	totalWeight := 0
	reserved := 0
	for i, b := range boxes {
		if b.isStatic() {
			reserved += b.Size
		} else {
			totalWeight += normalized[i]
		}
	}
	dynamic := availableSpace - reserved
	if dynamic < 0 {
		dynamic = 0
	}
	unit, extra := 0, 0
	if totalWeight > 0 {
		unit = dynamic / totalWeight
		extra = dynamic % totalWeight
	}
	result := make([]int, len(boxes))
	for i, b := range boxes {
		if b.isStatic() {
			result[i] = minInt(availableSpace, b.Size)
		} else {
			result[i] = unit * normalized[i]
		}
	}
	for extra > 0 {
		progressed := false
		for i, w := range normalized {
			if w > 0 && !boxes[i].isStatic() {
				result[i]++
				extra--
				normalized[i]--
				progressed = true
				if extra == 0 {
					break
				}
			}
		}
		if !progressed {
			break
		}
	}
	return result
}

func normalizeWeights(weights []int) []int {
	if len(weights) == 0 {
		return weights
	}
	for _, w := range weights {
		if w == 1 {
			return append([]int{}, weights...)
		}
	}
	var positive []int
	for _, w := range weights {
		if w > 0 {
			positive = append(positive, w)
		}
	}
	if len(positive) == 0 {
		return append([]int{}, weights...)
	}
	common := factors(positive[0])
	for _, w := range positive[1:] {
		f := factors(w)
		var inter []int
		for _, a := range common {
			for _, b := range f {
				if a == b {
					inter = append(inter, a)
					break
				}
			}
		}
		common = inter
	}
	if len(common) == 0 {
		return append([]int{}, weights...)
	}
	nw := make([]int, len(weights))
	for i, w := range weights {
		nw[i] = w / common[0]
	}
	return normalizeWeights(nw)
}

func factors(n int) []int {
	var res []int
	for i := 2; i <= n; i++ {
		if n%i == 0 {
			res = append(res, i)
		}
	}
	return res
}
