cd /workspace/src; cat > git.go <<'EOF'
package main

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"
)

type File struct {
	Name               string
	PreviousName       string
	HasStagedChanges   bool
	HasUnstagedChanges bool
	Tracked            bool
	Added              bool
	Deleted            bool
	HasMergeConflicts  bool
	HasInlineConflicts bool
	ShortStatus        string
	IsWorktree         bool
	IsSubmodule        bool
}

func (f *File) IsRename() bool { return f.PreviousName != "" }

type Branch struct {
	Name         string
	Head         bool
	Upstream     string // e.g. origin/main
	UpstreamGone bool
	Ahead        string
	Behind       string
	Recency      string
	CommitHash   string
	Subject      string
	CommitTime   int64
	DetachedHead bool
	UpstreamRemote string
	UpstreamBranch string
	CheckoutTime int64
	WorktreePath string
}

func (b *Branch) IsTrackingRemote() bool { return b.Upstream != "" }

type Commit struct {
	Hash          string
	Name          string
	Status        string // "unpushed", "pushed", "merged", "rebasing", "reflog"
	Action        string
	Tags          []string
	ExtraInfo     string // decorations
	AuthorName    string
	AuthorEmail   string
	UnixTimestamp int64
	Parents       []string
	Divergence    int
	IsHead        bool
	Refs          string
}

func (c *Commit) ShortHash() string {
	if len(c.Hash) > 7 {
		return c.Hash[:7]
	}
	return c.Hash
}

func (c *Commit) IsMerge() bool { return len(c.Parents) > 1 }

type StashEntry struct {
	Index   int
	Recency string
	Name    string
	Hash    string
	Time    int64
}

func (s *StashEntry) RefName() string { return "stash@{" + strconv.Itoa(s.Index) + "}" }

type Remote struct {
	Name     string
	Urls     []string
	Branches []*RemoteBranch
}

type RemoteBranch struct {
	Name       string
	RemoteName string
}

func (r *RemoteBranch) FullName() string { return r.RemoteName + "/" + r.Name }

type Tag struct {
	Name        string
	Message     string
	IsAnnotated bool
	Hash        string
}

type Worktree struct {
	Path     string
	IsMain   bool
	IsCurrent bool
	Branch   string
	Head     string
	Name     string
	IsPathMissing bool
	GitDir   string
}

type Submodule struct {
	Name string
	Path string
	Url  string
}

type Git struct {
	repoRoot  string
	gitDir    string
	extraArgs []string
}

func gitCmd(args ...string) *exec.Cmd {
	cmd := exec.Command("git", args...)
	cmd.Env = append(os.Environ(), "GIT_OPTIONAL_LOCKS=0", "LC_ALL=en_US.UTF-8", "LANG=en_US.UTF-8")
	return cmd
}

func runGit(args ...string) (string, error) {
	cmd := gitCmd(args...)
	var out, errb bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &errb
	err := cmd.Run()
	if err != nil {
		msg := strings.TrimSpace(errb.String())
		if msg == "" {
			msg = strings.TrimSpace(out.String())
		}
		if msg == "" {
			msg = err.Error()
		}
		return out.String(), &gitError{msg: msg}
	}
	return out.String(), nil
}

func runGitCombined(args ...string) (string, error) {
	cmd := gitCmd(args...)
	out, err := cmd.CombinedOutput()
	if err != nil {
		msg := strings.TrimSpace(string(out))
		if msg == "" {
			msg = err.Error()
		}
		return string(out), &gitError{msg: msg}
	}
	return string(out), nil
}

type gitError struct{ msg string }

func (e *gitError) Error() string { return e.msg }

func gitOut(args ...string) string {
	s, _ := runGit(args...)
	return s
}

func trimNL(s string) string { return strings.TrimRight(s, "\r\n") }

// ----- loaders -----

func loadFiles(renameThreshold int) []*File {
	out, err := runGit("status", "--untracked-files=all", "--porcelain", "-z", "--find-renames="+strconv.Itoa(renameThreshold)+"%")
	if err != nil {
		return nil
	}
	parts := strings.Split(out, "\x00")
	var files []*File
	for i := 0; i < len(parts); i++ {
		p := parts[i]
		if len(p) < 4 {
			continue
		}
		change := p[:2]
		name := p[3:]
		prev := ""
		if change[0] == 'R' || change[0] == 'C' || change[1] == 'R' || change[1] == 'C' {
			if i+1 < len(parts) {
				prev = parts[i+1]
				i++
			}
		}
		staged := change[0:1]
		unstaged := change[1:2]
		untracked := change == "??" || change == "A " || change == "AM"
		noStaged := staged == " " || staged == "U" || staged == "?"
		inline := change == "UU" || change == "AA"
		conflicts := inline || change == "DD" || change == "AU" || change == "UA" || change == "UD" || change == "DU"
		f := &File{
			Name: name, PreviousName: prev,
			HasStagedChanges:   !noStaged,
			HasUnstagedChanges: unstaged != " ",
			Tracked:            !untracked,
			Deleted:            unstaged == "D" || staged == "D",
			Added:              unstaged == "A" || untracked,
			HasMergeConflicts:  conflicts,
			HasInlineConflicts: inline,
			ShortStatus:        change,
		}
		files = append(files, f)
	}
	return files
}

func currentBranchName() (string, bool) {
	out, err := runGit("symbolic-ref", "-q", "--short", "HEAD")
	if err == nil {
		return trimNL(out), false
	}
	out, _ = runGit("rev-parse", "--short", "HEAD")
	return trimNL(out), true
}

func reflogCheckoutTimes() map[string]int64 {
	out, _ := runGit("-c", "log.showSignature=false", "log", "-g", "--date=unix", "--format=%gd%x00%gs", "HEAD", "--")
	res := map[string]int64{}
	for _, line := range strings.Split(out, "\n") {
		parts := strings.SplitN(line, "\x00", 2)
		if len(parts) != 2 {
			continue
		}
		subj := parts[1]
		if !strings.HasPrefix(subj, "checkout: moving from ") {
			continue
		}
		rest := strings.TrimPrefix(subj, "checkout: moving from ")
		idx := strings.LastIndex(rest, " to ")
		if idx < 0 {
			continue
		}
		to := rest[idx+4:]
		ts := parseReflogTime(parts[0])
		if _, ok := res[to]; !ok {
			res[to] = ts
		}
	}
	return res
}

func parseReflogTime(gd string) int64 {
	i := strings.Index(gd, "@{")
	if i < 0 {
		return 0
	}
	s := strings.TrimSuffix(gd[i+2:], "}")
	n, _ := strconv.ParseInt(s, 10, 64)
	return n
}

func unixToTimeAgo(ts int64) string {
	delta := time.Now().Unix() - ts
	return formatSecondsAgo(delta)
}

func formatSecondsAgo(delta int64) string {
	if delta < 0 {
		delta = 0
	}
	type period struct {
		label  string
		amount int64
	}
	periods := []period{{"s", 1}, {"m", 60}, {"h", 3600}, {"d", 86400}, {"w", 604800}, {"M", 2592000}, {"y", 31536000}}
	for i := 1; i < len(periods); i++ {
		if delta < periods[i].amount {
			return strconv.FormatInt(delta/periods[i-1].amount, 10) + periods[i-1].label
		}
	}
	last := periods[len(periods)-1]
	return strconv.FormatInt(delta/last.amount, 10) + last.label
}

func loadBranches(sortOrder string) []*Branch {
	format := "%(HEAD)%00%(refname:short)%00%(upstream:short)%00%(upstream:track)%00%(subject)%00%(objectname)%00%(committerdate:unix)%00%(worktreepath)"
	args := []string{"for-each-ref", "--format=" + format}
	switch sortOrder {
	case "alphabetical":
		args = append(args, "--sort=refname")
	case "date":
		args = append(args, "--sort=-committerdate")
	default:
		args = append(args, "--sort=-committerdate")
	}
	args = append(args, "refs/heads")
	out, _ := runGit(args...)
	checkouts := reflogCheckoutTimes()
	var branches []*Branch
	var head *Branch
	for _, line := range strings.Split(trimNL(out), "\n") {
		if line == "" {
			continue
		}
		p := strings.Split(line, "\x00")
		for len(p) < 8 {
			p = append(p, "")
		}
		b := &Branch{Name: p[1], Head: p[0] == "*", Upstream: p[2], Subject: p[4], CommitHash: p[5], WorktreePath: p[7]}
		b.CommitTime, _ = strconv.ParseInt(p[6], 10, 64)
		track := p[3]
		if track == "[gone]" {
			b.UpstreamGone = true
		} else if b.Upstream != "" {
			b.Ahead, b.Behind = "0", "0"
			t := strings.Trim(track, "[]")
			for _, part := range strings.Split(t, ", ") {
				if strings.HasPrefix(part, "ahead ") {
					b.Ahead = strings.TrimPrefix(part, "ahead ")
				} else if strings.HasPrefix(part, "behind ") {
					b.Behind = strings.TrimPrefix(part, "behind ")
				}
			}
		}
		if b.Upstream != "" {
			if i := strings.Index(b.Upstream, "/"); i >= 0 {
				b.UpstreamRemote = b.Upstream[:i]
				b.UpstreamBranch = b.Upstream[i+1:]
			}
		}
		if t, ok := checkouts[b.Name]; ok {
			b.CheckoutTime = t
			b.Recency = unixToTimeAgo(t)
		}
		if b.Head {
			head = b
			continue
		}
		branches = append(branches, b)
	}
	if sortOrder == "recency" {
		sort.SliceStable(branches, func(i, j int) bool {
			ti, tj := branches[i].CheckoutTime, branches[j].CheckoutTime
			if (ti == 0) != (tj == 0) {
				return ti != 0
			}
			return ti > tj
		})
	}
	if head == nil {
		// detached head or no commits
		name, detached := currentBranchName()
		if detached {
			out, _ := runGit("rev-parse", "HEAD")
			hash := trimNL(out)
			if hash != "" {
				disp := detachedHeadDisplay(hash)
				head = &Branch{Name: disp, Head: true, DetachedHead: true, CommitHash: hash, Recency: "  *"}
			}
		} else if name != "" {
			head = &Branch{Name: name, Head: true}
		}
	}
	if head != nil {
		head.Recency = "  *"
		branches = append([]*Branch{head}, branches...)
	}
	return branches
}

func detachedHeadDisplay(hash string) string {
	// mimic "HEAD detached at <short>"
	short := hash
	if len(short) > 7 {
		short = short[:7]
	}
	// check rebase states
	gd := gitDirPath()
	if b, err := os.ReadFile(filepath.Join(gd, "rebase-merge", "head-name")); err == nil {
		return "(no branch, rebasing " + strings.TrimPrefix(trimNL(string(b)), "refs/heads/") + ")"
	}
	if b, err := os.ReadFile(filepath.Join(gd, "rebase-apply", "head-name")); err == nil {
		return "(no branch, rebasing " + strings.TrimPrefix(trimNL(string(b)), "refs/heads/") + ")"
	}
	if b, err := os.ReadFile(filepath.Join(gd, "BISECT_START")); err == nil {
		return "(no branch, bisect started on " + trimNL(string(b)) + ")"
	}
	return "(HEAD detached at " + short + ")"
}

var cachedGitDir string

func gitDirPath() string {
	if cachedGitDir != "" {
		return cachedGitDir
	}
	out, err := runGit("rev-parse", "--absolute-git-dir")
	if err != nil {
		return ".git"
	}
	cachedGitDir = trimNL(out)
	return cachedGitDir
}

func loadCommits(limit int, ref string, mainBranches []string, all bool, order string) []*Commit {
	args := []string{"-c", "log.showSignature=false", "log", ref}
	if all {
		args = append(args, "--all")
	}
	switch order {
	case "date-order", "author-date-order", "topo-order":
		args = append(args, "--"+order)
	}
	args = append(args, "--oneline", "--pretty=format:+%H%x00%at%x00%aN%x00%ae%x00%D%x00%P%x00%s", "--abbrev=40", "--no-show-signature")
	if limit > 0 {
		args = append(args, "-"+strconv.Itoa(limit))
	}
	args = append(args, "--")
	out, err := runGit(args...)
	if err != nil {
		return nil
	}
	var commits []*Commit
	for _, line := range strings.Split(out, "\n") {
		if !strings.HasPrefix(line, "+") {
			continue
		}
		p := strings.SplitN(line[1:], "\x00", 7)
		if len(p) < 7 {
			continue
		}
		c := &Commit{Hash: p[0], AuthorName: p[2], AuthorEmail: p[3], Refs: p[4], Name: p[6]}
		c.UnixTimestamp, _ = strconv.ParseInt(p[1], 10, 64)
		if p[5] != "" {
			c.Parents = strings.Split(p[5], " ")
		}
		var tags []string
		var extra []string
		for _, r := range strings.Split(p[4], ", ") {
			if r == "" {
				continue
			}
			if strings.HasPrefix(r, "tag: ") {
				tags = append(tags, strings.TrimPrefix(r, "tag: "))
			} else {
				extra = append(extra, r)
			}
			if strings.HasPrefix(r, "HEAD") {
				c.IsHead = true
			}
		}
		c.Tags = tags
		if len(extra) > 0 {
			c.ExtraInfo = "(" + strings.Join(extra, ", ") + ")"
		}
		commits = append(commits, c)
	}
	return commits
}

func loadStash() []*StashEntry {
	out, err := runGit("stash", "list", "-z", "--pretty=%ct|%gs|%H")
	if err != nil {
		return nil
	}
	var res []*StashEntry
	i := 0
	for _, e := range strings.Split(out, "\x00") {
		if e == "" {
			continue
		}
		p := strings.SplitN(e, "|", 3)
		s := &StashEntry{Index: i}
		if len(p) >= 2 {
			s.Time, _ = strconv.ParseInt(p[0], 10, 64)
			s.Recency = unixToTimeAgo(s.Time)
			rest := e[len(p[0])+1:]
			if j := strings.LastIndex(rest, "|"); j >= 0 {
				s.Name = rest[:j]
				s.Hash = rest[j+1:]
			} else {
				s.Name = rest
			}
		} else {
			s.Name = e
		}
		res = append(res, s)
		i++
	}
	return res
}

func loadRemotes() []*Remote {
	out, _ := runGit("remote")
	var remotes []*Remote
	refsOut, _ := runGit("for-each-ref", "--sort=refname", "--format=%(refname)", "refs/remotes")
	refs := strings.Split(trimNL(refsOut), "\n")
	for _, name := range strings.Split(trimNL(out), "\n") {
		if name == "" {
			continue
		}
		r := &Remote{Name: name}
		urlOut, _ := runGit("remote", "get-url", "--all", name)
		for _, u := range strings.Split(trimNL(urlOut), "\n") {
			if u != "" {
				r.Urls = append(r.Urls, u)
			}
		}
		prefix := "refs/remotes/" + name + "/"
		for _, ref := range refs {
			if strings.HasPrefix(ref, prefix) {
				bn := strings.TrimPrefix(ref, prefix)
				if bn == "HEAD" {
					continue
				}
				r.Branches = append(r.Branches, &RemoteBranch{Name: bn, RemoteName: name})
			}
		}
		remotes = append(remotes, r)
	}
	sort.SliceStable(remotes, func(i, j int) bool {
		if remotes[i].Name == "origin" {
			return remotes[j].Name != "origin"
		}
		if remotes[j].Name == "origin" {
			return false
		}
		return strings.ToLower(remotes[i].Name) < strings.ToLower(remotes[j].Name)
	})
	return remotes
}

func loadRemoteBranchesSorted(remote string, order string) []*RemoteBranch {
	sortArg := "--sort=-committerdate"
	if order == "alphabetical" {
		sortArg = "--sort=refname"
	}
	out, _ := runGit("for-each-ref", sortArg, "--format=%(refname)", "refs/remotes/"+remote)
	var res []*RemoteBranch
	prefix := "refs/remotes/" + remote + "/"
	for _, ref := range strings.Split(trimNL(out), "\n") {
		if !strings.HasPrefix(ref, prefix) {
			continue
		}
		bn := strings.TrimPrefix(ref, prefix)
		if bn == "HEAD" {
			continue
		}
		res = append(res, &RemoteBranch{Name: bn, RemoteName: remote})
	}
	return res
}

func loadTags() []*Tag {
	out, _ := runGit("for-each-ref", "--sort=-creatordate", "--format=%(refname)%00%(objecttype)%00%(contents:subject)%00%(objectname)", "refs/tags")
	var tags []*Tag
	for _, line := range strings.Split(trimNL(out), "\n") {
		if line == "" {
			continue
		}
		p := strings.Split(line, "\x00")
		for len(p) < 4 {
			p = append(p, "")
		}
		t := &Tag{Name: strings.TrimPrefix(p[0], "refs/tags/"), IsAnnotated: p[1] == "tag", Message: p[2], Hash: p[3]}
		tags = append(tags, t)
	}
	return tags
}

func loadWorktrees() []*Worktree {
	out, err := runGit("worktree", "list", "--porcelain")
	if err != nil {
		return nil
	}
	cwd, _ := os.Getwd()
	cwdReal, _ := filepath.EvalSymlinks(cwd)
	var res []*Worktree
	var cur *Worktree
	for _, line := range strings.Split(out, "\n") {
		if strings.HasPrefix(line, "worktree ") {
			cur = &Worktree{Path: strings.TrimPrefix(line, "worktree ")}
			cur.IsMain = len(res) == 0
			res = append(res, cur)
		} else if cur != nil && strings.HasPrefix(line, "HEAD ") {
			cur.Head = strings.TrimPrefix(line, "HEAD ")
		} else if cur != nil && strings.HasPrefix(line, "branch ") {
			cur.Branch = strings.TrimPrefix(strings.TrimPrefix(line, "branch "), "refs/heads/")
		}
	}
	for _, w := range res {
		w.Name = filepath.Base(w.Path)
		real, _ := filepath.EvalSymlinks(w.Path)
		if real == cwdReal || w.Path == cwd || isSubdir(cwdReal, real) {
			w.IsCurrent = true
		}
		if _, err := os.Stat(w.Path); err != nil {
			w.IsPathMissing = true
		}
	}
	// only the deepest match is current
	return res
}

func isSubdir(child, parent string) bool {
	if parent == "" {
		return false
	}
	rel, err := filepath.Rel(parent, child)
	return err == nil && !strings.HasPrefix(rel, "..")
}

func loadSubmodules(root string) []*Submodule {
	data, err := os.ReadFile(filepath.Join(root, ".gitmodules"))
	if err != nil {
		return nil
	}
	var res []*Submodule
	var cur *Submodule
	for _, line := range strings.Split(string(data), "\n") {
		l := strings.TrimSpace(line)
		if strings.HasPrefix(l, "[submodule \"") {
			name := strings.TrimSuffix(strings.TrimPrefix(l, "[submodule \""), "\"]")
			cur = &Submodule{Name: name}
			res = append(res, cur)
			continue
		}
		if cur == nil {
			continue
		}
		if kv := strings.SplitN(l, "=", 2); len(kv) == 2 {
			k := strings.TrimSpace(kv[0])
			v := strings.TrimSpace(kv[1])
			switch k {
			case "path":
				cur.Path = v
			case "url":
				cur.Url = v
			}
		}
	}
	return res
}

func loadReflogCommits(limit int) []*Commit {
	args := []string{"-c", "log.showSignature=false", "log", "-g", "--abbrev=40", "--format=+%H%x00%ct%x00%gs%x00%P%x00%aN%x00%ae"}
	if limit > 0 {
		args = append(args, "-"+strconv.Itoa(limit))
	}
	out, err := runGit(args...)
	if err != nil {
		return nil
	}
	var res []*Commit
	for _, line := range strings.Split(out, "\n") {
		if !strings.HasPrefix(line, "+") {
			continue
		}
		p := strings.SplitN(line[1:], "\x00", 6)
		for len(p) < 6 {
			p = append(p, "")
		}
		c := &Commit{Hash: p[0], Name: p[2], Status: "reflog", AuthorName: p[4], AuthorEmail: p[5]}
		c.UnixTimestamp, _ = strconv.ParseInt(p[1], 10, 64)
		if p[3] != "" {
			c.Parents = strings.Split(p[3], " ")
		}
		res = append(res, c)
	}
	return res
}
EOF

