{"command":"cd /workspace/src; cat > layout.go <<'EOF'
package main

const (
	ScreenNormal = iota
	ScreenHalf
	ScreenFull
)

type arrangeArgs struct {
	width, height      int
	currentWindow      string
	currentSideWindow  string
	currentStaticWindow string
	splitMain          bool
	screenMode         int
	appStatus          string
	informationStr     string
	showExtras         bool
	inSearchPrompt     bool
	searchPrefix       string
	isAnyModeActive    bool
	stashAccessed      bool
}

func (g *Gui) midSectionWeights(a *arrangeArgs) (int, int) {
	ratio := g.cfg.SidePanelWidth
	if ratio <= 0 {
		ratio = 0.3333
	}
	mainW := int(1/ratio) - 1
	sideW := 1
	if g.splitMainSideBySide(a) {
		mainW = 5
	}
	if a.currentWindow == "main" || a.currentWindow == "secondary" {
		if a.screenMode == ScreenHalf || a.screenMode == ScreenFull {
			sideW = 0
		}
	} else {
		if a.screenMode == ScreenHalf {
			if g.cfg.EnlargedSideViewLocation == "top" {
				mainW = 2
			} else {
				mainW = 1
			}
		} else if a.screenMode == ScreenFull {
			mainW = 0
		}
	}
	return sideW, mainW
}

func (g *Gui) splitMainSideBySide(a *arrangeArgs) bool {
	if !a.splitMain {
		return false
	}
	switch g.cfg.MainPanelSplitMode {
	case "vertical":
		return false
	case "horizontal":
		return true
	default:
		if a.width < 200 && a.height > 30 {
			return false
		}
		return true
	}
}

func (g *Gui) portraitMode(a *arrangeArgs) bool {
	switch g.cfg.PortraitMode {
	case "always":
		return true
	case "never":
		return false
	}
	return a.width <= 84 && a.height > 45
}

func (g *Gui) getWindowDimensions(a *arrangeArgs) map[string]Dimensions {
	sideW, mainW := g.midSectionWeights(a)
	sideDir := COLUMN
	if g.portraitMode(a) {
		sideDir = ROW
	}
	showInfo := g.cfg.ShowBottomLine || a.inSearchPrompt || a.isAnyModeActive || a.appStatus != ""
	infoSize := 0
	if showInfo {
		infoSize = 1
	}
	root := &Box{
		Direction: ROW,
		Children: []*Box{
			{
				Direction: sideDir,
				Weight:    1,
				Children: []*Box{
					{Direction: ROW, Weight: sideW, ConditionalChildren: g.sidePanelChildren(a)},
					{Direction: ROW, Weight: mainW, ConditionalChildren: g.mainPanelChildren(a)},
				},
			},
			{Direction: COLUMN, Size: infoSize, Children: g.infoSectionChildren(a)},
		},
	}
	if g.portraitMode(a) {
		// in portrait mode, side panels on top, main below
		root.Children[0].Children[0].Weight = 1
		root.Children[0].Children[1].Weight = 1
		if a.screenMode == ScreenHalf || a.screenMode == ScreenFull {
			sw, mw := g.midSectionWeights(a)
			root.Children[0].Children[0].Weight = sw
			root.Children[0].Children[1].Weight = mw
		}
	}
	return ArrangeWindows(root, 0, 0, a.width, a.height)
}

func (g *Gui) mainSectionChildren(a *arrangeArgs) []*Box {
	if !a.splitMain || (a.screenMode == ScreenFull && a.currentWindow == "main") {
		return []*Box{{Window: "main", Weight: 1}}
	}
	return []*Box{{Window: "main", Weight: 1}, {Window: "secondary", Weight: 1}}
}

func (g *Gui) mainPanelChildren(a *arrangeArgs) func(int, int) []*Box {
	return func(width, height int) []*Box {
		dir := ROW
		if g.splitMainSideBySide(a) {
			dir = COLUMN
		}
		res := []*Box{{Direction: dir, Children: g.mainSectionChildren(a), Weight: 1}}
		if a.showExtras {
			res = append(res, &Box{Window: "extras", Size: g.extrasWindowSize(a)})
		}
		return res
	}
}

func (g *Gui) extrasWindowSize(a *arrangeArgs) int {
	base := 0
	if a.currentStaticWindow == "extras" {
		base = 1000
	} else if a.height < 40 {
		base = 1
	} else {
		base = g.cfg.CommandLogSize
	}
	return base + 2
}

func (g *Gui) sidePanelChildren(a *arrangeArgs) func(int, int) []*Box {
	return func(width, height int) []*Box {
		if a.screenMode == ScreenFull || a.screenMode == ScreenHalf {
			box := func(w string) *Box {
				if w == a.currentSideWindow {
					return &Box{Window: w, Weight: 1}
				}
				return &Box{Window: w, Size: 0}
			}
			return []*Box{box("status"), box("files"), box("branches"), box("commits"), box("stash")}
		} else if height >= 28 {
			accordion := g.cfg.ExpandFocusedSidePanel
			acc := func(b *Box) *Box {
				if accordion && b.Window == a.currentSideWindow {
					return &Box{Window: b.Window, Weight: g.cfg.ExpandedSidePanelWeight}
				}
				return b
			}
			stash := &Box{Window: "stash", Size: 3}
			if a.stashAccessed {
				stash = &Box{Window: "stash", Weight: 1}
			}
			return []*Box{
				{Window: "status", Size: 3},
				acc(&Box{Window: "files", Weight: 1}),
				acc(&Box{Window: "branches", Weight: 1}),
				acc(&Box{Window: "commits", Weight: 1}),
				acc(stash),
			}
		}
		squashed := 1
		if height >= 21 {
			squashed = 3
		}
		box := func(w string) *Box {
			if w == a.currentSideWindow {
				return &Box{Window: w, Weight: 1}
			}
			return &Box{Window: w, Size: squashed}
		}
		return []*Box{box("status"), box("files"), box("branches"), box("commits"), box("stash")}
	}
}

func (g *Gui) infoSectionChildren(a *arrangeArgs) []*Box {
	if a.inSearchPrompt {
		return []*Box{
			{Window: "searchPrefix", Size: stringWidth(a.searchPrefix)},
			{Window: "search", Weight: 1},
		}
	}
	appStatus := &Box{Window: "appStatus"}
	options := &Box{Window: "options"}
	if !g.cfg.ShowBottomLine {
		options.Weight = 0
		appStatus.Weight = 1
	} else {
		options.Weight = 1
		if a.isAnyModeActive {
			appStatus.Size = 1 + stringWidth(a.appStatus)
		} else {
			appStatus.Size = stringWidth(a.appStatus)
		}
		if a.appStatus != "" && !a.isAnyModeActive {
			appStatus.Size = stringWidth(a.appStatus) + 1
		}
	}
	res := []*Box{appStatus, options}
	if g.cfg.ShowBottomLine || a.isAnyModeActive {
		res = append(res, &Box{Window: "information", Size: 1 + stringWidth(decolorise(a.informationStr))})
	}
	return res
}
EOF"}

