package main

import (
	"fmt"
	"strconv"
	"strings"
)

// A small YAML subset parser: block maps, block sequences, flow maps/sequences, scalars.

type yamlLine struct {
	indent int
	text   string
	num    int
}

type yamlParser struct {
	lines []yamlLine
	pos   int
}

func parseYAML(src string) (interface{}, error) {
	var lines []yamlLine
	rawLines := strings.Split(strings.ReplaceAll(src, "\r\n", "\n"), "\n")
	for i := 0; i < len(rawLines); i++ {
		raw := rawLines[i]
		t := stripYAMLComment(raw)
		if strings.TrimSpace(t) == "" {
			continue
		}
		if strings.TrimSpace(t) == "---" {
			continue
		}
		ind := len(t) - len(strings.TrimLeft(t, " "))
		lines = append(lines, yamlLine{indent: ind, text: strings.TrimRight(t[ind:], " \t"), num: i + 1})
	}
	p := &yamlParser{lines: lines}
	if len(lines) == 0 {
		return map[string]interface{}{}, nil
	}
	v, err := p.parseBlock(lines[0].indent, rawLines)
	if err != nil {
		return nil, err
	}
	if p.pos < len(p.lines) {
		return nil, fmt.Errorf("yaml: line %d: did not find expected key", p.lines[p.pos].num)
	}
	return v, nil
}

func stripYAMLComment(s string) string {
	inS, inD := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '\'' && !inD:
			inS = !inS
		case c == '"' && !inS:
			if i == 0 || s[i-1] != '\\' {
				inD = !inD
			}
		case c == '#' && !inS && !inD:
			if i == 0 || s[i-1] == ' ' || s[i-1] == '\t' {
				return s[:i]
			}
		}
	}
	return s
}

func (p *yamlParser) parseBlock(indent int, raw []string) (interface{}, error) {
	if p.pos >= len(p.lines) {
		return nil, nil
	}
	l := p.lines[p.pos]
	if strings.HasPrefix(l.text, "- ") || l.text == "-" {
		return p.parseSeq(indent, raw)
	}
	if _, _, ok := splitKey(l.text); ok {
		return p.parseMap(indent, raw)
	}
	// scalar
	p.pos++
	return parseFlowOrScalar(l.text, l.num)
}

func splitKey(t string) (string, string, bool) {
	// find ": " or trailing ":" outside quotes/brackets
	if strings.HasPrefix(t, "{") || strings.HasPrefix(t, "[") {
		return "", "", false
	}
	inS, inD := false, false
	for i := 0; i < len(t); i++ {
		c := t[i]
		switch {
		case c == '\'' && !inD:
			inS = !inS
		case c == '"' && !inS:
			inD = !inD
		case c == ':' && !inS && !inD:
			if i == len(t)-1 || t[i+1] == ' ' || t[i+1] == '\t' {
				k := strings.TrimSpace(t[:i])
				k = unquoteYAML(k)
				return k, strings.TrimSpace(t[i+1:]), true
			}
		}
	}
	return "", "", false
}

func unquoteYAML(s string) string {
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		if u, err := strconv.Unquote(s); err == nil {
			return u
		}
		return s[1 : len(s)-1]
	}
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return strings.ReplaceAll(s[1:len(s)-1], "''", "'")
	}
	return s
}

func (p *yamlParser) parseMap(indent int, raw []string) (interface{}, error) {
	m := map[string]interface{}{}
	order := []string{}
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.indent < indent {
			break
		}
		if l.indent > indent {
			return nil, fmt.Errorf("yaml: line %d: mapping values are not allowed in this context", l.num)
		}
		k, rest, ok := splitKey(l.text)
		if !ok {
			return nil, fmt.Errorf("yaml: line %d: could not find expected ':'", l.num)
		}
		p.pos++
		var val interface{}
		var err error
		if rest == "" {
			if p.pos < len(p.lines) && (p.lines[p.pos].indent > indent || (p.lines[p.pos].indent == indent && strings.HasPrefix(p.lines[p.pos].text, "- "))) {
				val, err = p.parseBlock(p.lines[p.pos].indent, raw)
				if err != nil {
					return nil, err
				}
			} else {
				val = nil
			}
		} else if rest == "|" || rest == ">" || rest == "|-" || rest == ">-" || rest == "|+" || rest == ">+" {
			val = p.parseBlockScalar(indent, rest, raw)
		} else {
			val, err = parseFlowOrScalar(rest, l.num)
			if err != nil {
				return nil, err
			}
			// multi-line plain scalars
			for p.pos < len(p.lines) && p.lines[p.pos].indent > indent {
				if s, ok := val.(string); ok {
					val = s + " " + p.lines[p.pos].text
					p.pos++
				} else {
					break
				}
			}
		}
		if _, exists := m[k]; !exists {
			order = append(order, k)
		}
		m[k] = val
	}
	m["\x00order"] = order
	return m, nil
}

func (p *yamlParser) parseBlockScalar(indent int, style string, raw []string) string {
	var parts []string
	startLine := p.lines[p.pos-1].num // 1-based line number of key
	// gather raw lines following until indentation <= indent (non-empty)
	i := startLine
	blockIndent := -1
	for ; i < len(raw); i++ {
		r := raw[i]
		if strings.TrimSpace(r) == "" {
			parts = append(parts, "")
			continue
		}
		ind := len(r) - len(strings.TrimLeft(r, " "))
		if ind <= indent {
			break
		}
		if blockIndent < 0 {
			blockIndent = ind
		}
		if ind < blockIndent {
			break
		}
		parts = append(parts, r[blockIndent:])
	}
	// advance parser past consumed lines
	for p.pos < len(p.lines) && p.lines[p.pos].num <= i {
		p.pos++
	}
	for len(parts) > 0 && parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	var s string
	if strings.HasPrefix(style, "|") {
		s = strings.Join(parts, "\n")
	} else {
		s = strings.Join(parts, " ")
	}
	if !strings.HasSuffix(style, "-") {
		s += "\n"
	}
	return s
}

func (p *yamlParser) parseSeq(indent int, raw []string) (interface{}, error) {
	var arr []interface{}
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.indent != indent || !(strings.HasPrefix(l.text, "- ") || l.text == "-") {
			if l.indent > indent {
				return nil, fmt.Errorf("yaml: line %d: did not find expected '-' indicator", l.num)
			}
			break
		}
		rest := strings.TrimSpace(strings.TrimPrefix(l.text, "-"))
		if rest == "" {
			p.pos++
			if p.pos < len(p.lines) && p.lines[p.pos].indent > indent {
				v, err := p.parseBlock(p.lines[p.pos].indent, raw)
				if err != nil {
					return nil, err
				}
				arr = append(arr, v)
			} else {
				arr = append(arr, nil)
			}
			continue
		}
		if _, _, ok := splitKey(rest); ok {
			// inline map start: rewrite this line as a map line with deeper indent
			newIndent := l.indent + (len(l.text) - len(rest))
			p.lines[p.pos] = yamlLine{indent: newIndent, text: rest, num: l.num}
			v, err := p.parseMap(newIndent, raw)
			if err != nil {
				return nil, err
			}
			arr = append(arr, v)
			continue
		}
		p.pos++
		v, err := parseFlowOrScalar(rest, l.num)
		if err != nil {
			return nil, err
		}
		arr = append(arr, v)
	}
	if arr == nil {
		arr = []interface{}{}
	}
	return arr, nil
}

func parseFlowOrScalar(s string, line int) (interface{}, error) {
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "{") || strings.HasPrefix(s, "[") {
		fp := &flowParser{s: s, line: line}
		v, err := fp.parse()
		if err != nil {
			return nil, err
		}
		return v, nil
	}
	return parseScalar(s), nil
}

func parseScalar(s string) interface{} {
	if len(s) >= 2 && (s[0] == '"' || s[0] == '\'') {
		return unquoteYAML(s)
	}
	switch s {
	case "~", "null", "Null", "NULL", "":
		return nil
	case "true", "True", "TRUE", "yes", "Yes", "on", "On":
		if s == "true" || s == "True" || s == "TRUE" {
			return true
		}
		return s
	case "false", "False", "FALSE":
		return false
	}
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		return int(i)
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f
	}
	return s
}

type flowParser struct {
	s    string
	i    int
	line int
}

func (f *flowParser) ws() {
	for f.i < len(f.s) && (f.s[f.i] == ' ' || f.s[f.i] == '\t') {
		f.i++
	}
}

func (f *flowParser) parse() (interface{}, error) {
	f.ws()
	if f.i >= len(f.s) {
		return nil, fmt.Errorf("yaml: line %d: did not find expected node content", f.line)
	}
	switch f.s[f.i] {
	case '{':
		f.i++
		m := map[string]interface{}{}
		order := []string{}
		for {
			f.ws()
			if f.i >= len(f.s) {
				return nil, fmt.Errorf("yaml: line %d: did not find expected ',' or '}'", f.line)
			}
			if f.s[f.i] == '}' {
				f.i++
				break
			}
			k := f.scalar(":,}")
			f.ws()
			var v interface{}
			if f.i < len(f.s) && f.s[f.i] == ':' {
				f.i++
				var err error
				v, err = f.parse()
				if err != nil {
					return nil, err
				}
			}
			ks := fmt.Sprint(parseScalar(k))
			if pk := parseScalar(k); pk != nil {
				if str, ok := pk.(string); ok {
					ks = str
				}
			}
			order = append(order, ks)
			m[ks] = v
			f.ws()
			if f.i < len(f.s) && f.s[f.i] == ',' {
				f.i++
			}
		}
		m["\x00order"] = order
		return m, nil
	case '[':
		f.i++
		arr := []interface{}{}
		for {
			f.ws()
			if f.i >= len(f.s) {
				return nil, fmt.Errorf("yaml: line %d: did not find expected node content", f.line)
			}
			if f.s[f.i] == ']' {
				f.i++
				break
			}
			v, err := f.parse()
			if err != nil {
				return nil, err
			}
			arr = append(arr, v)
			f.ws()
			if f.i < len(f.s) && f.s[f.i] == ',' {
				f.i++
			}
		}
		return arr, nil
	}
	return parseScalar(f.scalar(",]}")), nil
}

func (f *flowParser) scalar(stops string) string {
	f.ws()
	if f.i < len(f.s) && (f.s[f.i] == '"' || f.s[f.i] == '\'') {
		q := f.s[f.i]
		j := f.i + 1
		for j < len(f.s) {
			if f.s[j] == '\\' && q == '"' {
				j += 2
				continue
			}
			if f.s[j] == q {
				if q == '\'' && j+1 < len(f.s) && f.s[j+1] == '\'' {
					j += 2
					continue
				}
				break
			}
			j++
		}
		if j >= len(f.s) {
			j = len(f.s) - 1
		}
		res := f.s[f.i : j+1]
		f.i = j + 1
		return res
	}
	start := f.i
	for f.i < len(f.s) && !strings.ContainsRune(stops, rune(f.s[f.i])) {
		if f.s[f.i] == ':' && (f.i+1 >= len(f.s) || f.s[f.i+1] != ' ') && strings.ContainsRune(stops, ':') {
			// colon not followed by space: part of scalar
			f.i++
			continue
		}
		f.i++
	}
	return strings.TrimSpace(f.s[start:f.i])
}
EOF"}

