func configFilePaths() ([]string, bool) {
	if env := os.Getenv("LG_CONFIG_FILE"); env != "" {
		var res []string
		for _, p := range strings.Split(env, ",") {
			if p != "" {
				res = append(res, p)
			}
		}
		return res, true
	}
	return []string{filepath.Join(configDir(), "config.yml")}, false
}

// loadUserConfig loads config files; returns error message to print via log.Fatal.
func loadUserConfig() (*Config, error) {
	c := defaultConfig()
	paths, custom := configFilePaths()
	for _, p := range paths {
		st, err := os.Stat(p)
		if err != nil {
			if !custom {
				// create default empty config
				os.MkdirAll(filepath.Dir(p), 0o755)
				if f, err := os.Create(p); err == nil {
					f.Close()
				}
				continue
			}
			return nil, fmt.Errorf("stat %s: no such file or directory", p)
		}
		if st.IsDir() {
			continue
		}
		data, err := os.ReadFile(p)
		if err != nil {
			return nil, err
		}
		if err := c.loadYAMLInto(string(data), p); err != nil {
			return nil, err
		}
	}
	return c, nil
}

func (c *Config) loadYAMLInto(data, path string) error {
	v, err := parseYAML(data)
	if err != nil {
		return fmt.Errorf("failed to parse YAML: %s", err.Error())
	}
	m, ok := v.(map[string]interface{})
	if !ok {
		if v == nil {
			return nil
		}
		return nil
	}
	c.apply(m)
	return nil
}

func (c *Config) loadRepoConfig(repoRoot, gitDir string) {
	// .lazygit.yml in parent directories, then <gitdir>/lazygit.yml
	var dirs []string
	d := filepath.Dir(repoRoot)
	for {
		dirs = append([]string{d}, dirs...)
		nd := filepath.Dir(d)
		if nd == d {
			break
		}
		d = nd
	}
	for _, dd := range dirs {
		p := filepath.Join(dd, ".lazygit.yml")
		if data, err := os.ReadFile(p); err == nil {
			c.loadYAMLInto(string(data), p)
		}
	}
	p := filepath.Join(gitDir, "lazygit.yml")
	if data, err := os.ReadFile(p); err == nil {
		c.loadYAMLInto(string(data), p)
	}
}

func colorFromName(n string) (Color, bool) {
	switch strings.ToLower(n) {
	case "black":
