	StartupPopupVersion   int
	DidShowHunkStagingHint bool
	LastVersion           string
	CustomCommandsHistory []string
	HideCommandLog        bool
	extra                 []string
}

func statePath() string { return filepath.Join(stateDir(), "state.yml") }

func loadAppState() *AppState {
	s := &AppState{}
	data, err := os.ReadFile(statePath())
	if err != nil {
		return s
	}
	v, err := parseYAML(string(data))
	if err != nil {
		return s
	}
	m, ok := v.(map[string]interface{})
	if !ok {
		return s
	}
	if x, ok := m["lastupdatecheck"].(int); ok {
		s.LastUpdateCheck = int64(x)
	}
	if arr, ok := m["recentrepos"].([]interface{}); ok {
		for _, e := range arr {
			s.RecentRepos = append(s.RecentRepos, fmt.Sprint(e))
		}
	}
	if x, ok := m["startuppopupversion"].(int); ok {
		s.StartupPopupVersion = x
	}
	if x, ok := m["didshowhunkstaginghint"].(bool); ok {
		s.DidShowHunkStagingHint = x
	}
	if x, ok := m["lastversion"]; ok && x != nil {
		s.LastVersion = fmt.Sprint(x)
	}
	if arr, ok := m["customcommandshistory"].([]interface{}); ok {
		for _, e := range arr {
			s.CustomCommandsHistory = append(s.CustomCommandsHistory, fmt.Sprint(e))
		}
	}
	if x, ok := m["hidecommandlog"].(bool); ok {
		s.HideCommandLog = x
	}
	return s
}

func yamlQuote(s string) string {
	if s == "" {
		return "\"\""
	}
	needs := false
	if strings.ContainsAny(s, ":#{}[],&*?|<>=!%@`'\"\\\n\t") || strings.HasPrefix(s, " ") || strings.HasSuffix(s, " ") || strings.HasPrefix(s, "-") {
		needs = true
	}
	switch strings.ToLower(s) {
	case "true", "false", "yes", "no", "null", "~", "on", "off", "y", "n":
		needs = true
	}
	if _, err := strconv.ParseFloat(s, 64); err == nil {
		needs = true
	}
	if !needs {
		return s
	}
	if !strings.ContainsAny(s, "'\n") {
		return "'" + s + "'"
	}
	return strconv.Quote(s)
}

func (s *AppState) Save() {
	var b strings.Builder
	fmt.Fprintf(&b, "lastupdatecheck: %d\n", s.LastUpdateCheck)
	if len(s.RecentRepos) == 0 {
		b.WriteString("recentrepos: []\n")
	} else {
		b.WriteString("recentrepos:\n")
		for _, r := range s.RecentRepos {
			b.WriteString("    - " + yamlQuote(r) + "\n")
		}
	}
	fmt.Fprintf(&b, "startuppopupversion: %d\n", s.StartupPopupVersion)
	fmt.Fprintf(&b, "didshowhunkstaginghint: %v\n", s.DidShowHunkStagingHint)
	b.WriteString("lastversion: " + yamlQuote(s.LastVersion) + "\n")
	if len(s.CustomCommandsHistory) == 0 {
		b.WriteString("customcommandshistory: []\n")
	} else {
		b.WriteString("customcommandshistory:\n")
		for _, r := range s.CustomCommandsHistory {
			b.WriteString("    - " + yamlQuote(r) + "\n")
		}
	}
	fmt.Fprintf(&b, "hidecommandlog: %v\n", s.HideCommandLog)
	os.MkdirAll(stateDir(), 0o700)
	os.WriteFile(statePath(), []byte(b.String()), 0o644)
}
