	if n.File != nil {
		return n.File.HasMergeConflicts
	}
	for _, c := range n.Children {
		if c.anyConflicts() {
			return true
		}
	}
	return false
}

func (n *FileNode) allTracked() bool {
	if n.File != nil {
		return n.File.Tracked
	}
	for _, c := range n.Children {
		if !c.allTracked() {
			return false
		}
	}
	return true
}

func (n *FileNode) Files() []*File {
	if n.File != nil {
		return []*File{n.File}
	}
	var res []*File
	for _, c := range n.Children {
		res = append(res, c.Files()...)
	}
	return res
}

func buildFileTree(files []*File) *FileNode {
	root := &FileNode{Path: ""}
	for _, f := range files {
		parts := strings.Split(f.Name, "/")
		cur := root
		for i, p := range parts {
			if p == "" && i == len(parts)-1 {
				break
			}
			path := strings.Join(parts[:i+1], "/")
			var found *FileNode
			for _, c := range cur.Children {
				if c.Path == path && (i < len(parts)-1) == c.IsDir() {
					found = c
					break
				}
			}
			if found == nil {
				found = &FileNode{Path: path, Name: p}
				if i == len(parts)-1 {
					found.File = f
				}
				cur.Children = append(cur.Children, found)
			}
			cur = found
		}
	}
	sortTree(root)
	compressTree(root)
	return root
}

func sortTree(n *FileNode) {
	sort.SliceStable(n.Children, func(i, j int) bool {
		a, b := n.Children[i], n.Children[j]
		if a.IsDir() != b.IsDir() {
			return a.IsDir()
		}
		return a.Path < b.Path
	})
	for _, c := range n.Children {
		sortTree(c)
	}
}

func compressTree(n *FileNode) {
	for _, c := range n.Children {
		for c.IsDir() && len(c.Children) == 1 && c.Children[0].IsDir() {
			child := c.Children[0]
			c.Name = c.Name + "/" + child.Name
			c.Path = child.Path
			c.Children = child.Children
		}
		compressTree(c)
	}
}

func buildFlatList(files []*File) *FileNode {
	root := &FileNode{Path: ""}
	sorted := append([]*File{}, files...)
	sort.SliceStable(sorted, func(i, j int) bool {
		// conflicted files first? keep git order otherwise
		return false
	})
	for _, f := range sorted {
		root.Children = append(root.Children, &FileNode{Path: f.Name, Name: f.Name, File: f})
	}
	return root
}

// flatten returns visible nodes in display order.
func flattenTree(root *FileNode, collapsed map[string]bool, showRoot bool) []*FileNode {
	var res []*FileNode
	var walk func(n *FileNode, depth int)
	walk = func(n *FileNode, depth int) {
		n.Depth = depth
		res = append(res, n)
		if n.IsDir() && collapsed[n.Path] {
			return
		}
		for _, c := range n.Children {
			walk(c, depth+1)
		}
	}
	if showRoot && len(root.Children) > 1 {
		root.Name = "/"
		root.Depth = 0
		res = append(res, root)
		if !collapsed[""] {
			for _, c := range root.Children {
				walk(c, 1)
			}
		}
	} else {
		for _, c := range root.Children {
			walk(c, 0)
		}
	}
	return res
}
