// ---------- authors ----------

var authorStyleCache = map[string]Style{}

func authorStyle(name string, cfg *Config) Style {
	if s, ok := authorStyleCache[name]; ok {
		return s
	}
	if cfg != nil && cfg.AuthorColors != nil {
		if c, ok := cfg.AuthorColors[name]; ok {
			if col, ok2 := colorFromName(c); ok2 {
				s := FgStyle(col)
				authorStyleCache[name] = s
				return s
			}
		}
		if c, ok := cfg.AuthorColors["*"]; ok {
			if col, ok2 := colorFromName(c); ok2 {
				s := FgStyle(col)
				authorStyleCache[name] = s
				return s
			}
		}
	}
	h := md5.Sum([]byte(name))
	randInt := func(b []byte, mx int) int {
		s := 0
		for _, x := range b {
			s = (s + int(x)) % mx
		}
		return s
	}
	randFloat := func(b []byte) float64 { return float64(randInt(b, 100)) / 100 }
	r, g, b := hslToRGB(randFloat(h[0:4])*360.0, 0.6+0.4*randFloat(h[4:8]), 0.4+randFloat(h[8:12])*0.2)
	s := FgStyle(RGB(int(r*255), int(g*255), int(b*255)))
	authorStyleCache[name] = s
	return s
}

func hslToRGB(h, s, l float64) (float64, float64, float64) {
	if s == 0 {
		return l, l, l
	}
	var t1 float64
	if l < 0.5 {
		t1 = l * (1.0 + s)
	} else {
		t1 = l + s - l*s
	}
	t2 := 2*l - t1
	h = h / 360
	f := func(t float64) float64 {
		if t < 0 {
			t += 1
		}
		if t > 1 {
			t -= 1
		}
		if 6*t < 1 {
			return t2 + (t1-t2)*6*t
		}
		if 2*t < 1 {
			return t1
		}
		if 3*t < 2 {
			return t2 + (t1-t2)*(2.0/3.0-t)*6
		}
		return t2
	}
	return f(h + 1.0/3.0), f(h), f(h - 1.0/3.0)
}

func authorInitials(name string) string {
	if name == "" {
		return ""
	}
	first, _ := utf8.DecodeRuneInString(name)
	if utf8.RuneCountInString(name) == 1 || isCJK(first) {
		return string(first)
	}
	split := strings.Split(name, " ")
	if len(split) == 1 {
		return limitStr(name, 2)
	}
	second, _ := utf8.DecodeRuneInString(split[1])
	if split[1] == "" {
		return string(first)
	}
	return string(first) + string(second)
}

func isCJK(r rune) bool {
	return runeWidth(r) == 2
}

func limitStr(s string, n int) string {
	r := []rune(s)
	if len(r) > n {
		return string(r[:n])
	}
	return s
}

func truncateWithEllipsis(s string, limit int) string {
	if stringWidth(s) <= limit {
		return s
	}
	if limit <= 0 {
		return ""
	}
	if limit <= 3 {
		return strings.Repeat(".", limit)
	}
	return runeTruncate(s, limit-1) + "…"
}

func runeTruncate(s string, w int) string {
	var b strings.Builder
	cur := 0
	for _, r := range s {
		rw := runeWidth(r)
		if cur+rw > w {
			break
		}
		b.WriteRune(r)
		cur += rw
	}
	return b.String()
}

func authorWithLength(name string, length int, cfg *Config) string {
	if length <= 2 {
		ini := authorInitials(name)
		if ini == "" {
			return ""
		}
		return authorStyle(name, cfg).Sprint(ini)
	}
	return authorStyle(name, cfg).Sprint(truncateWithEllipsis(name, length))
}

