		}
		out = rest.Sprint(arrow) + " "
		name := n.Name
		out += rest.Sprint(name)
		return indent + out
	}
	f := n.File
	first := f.ShortStatus[0:1]
	second := f.ShortStatus[1:2]
	firstCl := fgGreen
	if first == "?" {
		firstCl = fgRed
	} else if first == " " {
		firstCl = rest
