func (g *Gui) commitRows(commits []*Commit, graphLines []string, fullDescription bool, isReflog bool, branchHeads map[string]bool) [][]string {
	rows := make([][]string, 0, len(commits))
	for i, c := range commits {
		hashColor := styleDefault
		switch c.Status {
		case "unpushed":
			hashColor = fgRed
		case "pushed":
			hashColor = fgYellow
		case "merged":
			hashColor = fgGreen
		case "rebasing", "reflog":
			hashColor = fgBlue
		}
		if g.diffName != "" && c.Hash == g.diffName {
