func (g *Gui) formatCommitDate(ts int64) string {
	t := timeFromUnix(ts)
	now := nowTime()
	if now.Sub(t).Hours() < 24 && now.Sub(t) >= 0 {
		return t.Format(g.cfg.ShortTimeFormat)
	}
	return t.Format(g.cfg.TimeFormat)
