	case !up && !down && !left && right:
		return "╶", "─"
	}
	return " ", " "
}

var graphHighlight = FgStyle(Color(15)).Bold()

func renderPipeSet(pipes []pipe, selectedHash string, prevCommit *Commit) string {
	maxPos := 0
	commitPos := 0
	startCount := 0
	for _, p := range pipes {
		if p.kind == pipeStarts {
			startCount++
			commitPos = p.fromPos
		} else if p.kind == pipeTerminates {
			commitPos = p.toPos
		}
		if p.right() > maxPos {
			maxPos = p.right()
		}
	}
	isMerge := startCount > 1
	cells := make([]*gcell, maxPos+1)
	for i := range cells {
		cells[i] = &gcell{style: styleDefault}
	}
	renderPipe := func(p pipe, s Style, overrideRight bool) {
		l, r := p.left(), p.right()
		if l != r {
			for i := l + 1; i < r; i++ {
				cells[i].setLeft(s)
				cells[i].setRight(s, overrideRight)
			}
			cells[l].setRight(s, overrideRight)
			cells[r].setLeft(s)
		}
		if p.kind == pipeStarts || p.kind == pipeContinues {
			cells[p.toPos].setDown(s)
		}
		if p.kind == pipeTerminates || p.kind == pipeContinues {
			cells[p.fromPos].setUp(s)
		}
	}
	highlight := true
	if prevCommit != nil && selectedHash != "" && prevCommit.Hash == selectedHash {
		highlight = false
		for _, p := range pipes {
			if p.fromHash == selectedHash && (p.kind != pipeTerminates || p.fromPos != p.toPos) {
				highlight = true
			}
		}
	}
	var selected, nonSelected []pipe
	for _, p := range pipes {
		if highlight && selectedHash != "" && p.fromHash == selectedHash {
			selected = append(selected, p)
		} else {
			nonSelected = append(nonSelected, p)
		}
	}
	for _, p := range nonSelected {
		if p.kind == pipeStarts {
			renderPipe(p, p.style, true)
		}
	}
	for _, p := range nonSelected {
		if p.kind != pipeStarts && !(p.kind == pipeTerminates && p.fromPos == commitPos && p.toPos == commitPos) {
			renderPipe(p, p.style, false)
		}
	}
	for _, p := range selected {
		for i := p.left(); i <= p.right(); i++ {
			cells[i].reset()
		}
	}
	for _, p := range selected {
		renderPipe(p, graphHighlight, true)
		if p.toPos == commitPos {
			cells[p.toPos].style = graphHighlight
		}
	}
	if isMerge {
		cells[commitPos].ctype = 2
	} else {
		cells[commitPos].ctype = 1
	}
	var b strings.Builder
	for _, c := range cells {
		first, second := boxChars(c.up, c.down, c.left, c.right)
		switch c.ctype {
		case 1:
			first = "◯"
		case 2:
			first = "⏣"
		}
		rs := c.style
		if c.rightStyle != nil {
			rs = *c.rightStyle
		}
		b.WriteString(c.style.Sprint(first))
		if second == " " {
			b.WriteString(" ")
		} else {
			b.WriteString(rs.Sprint(second))
		}
	}
	return b.String()
}

func (g *Gui) renderGraph(commits []*Commit, selectedHash string) []string {
	sets := getPipeSets(commits, func(c *Commit) Style { return authorStyle(c.AuthorName, g.cfg) })
	res := make([]string, len(sets))
	for i, s := range sets {
		var prev *Commit
		if i > 0 {
			prev = commits[i-1]
		}
		res[i] = renderPipeSet(s, selectedHash, prev)
	}
	return res
}

