// ---------- generic column rendering ----------

func renderDisplayStrings(rows [][]string) []string {
	if len(rows) == 0 {
		return nil
	}
	ncols := 0
	for _, r := range rows {
		if len(r) > ncols {
			ncols = len(r)
		}
	}
	// exclude blank columns
	keep := make([]bool, ncols)
	for c := 0; c < ncols; c++ {
		for _, r := range rows {
			if c < len(r) && decolorise(r[c]) != "" {
				keep[c] = true
				break
			}
		}
	}
	var filtered [][]string
	for _, r := range rows {
		var nr []string
		for c, s := range r {
			if keep[c] {
				nr = append(nr, s)
			}
		}
		filtered = append(filtered, nr)
	}
	ncols = 0
	for _, r := range filtered {
		if len(r) > ncols {
			ncols = len(r)
		}
	}
	widths := make([]int, maxInt(ncols-1, 0))
	for c := range widths {
		for _, r := range filtered {
			if c < len(r) {
				if w := visibleWidth(r[c]); w > widths[c] {
					widths[c] = w
				}
			}
		}
	}
	res := make([]string, 0, len(filtered))
	for _, r := range filtered {
		if len(r) == 0 {
			res = append(res, "")
			continue
		}
		var b strings.Builder
		for c, w := range widths {
			if c >= len(r) {
				continue
			}
			b.WriteString(r[c])
			pad := w - visibleWidth(r[c])
			if pad > 0 {
				b.WriteString(strings.Repeat(" ", pad))
			}
			b.WriteString(" ")
		}
		if len(r)-1 < len(widths) {
			res = append(res, strings.TrimSuffix(b.String(), ""))
			continue
		}
		b.WriteString(r[len(widths)])
		res = append(res, b.String())
	}
	return res
}

// ---------- authors ----------

var authorStyleCache = map[string]Style{}

func authorStyle(name string, cfg *Config) Style {
	if s, ok := authorStyleCache[name]; ok {
		return s
	}
	if cfg != nil && cfg.AuthorColors != nil {
		if c, ok := cfg.AuthorColors[name]; ok {
			if col, ok2 := colorFromName(c); ok2 {
				s := FgStyle(col)
				authorStyleCache[name] = s
				return s
			}
		}
		if c, ok := cfg.AuthorColors["*"]; ok {
			if col, ok2 := colorFromName(c); ok2 {
				s := FgStyle(col)
				authorStyleCache[name] = s
				return s
			}
		}
	}
	h := md5.Sum([]byte(name))
	randInt := func(b []byte, mx int) int {
		s := 0
		for _, x := range b {
			s = (s + int(x)) % mx
		}
		return s
	}
	randFloat := func(b []byte) float64 { return float64(randInt(b, 100)) / 100 }
	r, g, b := hslToRGB(randFloat(h[0:4])*360.0, 0.6+0.4*randFloat(h[4:8]), 0.4+randFloat(h[8:12])*0.2)
	s := FgStyle(RGB(int(r*255), int(g*255), int(b*255)))
	authorStyleCache[name] = s
	return s
}

func hslToRGB(h, s, l float64) (float64, float64, float64) {
	if s == 0 {
		return l, l, l
	}
	var t1 float64
	if l < 0.5 {
		t1 = l * (1.0 + s)
	} else {
		t1 = l + s - l*s
	}
	t2 := 2*l - t1
	h = h / 360
	f := func(t float64) float64 {
		if t < 0 {
			t += 1
		}
		if t > 1 {
			t -= 1
		}
		if 6*t < 1 {
			return t2 + (t1-t2)*6*t
		}
		if 2*t < 1 {
			return t1
		}
		if 3*t < 2 {
			return t2 + (t1-t2)*(2.0/3.0-t)*6
		}
		return t2
	}
	return f(h + 1.0/3.0), f(h), f(h - 1.0/3.0)
}

func authorInitials(name string) string {
	if name == "" {
		return ""
	}
	first, _ := utf8.DecodeRuneInString(name)
	if utf8.RuneCountInString(name) == 1 || isCJK(first) {
		return string(first)
	}
	split := strings.Split(name, " ")
	if len(split) == 1 {
		return limitStr(name, 2)
	}
	second, _ := utf8.DecodeRuneInString(split[1])
	if split[1] == "" {
		return string(first)
	}
	return string(first) + string(second)
}

func isCJK(r rune) bool {
	return runeWidth(r) == 2
}

func limitStr(s string, n int) string {
	r := []rune(s)
	if len(r) > n {
		return string(r[:n])
	}
	return s
}

func truncateWithEllipsis(s string, limit int) string {
	if stringWidth(s) <= limit {
		return s
	}
	if limit <= 0 {
		return ""
	}
	if limit <= 3 {
		return strings.Repeat(".", limit)
	}
	return runeTruncate(s, limit-1) + "…"
}

func runeTruncate(s string, w int) string {
	var b strings.Builder
	cur := 0
	for _, r := range s {
		rw := runeWidth(r)
		if cur+rw > w {
			break
		}
		b.WriteRune(r)
		cur += rw
	}
	return b.String()
}

func authorWithLength(name string, length int, cfg *Config) string {
	if length <= 2 {
		ini := authorInitials(name)
		if ini == "" {
			return ""
		}
		return authorStyle(name, cfg).Sprint(ini)
	}
	return authorStyle(name, cfg).Sprint(truncateWithEllipsis(name, length))
}

// ---------- files ----------

func (g *Gui) fileLine(n *FileNode) string {
	indent := strings.Repeat("  ", n.Depth)
	hasStaged := n.anyStaged()
	hasUnstaged := n.anyUnstaged()
	rest := styleDefault
	if n.anyConflicts() {
		rest = fgRed
	} else if hasStaged && !hasUnstaged {
		rest = fgGreen
	} else if hasStaged {
		rest = fgYellow
	}
	out := ""
	if n.IsDir() {
		arrow := "▼"
		if g.collapsedDirs[n.Path] {
			arrow = "▶"
		}
		out = rest.Sprint(arrow) + " "
		name := n.Name
		out += rest.Sprint(name)
		return indent + out
	}
	f := n.File
	first := f.ShortStatus[0:1]
	second := f.ShortStatus[1:2]
	firstCl := fgGreen
	if first == "?" {
		firstCl = fgRed
	} else if first == " " {
		firstCl = rest
	}
	if f.HasMergeConflicts {
		firstCl = fgRed
	}
	secondCl := fgRed
	if second == " " {
		secondCl = rest
	}
	out = firstCl.Sprint(first) + secondCl.Sprint(second) + rest.Sprint(" ")
	name := n.Name
	if !g.showTree {
		name = f.Name
	}
	if f.IsRename() {
		if g.showTree {
			prev := f.PreviousName
			if i := strings.LastIndex(prev, "/"); i >= 0 && strings.HasPrefix(f.Name, prev[:i+1]) {
				prev = prev[i+1:]
			}
			name = prev + " → " + name
		} else {
			name = f.PreviousName + " → " + f.Name
		}
	}
	if f.IsWorktree {
		name += " (worktree)"
	}
	out += rest.Sprint(name)
	if f.IsSubmodule {
		out += " (submodule)"
	}
	return indent + out
}

