func branchTextStyle(name string, cfg *Config) Style {
	if cfg != nil {
		for pat, col := range cfg.BranchColorPatterns {
			if re, err := regexp.Compile(pat); err == nil && re.MatchString(name) {
				if c, ok := colorFromName(col); ok {
					return FgStyle(c)
				}
			}
		}
	}
	switch strings.Split(name, "/")[0] {
	case "feature":
		return fgGreen
	case "bugfix":
		return fgYellow
	case "hotfix":
		return fgRed
	}
	return styleDefault
}

func branchStatus(b *Branch) string {
	if !b.IsTrackingRemote() {
		return ""
	}
	if b.UpstreamGone {
		return fgRed.Sprint("(upstream gone)")
	}
	if b.Ahead == "0" && b.Behind == "0" {
		return fgGreen.Sprint("✓")
	}
	if b.Ahead == "" && b.Behind == "" {
		return fgMagenta.Sprint("?")
	}
	behind := b.Behind != "" && b.Behind != "0"
	ahead := b.Ahead != "" && b.Ahead != "0"
	if behind && ahead {
		return fgYellow.Sprint("↓" + b.Behind + "↑" + b.Ahead)
	}
	if behind {
		return fgYellow.Sprint("↓" + b.Behind)
	}
	if ahead {
		return fgYellow.Sprint("↑" + b.Ahead)
	}
	return ""
}

func (g *Gui) branchRow(b *Branch, viewWidth int, fullDescription bool) []string {
	status := branchStatus(b)
	if op, ok := g.itemOperations["branch:"+b.Name]; ok {
		status = fgCyan.Sprint(op + " " + g.spinnerFrame())
	}
	avail := viewWidth - 4
	if status != "" {
		avail -= visibleWidth(status) + 1
	}
	showHash := fullDescription || g.cfg.ShowBranchCommitHash
	if showHash {
		avail -= 8
	}
	checkedOutByOther := b.WorktreePath != "" && !b.Head
	wtIcon := "(worktree)"
	if checkedOutByOther {
		avail -= stringWidth(wtIcon) + 1
	}
	display := b.Name
	nameStyle := branchTextStyle(b.Name, g.cfg)
	if g.diffName != "" && g.diffName == b.Name {
		nameStyle = fgMagenta
	}
	if stringWidth(display) > maxInt(avail, 3) {
		l := maxInt(avail, 4)
		display = runeTruncate(display, l-1) + "…"
	}
	colored := nameStyle.Sprint(display)
	if checkedOutByOther {
		colored += " " + fgDefault.Sprint(wtIcon)
	}
	if status != "" {
		colored += " " + status
	}
	recencyColor := fgCyan
	if b.Recency == "  *" {
		recencyColor = fgGreen
	}
	row := []string{recencyColor.Sprint(b.Recency)}
	if showHash {
		h := b.CommitHash
		if len(h) > 7 {
			h = h[:7]
		}
		row = append(row, h)
	}
	row = append(row, colored)
	if fullDescription {
		row = append(row, fgYellow.Sprint(b.UpstreamRemote)+" "+fgYellow.Sprint(b.UpstreamBranch), truncateWithEllipsis(b.Subject, 60))
	}
	return row
}

// ---------- commits ----------

func (g *Gui) commitRows(commits []*Commit, graphLines []string, fullDescription bool, isReflog bool, branchHeads map[string]bool) [][]string {
	rows := make([][]string, 0, len(commits))
	for i, c := range commits {
		hashColor := styleDefault
		switch c.Status {
		case "unpushed":
			hashColor = fgRed
		case "pushed":
			hashColor = fgYellow
		case "merged":
			hashColor = fgGreen
		case "rebasing", "reflog":
			hashColor = fgBlue
		}
		if g.diffName != "" && c.Hash == g.diffName {
			hashColor = fgMagenta
		} else if g.cherryPicked[c.Hash] {
			hashColor = FgStyle(ColBlue).WithBg(ColCyan)
		}
		hl := g.cfg.CommitHashLength
		hash := ""
		if hl >= len(c.Hash) {
			hash = hashColor.Sprint(c.Hash)
		} else if hl > 0 {
			hash = hashColor.Sprint(c.Hash[:hl])
		} else {
			hash = hashColor.Sprint("*")
		}
		desc := ""
		if fullDescription {
			desc = fgBlue.Sprint(g.formatCommitDate(c.UnixTimestamp))
		}
		action := ""
		if c.Action != "" {
			action = actionStyle(c.Action).Sprint(c.Action) + " "
		}
		tagStr := ""
		if isReflog {
			// no tags
		} else if fullDescription {
			if c.ExtraInfo != "" {
				tagStr = fgMagenta.Bold().Sprint(c.ExtraInfo) + " "
			}
		} else {
			if len(c.Tags) > 0 {
				tagStr = fgMagenta.Bold().Sprint(strings.Join(c.Tags, " ")) + " "
			}
			if branchHeads[c.Hash] && c.Status != "merged" {
				tagStr = fgCyan.Bold().Sprint("* "+tagStr)
			}
		}
		authorLen := g.cfg.CommitAuthorShortLength
		if fullDescription {
			authorLen = g.cfg.CommitAuthorLongLength
		}
		author := ""
		if !isReflog {
			author = authorWithLength(c.AuthorName, authorLen, g.cfg)
		}
		graph := ""
		if i < len(graphLines) {
			graph = graphLines[i]
		}
		name := c.Name
		rows = append(rows, []string{"", hash, "", desc, action, author, graph + tagStr + name})
	}
	return rows
}

func actionStyle(a string) Style {
	switch a {
	case "pick":
		return fgCyan
	case "drop":
		return fgRed
	case "edit":
		return fgGreen
	case "fixup":
		return fgMagenta
	case "squash":
		return fgYellow
	}
	return fgYellow
}

func (g *Gui) formatCommitDate(ts int64) string {
	t := timeFromUnix(ts)
	now := nowTime()
	if now.Sub(t).Hours() < 24 && now.Sub(t) >= 0 {
		return t.Format(g.cfg.ShortTimeFormat)
	}
	return t.Format(g.cfg.TimeFormat)
}

// ---------- graph ----------

type pipeKind int

const (
	pipeTerminates pipeKind = iota
	pipeStarts
	pipeContinues
)

type pipe struct {
	fromPos, toPos   int
	fromHash, toHash string
	kind             pipeKind
	style            Style
}

func (p pipe) left() int  { return minInt(p.fromPos, p.toPos) }
func (p pipe) right() int { return maxInt(p.fromPos, p.toPos) }

const emptyTreeHash = "4b825dc642cb6eb9a060e54bf8d69288fbee4904"

func getPipeSets(commits []*Commit, getStyle func(*Commit) Style) [][]pipe {
	if len(commits) == 0 {
		return nil
	}
	pipes := []pipe{{fromPos: 0, toPos: 0, fromHash: "START", toHash: commits[0].Hash, kind: pipeStarts, style: styleDefault}}
	res := make([][]pipe, 0, len(commits))
	for _, c := range commits {
		pipes = getNextPipes(pipes, c, getStyle)
		res = append(res, pipes)
	}
	return res
}

func getNextPipes(prev []pipe, commit *Commit, getStyle func(*Commit) Style) []pipe {
	maxPos := 0
	for _, p := range prev {
		if p.toPos > maxPos {
			maxPos = p.toPos
		}
	}
	var current []pipe
	for _, p := range prev {
		if p.kind != pipeTerminates {
			current = append(current, p)
		}
	}
	newPipes := make([]pipe, 0, len(current)+len(commit.Parents))
	pos := maxPos + 1
	for _, p := range current {
		if p.toHash == commit.Hash {
			pos = p.toPos
			break
		}
	}
	taken := map[int]bool{}
	traversed := map[int]bool{}
	toHash := emptyTreeHash
	if len(commit.Parents) > 0 {
		toHash = commit.Parents[0]
	}
	newPipes = append(newPipes, pipe{fromPos: pos, toPos: pos, fromHash: commit.Hash, toHash: toHash, kind: pipeStarts, style: getStyle(commit)})
	traversedForContinuing := map[int]bool{}
	for _, p := range current {
		if p.toHash != commit.Hash {
			traversedForContinuing[p.toPos] = true
		}
	}
	nextAvailContinuing := func() int {
		i := 0
		for traversed[i] {
			i++
		}
		return i
	}
	nextAvailNew := func() int {
		i := 0
		for taken[i] || traversedForContinuing[i] {
			i++
		}
		return i
	}
	traverse := func(from, to int) {
		l, r := from, to
		if l > r {
			l, r = r, l
		}
		for i := l; i <= r; i++ {
			traversed[i] = true
		}
		taken[to] = true
	}
	for _, p := range current {
		if p.toHash == commit.Hash {
			newPipes = append(newPipes, pipe{fromPos: p.toPos, toPos: pos, fromHash: p.fromHash, toHash: p.toHash, kind: pipeTerminates, style: p.style})
			traverse(p.toPos, pos)
		} else if p.toPos < pos {
			avail := nextAvailContinuing()
			newPipes = append(newPipes, pipe{fromPos: p.toPos, toPos: avail, fromHash: p.fromHash, toHash: p.toHash, kind: pipeContinues, style: p.style})
			traverse(p.toPos, avail)
		}
	}
	if len(commit.Parents) > 1 {
		for _, parent := range commit.Parents[1:] {
			avail := nextAvailNew()
			newPipes = append(newPipes, pipe{fromPos: pos, toPos: avail, fromHash: commit.Hash, toHash: parent, kind: pipeStarts, style: getStyle(commit)})
			taken[avail] = true
		}
	}
	for _, p := range current {
		if p.toHash != commit.Hash && p.toPos > pos {
			last := p.toPos
			for i := p.toPos; i > pos; i-- {
				if taken[i] || traversed[i] {
					break
				}
				last = i
			}
			newPipes = append(newPipes, pipe{fromPos: p.toPos, toPos: last, fromHash: p.fromHash, toHash: p.toHash, kind: pipeContinues, style: p.style})
			traverse(p.toPos, last)
		}
	}
	// stable sort by toPos then kind
	for i := 1; i < len(newPipes); i++ {
		for j := i; j > 0; j-- {
			a, b := newPipes[j-1], newPipes[j]
			if a.toPos > b.toPos || (a.toPos == b.toPos && a.kind > b.kind) {
				newPipes[j-1], newPipes[j] = b, a
			} else {
				break
			}
		}
	}
	return newPipes
}

type gcell struct {
	up, down, left, right bool
	ctype                 int // 0 connection, 1 commit, 2 merge
	rightStyle            *Style
	style                 Style
}

func (c *gcell) setUp(s Style) { c.up = true; c.style = s }
func (c *gcell) setDown(s Style) { c.down = true; c.style = s }
func (c *gcell) setLeft(s Style) {
	c.left = true
	if !c.up && !c.down {
		c.style = s
	}
}
func (c *gcell) setRight(s Style, override bool) {
	c.right = true
	if c.rightStyle == nil || override {
		ss := s
		c.rightStyle = &ss
	}
}
func (c *gcell) reset() { c.up, c.down, c.left, c.right = false, false, false, false }

func boxChars(up, down, left, right bool) (string, string) {
	switch {
	case up && down && left && right:
		return "│", "─"
	case up && down && left && !right:
		return "│", " "
	case up && down && !left && right:
		return "│", "─"
	case up && down && !left && !right:
		return "│", " "
	case up && !down && left && right:
		return "┴", "─"
	case up && !down && left && !right:
		return "╯", " "
	case up && !down && !left && right:
		return "╰", "─"
	case up && !down && !left && !right:
		return "╵", " "
	case !up && down && left && right:
		return "┬", "─"
	case !up && down && left && !right:
		return "╮", " "
	case !up && down && !left && right:
		return "╭", "─"
	case !up && down && !left && !right:
		return "╷", " "
	case !up && !down && left && right:
		return "─", "─"
	case !up && !down && left && !right:
		return "─", " "
	case !up && !down && !left && right:
		return "╶", "─"
	}
	return " ", " "
}

var graphHighlight = FgStyle(Color(15)).Bold()

func renderPipeSet(pipes []pipe, selectedHash string, prevCommit *Commit) string {
	maxPos := 0
	commitPos := 0
	startCount := 0
	for _, p := range pipes {
		if p.kind == pipeStarts {
			startCount++
			commitPos = p.fromPos
		} else if p.kind == pipeTerminates {
			commitPos = p.toPos
		}
		if p.right() > maxPos {
			maxPos = p.right()
		}
	}
	isMerge := startCount > 1
	cells := make([]*gcell, maxPos+1)
	for i := range cells {
		cells[i] = &gcell{style: styleDefault}
	}
	renderPipe := func(p pipe, s Style, overrideRight bool) {
		l, r := p.left(), p.right()
		if l != r {
			for i := l + 1; i < r; i++ {
				cells[i].setLeft(s)
				cells[i].setRight(s, overrideRight)
			}
			cells[l].setRight(s, overrideRight)
			cells[r].setLeft(s)
		}
		if p.kind == pipeStarts || p.kind == pipeContinues {
			cells[p.toPos].setDown(s)
		}
		if p.kind == pipeTerminates || p.kind == pipeContinues {
			cells[p.fromPos].setUp(s)
		}
	}
	highlight := true
	if prevCommit != nil && selectedHash != "" && prevCommit.Hash == selectedHash {
		highlight = false
		for _, p := range pipes {
			if p.fromHash == selectedHash && (p.kind != pipeTerminates || p.fromPos != p.toPos) {
				highlight = true
			}
		}
	}
	var selected, nonSelected []pipe
	for _, p := range pipes {
		if highlight && selectedHash != "" && p.fromHash == selectedHash {
			selected = append(selected, p)
		} else {
			nonSelected = append(nonSelected, p)
		}
	}
	for _, p := range nonSelected {
		if p.kind == pipeStarts {
			renderPipe(p, p.style, true)
		}
	}
	for _, p := range nonSelected {
		if p.kind != pipeStarts && !(p.kind == pipeTerminates && p.fromPos == commitPos && p.toPos == commitPos) {
			renderPipe(p, p.style, false)
		}
	}
	for _, p := range selected {
		for i := p.left(); i <= p.right(); i++ {
			cells[i].reset()
		}
	}
	for _, p := range selected {
		renderPipe(p, graphHighlight, true)
		if p.toPos == commitPos {
			cells[p.toPos].style = graphHighlight
		}
	}
	if isMerge {
		cells[commitPos].ctype = 2
	} else {
		cells[commitPos].ctype = 1
	}
	var b strings.Builder
	for _, c := range cells {
		first, second := boxChars(c.up, c.down, c.left, c.right)
		switch c.ctype {
		case 1:
			first = "◯"
		case 2:
			first = "⏣"
		}
		rs := c.style
		if c.rightStyle != nil {
			rs = *c.rightStyle
		}
		b.WriteString(c.style.Sprint(first))
		if second == " " {
			b.WriteString(" ")
		} else {
			b.WriteString(rs.Sprint(second))
		}
	}
	return b.String()
}

func (g *Gui) renderGraph(commits []*Commit, selectedHash string) []string {
	sets := getPipeSets(commits, func(c *Commit) Style { return authorStyle(c.AuthorName, g.cfg) })
	res := make([]string, len(sets))
	for i, s := range sets {
		var prev *Commit
		if i > 0 {
			prev = commits[i-1]
		}
		res[i] = renderPipeSet(s, selectedHash, prev)
	}
	return res
}

// ---------- misc ----------

func plural(n int, s string) string {
	return strconv.Itoa(n) + " " + s
}

