	if args.screenMode != "" {
		cfg.ScreenMode = args.screenMode
	}
	borderStyle = cfg.Border

	term, err := openTerminal()
	if err != nil {
		fatalStartupError(err.Error())
	}
	g := newGui(term, cfg, state, args)
	g.run()
}

// returns true if we are now in a repo
func handleNotARepo(cfg *Config, state *AppState) bool {
	switch cfg.NotARepository {
	case "create":
		initRepo("")
		return true
	case "skip":
		if openRecentRepo(state) {
			return true
		}
		fmt.Fprintln(os.Stderr, "Must open lazygit in a git repository. No valid recent repositories. Exiting.")
		os.Exit(1)
	case "quit":
		fmt.Fprintln(os.Stderr, "Must open lazygit in a git repository")
		os.Exit(0)
	}
	fmt.Print("Not in a git repository. Create a new git repository? (y/N): ")
	reader := bufio.NewReader(os.Stdin)
	resp, _ := reader.ReadString('\n')
	resp = strings.TrimSpace(resp)
	if strings.ToLower(resp) == "y" {
		fmt.Print("Branch name? (leave empty for git's default): ")
		branch, _ := reader.ReadString('\n')
		branch = strings.TrimSpace(branch)
		initRepo(branch)
		return true
	}
	if openRecentRepo(state) {
		return true
	}
	fmt.Fprintln(os.Stderr, "Must open lazygit in a git repository. No valid recent repositories. Exiting.")
	os.Exit(1)
	return false
}

func initRepo(branch string) {
	args := []string{"init"}
	if branch != "" {
		args = append(args, "--initial-branch="+branch)
	}
	cmd := exec.Command("git", args...)
	cmd.Run()
}

func openRecentRepo(state *AppState) bool {
	cwd, _ := os.Getwd()
	for _, r := range state.RecentRepos {
		if r == cwd {
			continue
		}
		if st, err := os.Stat(r); err != nil || !st.IsDir() {
			continue
		}
		if err := os.Chdir(r); err != nil {
			continue
		}
		if isInGitRepo() {
			return true
		}
	}
	return false
}

func repoNameOf(root string) string {
	return filepath.Base(root)
}
