)

type ContextKind int

const (
	KindSide ContextKind = iota
	KindMain
	KindPopup
	KindExtras
)

type Context struct {
	Key         string
	Kind        ContextKind
	Window      string
	Title       string
	View        *View
	IsList      bool
	sel         int
	rangeStart  int
	rangeActive bool
	rangeSticky bool
	length      func() int
	render      func() []string
	menuKey     string
	footer      bool
	onFocus     func()
	onFocusLost func()
	parentKey   string
}

func (c *Context) Len() int {
	if c.length == nil {
		return 0
	}
	return c.length()
}

func (c *Context) clampSel() {
	n := c.Len()
	if c.sel >= n {
		c.sel = n - 1
	}
	if c.sel < 0 {
		c.sel = 0
	}
	if c.rangeActive {
		if c.rangeStart >= n {
			c.rangeStart = n - 1
		}
		if c.rangeStart < 0 {
			c.rangeStart = 0
		}
	}
}

func (c *Context) selRange() (int, int) {
	if !c.rangeActive {
		return c.sel, c.sel
	}
	a, b := c.rangeStart, c.sel
	if a > b {
		a, b = b, a
	}
	return a, b
}

type Gui struct {
	t     *Terminal
	cfg   *Config
	state *AppState
	args  *cliArgs
	w, h  int
	front *Screen
	fullRedraw bool

	views     map[string]*View
