	"strings"
	"time"
)

type ContextKind int

const (
	KindSide ContextKind = iota
	KindMain
	KindPopup
	KindExtras
)

type Context struct {
	Key         string
	Kind        ContextKind
	Window      string
	Title       string
	View        *View
	IsList      bool
	sel         int
	rangeStart  int
	rangeActive bool
	rangeSticky bool
	length      func() int
	render      func() []string
	menuKey     string
	footer      bool
	onFocus     func()
	onFocusLost func()
	parentKey   string
}

func (c *Context) Len() int {
	if c.length == nil {
		return 0
	}
	return c.length()
}

func (c *Context) clampSel() {
	n := c.Len()
	if c.sel >= n {
		c.sel = n - 1
	}
	if c.sel < 0 {
		c.sel = 0
	}
	if c.rangeActive {
		if c.rangeStart >= n {
			c.rangeStart = n - 1
		}
		if c.rangeStart < 0 {
			c.rangeStart = 0
		}
	}
}

func (c *Context) selRange() (int, int) {
	if !c.rangeActive {
		return c.sel, c.sel
	}
	a, b := c.rangeStart, c.sel
	if a > b {
		a, b = b, a
	}
	return a, b
}

type Gui struct {
	t     *Terminal
	cfg   *Config
	state *AppState
	args  *cliArgs
	w, h  int
	front *Screen
	fullRedraw bool

	views     map[string]*View
	viewOrder []string

	ctx         map[string]*Context
	stack       []*Context
	windowCtx   map[string]string
	stashAccessed bool

	// models
	files      []*File
	fileNodes  []*FileNode
	fileRoot   *FileNode
	collapsedDirs map[string]bool
	showTree   bool
	branches   []*Branch
	remotes    []*Remote
	remoteBranches []*RemoteBranch
	currentRemote *Remote
	tags       []*Tag
	commits    []*Commit
	commitGraph []string
	reflog     []*Commit
	stash      []*StashEntry
	worktrees  []*Worktree
	submodules []*Submodule
	subCommits []*Commit
	subCommitsRef string
	subCommitsTitle string
	commitFiles []*File
	commitFileNodes []*FileNode
	commitFilesRef string
	commitFilesTitle string
	commitFilesParent string
	mainBranchRefs []string

	repoRoot string
	repoName string
	gitDir   string
	headBranch *Branch

	screenMode int
	diffName   string
	cherryPicked map[string]bool
	itemOperations map[string]string

	cmdLogLines []string
	appStatus  string
	statusUntil time.Time
	quitting   bool
	exitCode   int
	mainKey    string
	mainTitle  string
	secTitle   string
	splitMain  bool
	tip        string

	diffContext int
	renameThreshold int
	ignoreWhitespace bool

	// popups
	menu      *menuState
	confirm   *confirmState
	toast     string
	toastUntil time.Time
	commitMsg *commitMsgState
	searchState *searchState

	// staging
	staging *stagingState

	inPrompt bool
	lastSelectedFile string
	pendingEvents []Event
	statusPanelMainOverride string
	allBranchLogIdx int
	extrasFocusedOnce bool
	commandLogFocusedAutoscroll bool
}

func newGui(t *Terminal, cfg *Config, state *AppState, args *cliArgs) *Gui {
	g := &Gui{t: t, cfg: cfg, state: state, args: args, views: map[string]*View{}, ctx: map[string]*Context{},
		windowCtx: map[string]string{}, collapsedDirs: map[string]bool{}, showTree: cfg.ShowFileTree,
		cherryPicked: map[string]bool{}, itemOperations: map[string]string{}, fullRedraw: true}
	g.w, g.h = t.w, t.h
	g.diffContext = cfg.DiffContextSize
	g.renameThreshold = cfg.RenameSimilarityThreshold
	g.ignoreWhitespace = cfg.IgnoreWhitespaceInDiffView
	switch cfg.ScreenMode {
	case "half":
		g.screenMode = ScreenHalf
	case "full":
		g.screenMode = ScreenFull
	}
	cwd, _ := os.Getwd()
	g.repoRoot = cwd
	g.repoName = repoNameOf(cwd)
	g.gitDir = gitDirPath()
	g.createViews()
	g.createContexts()
	return g
}

func (g *Gui) addView(name string) *View {
	v := NewView(name)
	g.views[name] = v
	g.viewOrder = append(g.viewOrder, name)
	return v
}

func (g *Gui) createViews() {
	for _, n := range []string{"main", "secondary", "staging", "stagingSecondary", "status", "submodules", "worktrees", "files",
		"tags", "remotes", "remoteBranches", "localBranches", "commitFiles", "subCommits", "reflogCommits", "commits", "stash",
		"extras", "options", "appStatus", "information", "search", "searchPrefix",
		"commitMessage", "commitDescription", "menu", "suggestions", "confirmation", "tooltip", "limit"} {
		g.addView(n)
	}
	for _, n := range []string{"main", "secondary", "staging", "stagingSecondary"} {
		v := g.views[n]
		v.Wrap = true
		v.CanScrollPastBottom = g.cfg.ScrollPastBottom
		v.Scrollbar = true
		v.TabWidth = g.cfg.TabWidth
	}
	for _, n := range []string{"options", "appStatus", "information", "search", "searchPrefix"} {
		g.views[n].Frame = false
	}
	g.views["options"].FgColor = themeStyle(g.cfg.OptionsTextColor).Fg
	g.views["extras"].Wrap = true
	g.views["extras"].Title = "Command log"
	g.views["extras"].Scrollbar = true
	g.views["confirmation"].Wrap = true
	g.views["tooltip"].Wrap = true
	g.views["menu"].Scrollbar = true
	g.views["limit"].Title = "Not enough space to render panels"
	g.views["limit"].Wrap = true
	for _, n := range []string{"files", "worktrees", "submodules", "localBranches", "remotes", "remoteBranches", "tags", "commits",
		"reflogCommits", "subCommits", "commitFiles", "stash", "status"} {
		g.views[n].Scrollbar = true
	}
	g.views["status"].Scrollbar = false
}

func (g *Gui) view(name string) *View { return g.views[name] }

// ---------- run loop ----------

func (g *Gui) run() {
	defer func() {
		if r := recover(); r != nil {
			g.t.Close()
			panic(r)
		}
	}()
	g.recordRecentRepo()
	g.refreshAll()
	g.initCommandLog()
	initial := "files"
	if g.args != nil {
		switch g.args.gitArg {
		case "status":
			initial = "status"
		case "branch":
			initial = "localBranches"
		case "log":
			initial = "commits"
		case "stash":
			initial = "stash"
		}
	}
	g.pushContext(g.ctx[initial])
	if !g.cfg.DisableStartupPopups && g.state.StartupPopupVersion < 5 {
		g.showIntroPopup()
	}
	g.state.LastVersion = buildVersion
	g.state.Save()
	g.render()

	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()
	refreshTicker := time.NewTicker(time.Duration(maxInt(g.cfg.refreshInterval(), 1)) * time.Second)
	defer refreshTicker.Stop()
	for !g.quitting {
		select {
		case ev := <-g.t.events:
			g.handleEvent(ev)
			// drain queued events quickly
		drain:
			for i := 0; i < 64 && !g.quitting; i++ {
				select {
				case ev2 := <-g.t.events:
					g.handleEvent(ev2)
				default:
					break drain
				}
			}
		case <-ticker.C:
			if g.appStatus != "" && !g.statusUntil.IsZero() && time.Now().After(g.statusUntil) {
				g.appStatus = ""
				g.statusUntil = time.Time{}
			}
			if g.toast != "" && time.Now().After(g.toastUntil) {
				g.toast = ""
			}
		case <-refreshTicker.C:
			if g.cfg.AutoRefresh && g.currentContext().Kind != KindPopup && g.commitMsg == nil {
				g.backgroundRefresh()
			}
		}
		if g.quitting {
			break
		}
		g.render()
	}
	g.t.Close()
	os.Exit(g.exitCode)
}

func (c *Config) refreshInterval() int { return 10 }

func (g *Gui) recordRecentRepo() {
	cwd, _ := os.Getwd()
	var res []string
	res = append(res, cwd)
	for _, r := range g.state.RecentRepos {
		if r != cwd {
			res = append(res, r)
		}
	}
	if len(res) > 20 {
		res = res[:20]
	}
	g.state.RecentRepos = res
}

func (g *Gui) handleEvent(ev Event) {
	switch ev.Type {
	case EvResize:
		g.w, g.h = ev.MX, ev.MY
		g.fullRedraw = true
		g.mainKey = ""
	case EvKey:
		g.handleKey(ev.Key)
	case EvPaste:
		g.handlePaste(ev.Paste)
	case EvMouse:
		g.handleMouse(ev)
	case EvFunc:
		if ev.Fn != nil {
			ev.Fn()
		}
	}
}

func (g *Gui) post(fn func()) {
	go func() { g.t.events <- Event{Type: EvFunc, Fn: fn} }()
}

// ---------- contexts / focus ----------

func (g *Gui) currentContext() *Context {
	if len(g.stack) == 0 {
		return g.ctx["files"]
	}
	return g.stack[len(g.stack)-1]
}

func (g *Gui) currentSideContext() *Context {
	for i := len(g.stack) - 1; i >= 0; i-- {
		if g.stack[i].Kind == KindSide {
			return g.stack[i]
		}
	}
	return g.ctx["files"]
}

func (g *Gui) currentStaticContext() *Context {
	for i := len(g.stack) - 1; i >= 0; i-- {
		if g.stack[i].Kind != KindPopup {
			return g.stack[i]
		}
	}
	return g.ctx["files"]
}

func (g *Gui) pushContext(c *Context) {
	if c == nil {
		return
	}
	prev := g.currentContext()
	switch c.Kind {
	case KindSide:
		// replace stack
		for _, x := range g.stack {
			if x.onFocusLost != nil && x != c {
				x.onFocusLost()
			}
		}
		g.stack = []*Context{c}
	case KindMain, KindExtras:
		// keep side context underneath
		var ns []*Context
		for _, x := range g.stack {
			if x.Kind == KindSide {
				ns = append(ns, x)
			}
		}
		g.stack = append(ns, c)
	default:
		g.stack = append(g.stack, c)
	}
	if c.Window != "" && (c.Kind == KindSide) {
		g.windowCtx[c.Window] = c.Key
	}
	if c.Window == "stash" {
		g.stashAccessed = true
	}
	if c.onFocus != nil && c != prev {
		c.onFocus()
	}
	g.mainKey = ""
}

func (g *Gui) popContext() {
	if len(g.stack) <= 1 {
		return
	}
	top := g.stack[len(g.stack)-1]
	g.stack = g.stack[:len(g.stack)-1]
	if top.onFocusLost != nil {
		top.onFocusLost()
	}
	g.mainKey = ""
}

func (g *Gui) removeContext(key string) {
	var ns []*Context
	for _, c := range g.stack {
		if c.Key != key {
			ns = append(ns, c)
		}
	}
	if len(ns) == 0 {
		ns = []*Context{g.ctx["files"]}
	}
	g.stack = ns
	g.mainKey = ""
}

func (g *Gui) windowContext(window string) *Context {
	if k, ok := g.windowCtx[window]; ok {
		return g.ctx[k]
	}
	switch window {
	case "status":
		return g.ctx["status"]
	case "files":
		return g.ctx["files"]
	case "branches":
		return g.ctx["localBranches"]
	case "commits":
		return g.ctx["commits"]
	case "stash":
		return g.ctx["stash"]
	}
	return nil
}

var sideWindows = []string{"status", "files", "branches", "commits", "stash"}

func (g *Gui) windowTabs(window string) []string {
	switch window {
	case "files":
		return []string{"files", "worktrees", "submodules"}
	case "branches":
		return []string{"localBranches", "remotes", "tags"}
	case "commits":
		return []string{"commits", "reflogCommits"}
	}
	return nil
}

func (g *Gui) focusWindow(window string) {
	c := g.windowContext(window)
	if c != nil {
		g.pushContext(c)
	}
}

// ---------- refresh ----------

func (g *Gui) refreshAll() {
	g.refreshFiles()
	g.refreshBranches()
	g.refreshCommits()
	g.refreshReflog()
	g.refreshStash()
	g.refreshRemotes()
	g.refreshTags()
	g.refreshWorktrees()
	g.refreshSubmodules()
	g.mainKey = ""
}

func (g *Gui) backgroundRefresh() {
	g.refreshFiles()
	g.refreshSubmodules()
	g.mainKey = ""
}

func (g *Gui) refreshFiles() {
	var prevPath string
	fc := g.ctx["files"]
	if fc != nil && fc.sel < len(g.fileNodes) && fc.sel >= 0 {
		prevPath = g.fileNodes[fc.sel].Path
	}
	g.files = loadFiles(g.renameThreshold)
	// sort: lazygit sorts conflicted first? keep order
	if g.showTree {
		g.fileRoot = buildFileTree(g.files)
	} else {
		g.fileRoot = buildFlatListSorted(g.files)
	}
	g.fileNodes = flattenTree(g.fileRoot, g.collapsedDirs, g.cfg.ShowRootItemInFileTree && g.showTree)
	if fc != nil && prevPath != "" {
		for i, n := range g.fileNodes {
			if n.Path == prevPath {
				fc.sel = i
				break
			}
		}
		fc.clampSel()
	}
}

func buildFlatListSorted(files []*File) *FileNode {
	root := &FileNode{}
	for _, f := range files {
		root.Children = append(root.Children, &FileNode{Path: f.Name, Name: f.Name, File: f})
	}
	sortTree(root)
	return root
}

func (g *Gui) refreshBranches() {
	g.branches = loadBranches(g.cfg.LocalBranchSortOrder)
	g.headBranch = nil
	for _, b := range g.branches {
		if b.Head {
			g.headBranch = b
		}
	}
	if c := g.ctx["localBranches"]; c != nil {
		c.clampSel()
	}
}

func (g *Gui) determineMainBranches() []string {
	var res []string
	for _, name := range g.cfg.MainBranches {
		if out, err := runGit("rev-parse", "--symbolic-full-name", name+"@{u}"); err == nil && strings.TrimSpace(out) != "" {
			res = append(res, strings.TrimSpace(out))
			continue
		}
		ref := "refs/remotes/origin/" + name
		if _, err := runGit("rev-parse", "--verify", "--quiet", ref); err == nil {
			res = append(res, ref)
			continue
		}
		ref = "refs/heads/" + name
		if _, err := runGit("rev-parse", "--verify", "--quiet", ref); err == nil {
			res = append(res, ref)
		}
	}
	return res
}

func (g *Gui) setCommitStatuses(commits []*Commit, ref string) {
	g.mainBranchRefs = g.determineMainBranches()
	unmerged := map[string]bool{}
	hasMain := len(g.mainBranchRefs) > 0
	if hasMain {
		args := append([]string{"rev-list", ref, "--not"}, g.mainBranchRefs...)
		out, _ := runGit(args...)
		for _, h := range strings.Split(trimNL(out), "\n") {
			if h != "" {
				unmerged[h] = true
			}
		}
	}
	unpushed := map[string]bool{}
	upstreamOK := false
	upRef := ref + "@{u}"
	if ref == "HEAD" {
		upRef = "HEAD@{u}"
	}
	if out, err := runGit("rev-list", ref, "--not", upRef); err == nil {
		upstreamOK = true
		for _, h := range strings.Split(trimNL(out), "\n") {
			if h != "" {
				unpushed[h] = true
			}
		}
	}
	for _, c := range commits {
		if c.Status == "rebasing" {
			continue
		}
		if !hasMain || unmerged[c.Hash] {
			if upstreamOK && unpushed[c.Hash] {
				c.Status = "unpushed"
			} else {
				c.Status = "pushed"
			}
		} else {
			c.Status = "merged"
		}
	}
}

func (g *Gui) refreshCommits() {
	limit := 300
	g.commits = loadCommits(limit, "HEAD", g.cfg.MainBranches, g.cfg.LogShowWholeGraph, g.cfg.LogOrder)
	g.setCommitStatuses(g.commits, "HEAD")
	g.rebuildCommitGraph()
	if c := g.ctx["commits"]; c != nil {
		c.clampSel()
	}
}

func (g *Gui) rebuildCommitGraph() {
	g.commitGraph = nil
}

func (g *Gui) refreshReflog() {
	g.reflog = loadReflogCommits(0)
	if c := g.ctx["reflogCommits"]; c != nil {
		c.clampSel()
	}
}

func (g *Gui) refreshStash() {
	g.stash = loadStash()
	if c := g.ctx["stash"]; c != nil {
		c.clampSel()
	}
}

func (g *Gui) refreshRemotes() {
	g.remotes = loadRemotes()
	if c := g.ctx["remotes"]; c != nil {
		c.clampSel()
	}
}

func (g *Gui) refreshTags() {
	g.tags = loadTags()
	if c := g.ctx["tags"]; c != nil {
		c.clampSel()
	}
}

func (g *Gui) refreshWorktrees() {
	g.worktrees = loadWorktrees()
	// put current first? lazygit: current worktree first
	var cur []*Worktree
	var rest []*Worktree
	for _, w := range g.worktrees {
		if w.IsCurrent {
			cur = append(cur, w)
		} else {
			rest = append(rest, w)
		}
	}
	g.worktrees = append(cur, rest...)
	if c := g.ctx["worktrees"]; c != nil {
		c.clampSel()
	}
}

func (g *Gui) refreshSubmodules() {
	g.submodules = loadSubmodules(g.repoRoot)
	if c := g.ctx["submodules"]; c != nil {
		c.clampSel()
	}
}

// ---------- command log ----------

var randomTips = []string{}

func (g *Gui) initCommandLog() {
	lines := []string{fgCyan.Sprint("You can hide/focus this panel by pressing '@'")}
	if g.cfg.ShowRandomTip && len(randomTips) > 0 {
		r := rand.New(rand.NewSource(time.Now().UnixNano()))
		tip := randomTips[r.Intn(len(randomTips))]
		lines = append(lines, "", fgYellow.Sprint("Random tip")+": "+fgGreen.Sprint(tip))
	}
	g.cmdLogLines = lines
}

func (g *Gui) logAction(action string) {
	g.cmdLogLines = append(g.cmdLogLines, fgYellow.Sprint(action))
}

func (g *Gui) logCommand(cmd string, cmdline bool) {
	if cmdline {
		g.cmdLogLines = append(g.cmdLogLines, "  "+cmd)
	} else {
		g.cmdLogLines = append(g.cmdLogLines, "  "+cmd)
	}
}

// runLogged runs a git command and logs it to the command log
func (g *Gui) runGitLogged(args ...string) (string, error) {
	g.logCommand("git "+quoteArgs(args), true)
	return runGitCombined(args...)
}

func quoteArgs(args []string) string {
	var parts []string
	for _, a := range args {
		parts = append(parts, shellQuoteIfNeeded(a))
	}
	return strings.Join(parts, " ")
}

func shellQuoteIfNeeded(a string) string {
	if a == "" {
		return "\"\""
	}
	if strings.ContainsAny(a, " \t\"'$`\\|&;<>()*?[]{}!#~\n") {
		return "\"" + strings.ReplaceAll(strings.ReplaceAll(a, "\\", "\\\\"), "\"", "\\\"") + "\""
	}
	return a
}

func (g *Gui) spinnerFrame() string {
	frames := g.cfg.SpinnerFrames
	if len(frames) == 0 {
		return ""
	}
	rate := g.cfg.SpinnerRate
	if rate <= 0 {
		rate = 50
	}
	idx := int(time.Now().UnixMilli()/int64(rate)) % len(frames)
	return frames[idx]
}

func absPath(p string) string {
	a, err := filepath.Abs(p)
	if err != nil {
		return p
	}
	return a
}
EOF

