}

func pluralS(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

func (g *Gui) isAnyModeActive() bool {
	return g.diffName != "" || len(g.cherryPicked) > 0
}

func (g *Gui) layout() {
	cur := g.currentContext()
	static := g.currentStaticContext()
	side := g.currentSideContext()
	curWindow := static.Window
	args := &arrangeArgs{
		width: g.w, height: g.h,
		currentWindow:       curWindow,
		currentSideWindow:   side.Window,
		currentStaticWindow: curWindow,
		splitMain:           g.splitMain,
		screenMode:          g.screenMode,
		appStatus:           g.appStatus,
		informationStr:      g.informationStr(),
		showExtras:          g.cfg.ShowCommandLog && !g.state.HideCommandLog,
		inSearchPrompt:      g.searchState != nil && g.searchState.typing,
		searchPrefix:        g.searchPrefix(),
		isAnyModeActive:     g.isAnyModeActive(),
		stashAccessed:       g.stashAccessed,
	}
	if cur.Key == "extras" || static.Key == "extras" {
		args.currentStaticWindow = "extras"
	}
	// update main content before layout (split state may change)
	g.updateMainContent()
	args.splitMain = g.splitMain
	dims := g.getWindowDimensions(args)

	for _, v := range g.views {
		v.Visible = false
		v.Focused = false
	}
	activeBorder := themeStyle(g.cfg.ActiveBorderColor)
	inactiveBorder := themeStyle(g.cfg.InactiveBorderColor)
	setFrame := func(v *View, focused bool) {
		if focused {
			v.FrameFg, v.FrameAttr = activeBorder.Fg, activeBorder.Attr
			if g.searchState != nil && g.searchState.view == v.Name {
				s := themeStyle(g.cfg.SearchingActiveBorderColor)
				v.FrameFg, v.FrameAttr = s.Fg, s.Attr
			}
		} else {
			v.FrameFg, v.FrameAttr = inactiveBorder.Fg, inactiveBorder.Attr
		}
		v.TabSelFg, v.TabSelAttr = activeBorder.Fg, activeBorder.Attr
	}
	place := func(v *View, d Dimensions, frame bool) {
		if frame {
			v.X0, v.Y0, v.X1, v.Y1 = d.X0, d.Y0, d.X1, d.Y1
		} else {
			v.X0, v.Y0, v.X1, v.Y1 = d.X0-1, d.Y0-1, d.X1+1, d.Y1+1
		}
		v.Visible = true
	}
	selBg := themeBgStyle(g.cfg.SelectedLineBgColor)
	inactiveSel := themeBgStyle(g.cfg.InactiveViewSelectedLineBgColor)

	jumpIdx := map[string]int{"status": 1, "files": 2, "branches": 3, "commits": 4, "stash": 5}
	for _, w := range sideWindows {
		d, ok := dims[w]
		if !ok {
			continue
		}
		c := g.windowContext(w)
		if c == nil {
			continue
		}
		v := c.View
		place(v, d, true)
		if d.Y1 < d.Y0 {
			v.Visible = false
			continue
		}
		focused := cur == c
		v.Focused = focused
		setFrame(v, focused)
		if g.cfg.ShowPanelJumps {
			v.TitlePrefix = "[" + strconv.Itoa(jumpIdx[w]) + "]"
		} else {
			v.TitlePrefix = ""
		}
		tabs := g.windowTabs(w)
		v.Tabs = nil
		v.TabIndex = 0
		isTab := false
		for i, t := range tabs {
			if t == c.Key {
				isTab = true
				v.TabIndex = i
			}
		}
		if isTab {
			for _, t := range tabs {
				v.Tabs = append(v.Tabs, g.ctx[t].Title)
			}
		} else {
			v.Title = g.contextTitle(c)
		}
		// content
		if c.render != nil {
			lines := c.render()
			v.SetLines(lines)
		}
		c.clampSel()
		v.SelLine = c.sel
		if c.rangeActive {
			a, b := c.selRange()
			v.RangeStart, v.RangeEnd = a, b
		} else {
			v.RangeStart, v.RangeEnd = -1, -1
		}
		v.Highlight = false
		if c.IsList {
			if focused {
				v.Highlight = true
				v.SelBg = selBg.Bg
				v.SelAttr = selBg.Attr | AttrBold
				if selBg.Bg == ColorDefault && selBg.Attr == 0 {
					v.SelAttr = AttrBold
				}
			} else if (cur.Kind == KindPopup || cur.Kind == KindMain) && side == c {
				v.Highlight = true
				v.SelBg = inactiveSel.Bg
				v.SelAttr = inactiveSel.Attr
			}
		}
		if c.footer && g.cfg.ShowListFooter && c.IsList {
			n := c.Len()
			if n == 0 {
				v.Footer = "0 of 0"
			} else {
				v.Footer = strconv.Itoa(c.sel+1) + " of " + strconv.Itoa(n)
			}
		} else {
			v.Footer = ""
		}
		g.ensureSelVisible(v, c)
	}

	// main windows
	g.layoutMain(dims, cur, setFrame, place)

	// extras
	if d, ok := dims["extras"]; ok {
		v := g.views["extras"]
		place(v, d, true)
		focused := cur.Key == "extras"
		setFrame(v, focused)
		v.SetLines(g.cmdLogLines)
		v.Title = "Command log"
		if !focused || g.commandLogFocusedAutoscroll {
			// autoscroll to bottom
			vh := v.ViewLinesHeight()
			ih := v.InnerHeight()
			if vh > ih {
				v.OY = vh - ih
			} else {
				v.OY = 0
			}
		}
	}

	// bottom line
	if d, ok := dims["options"]; ok && d.X1 >= d.X0 {
		v := g.views["options"]
		place(v, d, false)
		v.SetLines([]string{g.optionsString(v.InnerWidth())})
	}
	if d, ok := dims["information"]; ok {
		v := g.views["information"]
		place(v, d, false)
		v.SetLines([]string{" " + g.informationStr()})
		if g.isAnyModeActive() {
			v.SetLines([]string{g.informationStr()})
		}
	}
	if d, ok := dims["appStatus"]; ok && g.appStatus != "" && d.X1 >= d.X0 {
		v := g.views["appStatus"]
		place(v, d, false)
		v.SetLines([]string{fgCyan.Sprint(g.appStatus)})
	}
	if g.searchState != nil && g.searchState.typing {
		if d, ok := dims["searchPrefix"]; ok {
			v := g.views["searchPrefix"]
			place(v, d, false)
			v.SetLines([]string{fgGreen.Sprint(g.searchPrefix())})
		}
		if d, ok := dims["search"]; ok {
			v := g.views["search"]
			place(v, d, false)
			v.SetLines([]string{g.searchState.input.String()})
		}
	}

	// popups
	g.layoutPopups(cur, setFrame)

	// limit view
	if g.w < 10 || g.h < 10 {
		v := g.views["limit"]
		v.X0, v.Y0, v.X1, v.Y1 = 0, 0, g.w-1, g.h-1
		v.Visible = true
		v.SetLines([]string{"Not enough space to render panels"})
	}
}

func (g *Gui) contextTitle(c *Context) string {
	switch c.Key {
	case "subCommits":
		return g.subCommitsTitle
	case "commitFiles":
		return g.commitFilesTitle
	case "remoteBranches":
		if g.currentRemote != nil {
			return "Remote branches (" + g.currentRemote.Name + ")"
		}
	}
	return c.Title
}

func (g *Gui) ensureSelVisible(v *View, c *Context) {
	ih := v.InnerHeight()
	n := c.Len()
	if ih <= 0 {
		return
	}
	sel := c.sel
	margin := g.cfg.ScrollOffMargin
	if margin*2 >= ih {
		margin = (ih - 1) / 2
	}
	if margin < 0 {
		margin = 0
	}
	if g.cfg.ScrollOffBehavior == "jump" {
		margin = 0
	}
	if sel < v.OY+margin {
		v.OY = sel - margin
	}
	if sel > v.OY+ih-1-margin {
		v.OY = sel - ih + 1 + margin
	}
	if v.OY > n-ih {
		v.OY = n - ih
	}
	if v.OY < 0 {
		v.OY = 0
	}
}

func (g *Gui) optionsString(width int) string {
	items := g.optionsItems()
	width -= 4
	var b strings.Builder
	length := 0
	for i, it := range items {
		if i > 0 {
			b.WriteString(" | ")
			length += 3
		}
		if length+stringWidth(it)+1 > width {
			b.WriteString("…")
			break
		}
		b.WriteString(it)
		length += stringWidth(it)
	}
	return b.String()
}

func (g *Gui) render() {
	if g.t.suspended {
		return
	}
	g.layout()
	scr := NewScreen(g.w, g.h)
	cx, cy, show := 0, 0, false
	for _, name := range g.viewOrder {
		v := g.views[name]
		if !v.Visible {
			continue
		}
		v.draw(scr, false)
	}
	if x, y, ok := g.cursorPos(); ok {
		cx, cy, show = x, y, true
	}
	g.t.Flush(g.front, scr, g.fullRedraw, cx, cy, show)
	g.front = scr
	g.fullRedraw = false
}
EOF"}

