	var rows [][]string
	full := g.screenMode != ScreenNormal && g.currentSideContext().Key == "localBranches"
	for _, b := range g.branches {
		rows = append(rows, g.branchRow(b, w, full))
	}
	return renderDisplayStrings(rows)
}

func (g *Gui) renderRemotes() []string {
	var rows [][]string
	for _, r := range g.remotes {
		rows = append(rows, []string{fgDefault.Sprint(r.Name), fgBlue.Sprint(strconv.Itoa(len(r.Branches)) + " branches")})
	}
	return renderDisplayStrings(rows)
}

func (g *Gui) renderRemoteBranches() []string {
	var rows [][]string
	for _, b := range g.remoteBranches {
		rows = append(rows, []string{branchTextStyle(b.Name, g.cfg).Sprint(b.Name)})
	}
	return renderDisplayStrings(rows)
}

func (g *Gui) renderTags() []string {
	var rows [][]string
	for _, t := range g.tags {
		rows = append(rows, []string{fgDefault.Sprint(t.Name), fgYellow.Sprint(t.Message)})
	}
	return renderDisplayStrings(rows)
}

func (g *Gui) showGraph() bool {
	switch g.cfg.LogShowGraph {
	case "never":
		return false
	case "when-maximised":
		return g.screenMode != ScreenNormal
	}
	return true
}

func (g *Gui) branchHeads() map[string]bool {
	res := map[string]bool{}
	mains := map[string]bool{}
	for _, m := range g.cfg.MainBranches {
		mains[m] = true
	}
	for _, b := range g.branches {
		if b.Head || mains[b.Name] || b.CommitHash == "" {
			continue
		}
		res[b.CommitHash] = true
	}
	return res
}

func (g *Gui) renderCommits() []string {
	c := g.ctx["commits"]
	selHash := ""
	if c.sel < len(g.commits) && c.sel >= 0 && g.currentContext() == c {
		selHash = g.commits[c.sel].Hash
	}
	var graph []string
	if g.showGraph() {
		graph = g.renderGraph(g.commits, selHash)
	}
	full := g.screenMode != ScreenNormal && g.currentSideContext().Key == "commits"
	rows := g.commitRows(g.commits, graph, full, false, g.branchHeads())
	return renderDisplayStrings(rows)
}

func (g *Gui) renderSubCommits() []string {
	c := g.ctx["subCommits"]
	selHash := ""
	if c.sel < len(g.subCommits) && c.sel >= 0 && g.currentContext() == c {
		selHash = g.subCommits[c.sel].Hash
	}
	var graph []string
	if g.showGraph() {
		graph = g.renderGraph(g.subCommits, selHash)
	}
	full := g.screenMode != ScreenNormal && g.currentSideContext().Key == "subCommits"
	rows := g.commitRows(g.subCommits, graph, full, false, map[string]bool{})
	return renderDisplayStrings(rows)
}

func (g *Gui) renderReflog() []string {
	full := g.screenMode != ScreenNormal && g.currentSideContext().Key == "reflogCommits"
	rows := g.commitRows(g.reflog, nil, full, true, nil)
	return renderDisplayStrings(rows)
}

func (g *Gui) renderStash() []string {
	var rows [][]string
	for _, s := range g.stash {
		rows = append(rows, []string{fgCyan.Sprint(s.Recency), s.Name})
	}
	return renderDisplayStrings(rows)
}

func (g *Gui) renderCommitFiles() []string {
	var res []string
	for _, n := range g.commitFileNodes {
		res = append(res, g.commitFileLine(n))
	}
	return res
}

func (g *Gui) commitFileLine(n *FileNode) string {
	indent := strings.Repeat("  ", n.Depth)
	if n.IsDir() {
		arrow := "▼"
		if g.collapsedDirs["cf:"+n.Path] {
			arrow = "▶"
		}
		return indent + arrow + " " + n.Name
	}
	f := n.File
	st := f.ShortStatus
	col := styleDefault
	switch st {
	case "A":
		col = fgGreen
	case "D":
		col = fgRed
	case "M":
		col = fgYellow
	}
	name := n.Name
	if !g.showTree {
		name = f.Name
	}
	return indent + col.Sprint(st) + " " + name
}

// ---------- selection helpers ----------

func (g *Gui) selectedFileNode() *FileNode {
	c := g.ctx["files"]
	if c.sel >= 0 && c.sel < len(g.fileNodes) {
		return g.fileNodes[c.sel]
	}
	return nil
}

func (g *Gui) selectedBranch() *Branch {
	c := g.ctx["localBranches"]
