package main

import (
	"os"
	"os/exec"
	"strconv"
	"strings"
	"time"
)

func fileExists(p string) bool {
	_, err := os.Stat(p)
	return err == nil
}

func splitArgs(s string) []string {
	var args []string
	var cur strings.Builder
	inS, inD := false, false
	has := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '\'' && !inD:
			inS = !inS
			has = true
		case c == '"' && !inS:
			inD = !inD
			has = true
		case c == '\\' && inD && i+1 < len(s):
			i++
			cur.WriteByte(s[i])
		case (c == ' ' || c == '\t') && !inS && !inD:
			if cur.Len() > 0 || has {
				args = append(args, cur.String())
				cur.Reset()
				has = false
			}
		default:
			cur.WriteByte(c)
		}
	}
	if cur.Len() > 0 || has {
		args = append(args, cur.String())
	}
	return args
}

func runCmdOutput(args []string) string {
	if len(args) == 0 {
		return ""
	}
	cmd := exec.Command(args[0], args[1:]...)
	cmd.Env = append(os.Environ(), "GIT_OPTIONAL_LOCKS=0")
	out, _ := cmd.CombinedOutput()
	return string(out)
}

func (g *Gui) diffArgs() []string {
	args := []string{"--submodule", "--no-ext-diff", "--unified=" + strconv.Itoa(g.diffContext)}
	if g.ignoreWhitespace {
		args = append(args, "--ignore-all-space")
	}
	return args
}

func (g *Gui) fileDiff(f *File, cached bool, path string) string {
	args := []string{"-c", "diff.noprefix=false", "diff"}
	args = append(args, g.diffArgs()...)
	args = append(args, "--color=always")
	if cached {
		args = append(args, "--cached")
	}
	if f != nil && !f.Tracked && !f.HasStagedChanges && !cached {
		args = append(args, "--no-index", "--", "/dev/null", path)
	} else {
		args = append(args, "--find-renames="+strconv.Itoa(g.renameThreshold)+"%", "--", path)
		if f != nil && f.IsRename() && cached {
			args = append(args, f.PreviousName)
		}
	}
	out, _ := runGit(args...)
	return out
}

func (g *Gui) branchLog(name string) string {
	cmdStr := strings.ReplaceAll(g.cfg.BranchLogCmd, "{{branchName}}", shellQuoteName(name))
	args := splitArgs(cmdStr)
	return runCmdOutput(args)
}

func shellQuoteName(n string) string {
	return "\"" + n + "\""
}

func (g *Gui) showCommit(hash string) string {
	args := []string{"-c", "color.ui=always", "-c", "core.quotepath=false", "show", "--submodule", "--color=always", "--no-ext-diff", "--stat", "--decorate", "-p",
		"--unified=" + strconv.Itoa(g.diffContext), "--find-renames=" + strconv.Itoa(g.renameThreshold) + "%"}
	if g.ignoreWhitespace {
		args = append(args, "--ignore-all-space")
	}
	args = append(args, hash, "--")
	out, _ := runGit(args...)
	return out
}

func (g *Gui) setMain(title, content string, itemKey string) {
	v := g.views["main"]
	v.Title = title
	if g.mainItemKey != itemKey {
		v.OY = 0
		v.OX = 0
		g.mainItemKey = itemKey
	}
	v.SetContent(content)
	g.splitMain = false
	g.views["secondary"].Clear()
}

func (g *Gui) setSplit(title1, c1, title2, c2, itemKey string) {
	v := g.views["main"]
	v.Title = title1
	v2 := g.views["secondary"]
	v2.Title = title2
	if g.mainItemKey != itemKey {
		v.OY, v.OX, v2.OY, v2.OX = 0, 0, 0, 0
		g.mainItemKey = itemKey
	}
	v.SetContent(c1)
	v2.SetContent(c2)
	g.splitMain = true
}

func (g *Gui) updateMainContent() {
	cur := g.currentContext()
	static := g.currentStaticContext()
	if static.Key == "staging" || static.Key == "stagingSecondary" {
		g.updateStagingContent()
		return
	}
	side := g.currentSideContext()
	_ = cur
	key := side.Key + ":" + strconv.Itoa(side.sel) + ":" + strconv.Itoa(g.diffContext) + ":" + strconv.FormatBool(g.ignoreWhitespace) + ":" + strconv.Itoa(g.renameThreshold) + ":" + strconv.Itoa(g.w) + "x" + strconv.Itoa(g.h)
	if key == g.mainKey {
		return
	}
	g.mainKey = key
	switch side.Key {
	case "status":
		g.setMain("Status", g.statusDashboard(), "status")
	case "files":
		n := g.selectedFileNode()
		if n == nil {
			g.setMain("", "", "files:none")
			g.views["main"].Title = ""
			return
		}
		path := n.Path
		if path == "" {
			path = "."
		}
		var f *File
		if !n.IsDir() {
			f = n.File
		}
		hasStaged := n.anyStaged()
		hasUnstaged := n.anyUnstaged()
		ik := "files:" + path
		if f != nil && f.HasInlineConflicts {
			g.setMain("Merge conflicts", g.fileDiff(f, false, path), ik)
			return
		}
		if hasStaged && hasUnstaged || (g.cfg.SplitDiff == "always") {
			unstaged := g.fileDiff(f, false, path)
			staged := g.fileDiff(f, true, path)
			g.setSplit("Unstaged changes", unstaged, "Staged changes", staged, ik)
			return
		}
		if hasStaged {
			g.setMain("Staged changes", g.fileDiff(f, true, path), ik)
		} else {
			g.setMain("Unstaged changes", g.fileDiff(f, false, path), ik)
		}
	case "worktrees":
		w := g.selectedWorktree()
		if w == nil {
			g.setMain("", "", "wt:none")
			return
		}
		name := fgGreen.Sprint(w.Name)
		if w.IsMain {
			name += " (main)"
		}
		branch := w.Branch
		bl := fgYellow.Sprint(branch)
		if branch == "" {
			bl = fgYellow.Sprint("(detached HEAD)")
		}
		content := "Name:    " + name + "\nBranch:  " + bl + "\nPath:    " + fgCyan.Sprint(w.Path)
		if w.IsPathMissing {
			content += "\n" + fgRed.Sprint("Path does not exist")
		}
		g.setMain("Worktree", content, "wt:"+w.Path)
	case "submodules":
		if len(g.submodules) == 0 {
			g.setMain("", "", "sm:none")
			return
		}
		s := g.submodules[side.sel]
		content := "Name: " + fgGreen.Sprint(s.Name) + "\nPath: " + fgYellow.Sprint(s.Path) + "\nUrl:  " + fgCyan.Sprint(s.Url)
		g.setMain("Submodule", content, "sm:"+s.Name)
	case "localBranches":
		b := g.selectedBranch()
		if b == nil {
			g.setMain("", "", "br:none")
			return
		}
		name := b.Name
		if b.DetachedHead {
			name = b.CommitHash
		}
		g.setMain("Log", g.branchLog(name), "br:"+b.Name)
	case "remotes":
		r := g.selectedRemote()
		if r == nil {
			g.setMain("", "", "rm:none")
			return
		}
		content := fgGreen.Sprint(r.Name) + "\nUrls:\n" + strings.Join(r.Urls, "\n")
		g.setMain("Remote", content, "rm:"+r.Name)
	case "remoteBranches":
		rb := g.selectedRemoteBranch()
		if rb == nil {
			g.setMain("", "", "rb:none")
			return
		}
		g.setMain("Remote branch", g.branchLog(rb.FullName()), "rb:"+rb.FullName())
	case "tags":
		t := g.selectedTag()
		if t == nil {
			g.setMain("", "", "tag:none")
			return
		}
		g.setMain("Tag", g.tagContent(t), "tag:"+t.Name)
	case "commits":
		c := g.selectedCommit()
		if c == nil {
			g.setMain("", "", "c:none")
			return
		}
		g.setMain("Patch", g.showCommit(c.Hash), "c:"+c.Hash)
	case "subCommits":
		c := g.selectedSubCommit()
		if c == nil {
			g.setMain("", "", "sc:none")
			return
		}
		g.setMain("Patch", g.showCommit(c.Hash), "sc:"+c.Hash)
	case "reflogCommits":
		c := g.selectedReflog()
		if c == nil {
			g.setMain("", "", "rf:none")
			return
		}
		g.setMain("Reflog Entry", g.showCommit(c.Hash), "rf:"+c.Hash+":"+strconv.Itoa(side.sel))
	case "stash":
		s := g.selectedStash()
		if s == nil {
			g.setMain("", "", "st:none")
			return
		}
		args := []string{"stash", "show", "-p", "--stat", "-u", "--color=always", "--unified=" + strconv.Itoa(g.diffContext)}
		if g.ignoreWhitespace {
			args = append(args, "--ignore-all-space")
		}
		args = append(args, "--find-renames="+strconv.Itoa(g.renameThreshold)+"%", "refs/stash@{"+strconv.Itoa(s.Index)+"}")
		out, _ := runGit(args...)
		header := fgYellow.Sprint(s.RefName() + ": " + s.Name)
		g.setMain("Stash", header+"\n\n"+out, "st:"+s.Hash)
	case "commitFiles":
		n := g.selectedCommitFileNode()
		if n == nil {
			g.setMain("", "", "cf:none")
			return
		}
		path := n.Path
		args := []string{"-c", "color.ui=always", "diff", "--submodule", "--no-ext-diff", "--unified=" + strconv.Itoa(g.diffContext), "--color=always"}
		if g.ignoreWhitespace {
			args = append(args, "--ignore-all-space")
		}
		args = append(args, "--find-renames="+strconv.Itoa(g.renameThreshold)+"%")
		args = append(args, g.commitFilesRef+"^", g.commitFilesRef, "--", path)
		if g.commitFilesParentRef != "" {
			args = []string{"-c", "color.ui=always", "diff", "--submodule", "--no-ext-diff", "--unified=" + strconv.Itoa(g.diffContext), "--color=always", "--find-renames=" + strconv.Itoa(g.renameThreshold) + "%", g.commitFilesParentRef, g.commitFilesRef, "--", path}
		}
		out, _ := runGit(args...)
		g.setMain("Patch", out, "cf:"+g.commitFilesRef+":"+path)
	default:
		g.setMain("", "", "none")
	}
}

func (g *Gui) tagContent(t *Tag) string {
	var b strings.Builder
	if t.IsAnnotated {
		b.WriteString("Annotated tag: " + fgYellow.Bold().Sprint(t.Name) + "\n\n")
		out, _ := runGit("for-each-ref", "--format=%(taggername) %(taggeremail)%00%(taggerdate)%00%(contents)", "refs/tags/"+t.Name)
		parts := strings.SplitN(strings.TrimRight(out, "\n"), "\x00", 3)
		if len(parts) == 3 {
			b.WriteString("Tagger:     " + parts[0] + "\n")
			b.WriteString("TaggerDate: " + parts[1] + "\n\n")
			b.WriteString(strings.TrimRight(parts[2], "\n") + "\n")
		}
		b.WriteString("\n---\n\n")
	} else {
		b.WriteString("Lightweight tag: " + fgYellow.Bold().Sprint(t.Name) + "\n\n---\n\n")
	}
	b.WriteString(g.branchLog(t.Name))
	return b.String()
}

var logoLines = []string{
	"   _                       _ _",
	"  | |                     (_) |",
	"  | | __ _ _____   _  __ _ _| |_",
	"  | |/ _` |_  / | | |/ _` | | __|",
	"  | | (_| |/ /| |_| | (_| | | |_",
	"  |_|\\__,_/___|\\__, |\\__, |_|\\__|",
	"                __/ | __/ |",
	"               |___/ |___/",
}

func (g *Gui) statusDashboard() string {
	if g.cfg.StatusPanelView == "allBranchesLog" || g.statusPanelMainOverride == "allBranchesLog" {
		cmds := g.cfg.AllBranchesLogCmds
		if len(cmds) > 0 {
			return runCmdOutput(splitArgs(cmds[g.allBranchLogIdx%len(cmds)]))
		}
	}
	var b strings.Builder
	b.WriteString("\n")
	b.WriteString(strings.Join(logoLines, "\n"))
	b.WriteString("\n\n")
	b.WriteString("Copyright " + strconv.Itoa(time.Now().Year()) + " Jesse Duffield\n\n")
	b.WriteString("Keybindings: https://github.com/jesseduffield/lazygit/blob/master/docs/keybindings\n\n")
	b.WriteString("Config Options: https://github.com/jesseduffield/lazygit/blob/master/docs/Config.md\n\n")
	b.WriteString("Tutorial: https://youtu.be/VDXvbHZYeKY\n\n")
	b.WriteString("Raise an Issue: https://github.com/jesseduffield/lazygit/issues\n\n")
	b.WriteString("Release Notes: https://github.com/jesseduffield/lazygit/releases\n\n")
	b.WriteString(fgMagenta.Sprint("Become a sponsor: https://github.com/sponsors/jesseduffield"))
	return b.String()
}
EOF"}

