func (g *Gui) searchPrefix() string {
	if g.searchState != nil && g.searchState.filter {
		return "Filter: "
	}
	return "Search: "
}

// ---------- menu ----------

func (g *Gui) showMenu(title string, items []*menuItem) {
	m := &menuState{title: title, items: items}
	// select first selectable
	for i, it := range items {
		if !it.IsSection {
			m.sel = i
			break
		}
	}
	g.menu = m
	g.pushContext(g.ctx["menu"])
}

func (g *Gui) closeMenu() {
	if g.menu == nil {
		return
	}
	g.menu = nil
	g.removeContext("menu")
}

func (g *Gui) menuLines() ([]string, int) {
	m := g.menu
	if m == nil {
		return nil, 0
	}
	var rows [][]string
	hasKeys := false
	for _, it := range m.items {
		if it.Key != "" {
			hasKeys = true
		}
	}
	keyW := 0
	for _, it := range m.items {
		if w := stringWidth(it.Key); w > keyW {
			keyW = w
		}
	}
	var lines []string
	if m.keyMenu {
		for _, it := range m.items {
			if it.IsSection {
				if it.Label == "" {
					lines = append(lines, "")
				} else {
					lines = append(lines, strings.Repeat(" ", keyW+1)+fgGreen.Bold().Sprint("--- "+it.Label+" ---"))
				}
				continue
			}
			k := it.Key
			pad := keyW - stringWidth(k)
			line := strings.Repeat(" ", pad) + fgCyan.Sprint(k) + " " + it.Label
			lines = append(lines, line)
		}
		return lines, keyW
	}
	for _, it := range m.items {
		var row []string
		if hasKeys {
			row = append(row, fgCyan.Sprint(it.Key))
		}
		if len(it.Columns) > 0 {
			row = append(row, it.Columns...)
		} else {
			label := it.Label
			if it.Disabled != "" {
				label = FgStyle(ColorDefault).Strike().Sprint(label)
			}
			row = append(row, label)
		}
		rows = append(rows, row)
	}
	lines = renderDisplayStrings(rows)
	return lines, keyW
}

func (g *Gui) menuSelectable(i int) bool {
	if g.menu == nil || i < 0 || i >= len(g.menu.items) {
		return false
	}
	return !g.menu.items[i].IsSection
}

func (g *Gui) menuMove(delta int) {
	m := g.menu
	n := len(m.items)
	i := m.sel
	for {
		i += delta
		if i < 0 || i >= n {
			return
		}
		if g.menuSelectable(i) {
			m.sel = i
			return
		}
	}
}

func (g *Gui) menuItemCount() int {
	if g.menu == nil {
		return 0
	}
	n := 0
	for _, it := range g.menu.items {
		if !it.IsSection {
			n++
		}
	}
	return n
}

func (g *Gui) menuSelIndexAmongItems() int {
	n := 0
	for i, it := range g.menu.items {
		if i == g.menu.sel {
			return n
		}
		if !it.IsSection {
			n++
		}
	}
	return n
}

func (g *Gui) menuPress(it *menuItem) {
	if it == nil || it.IsSection {
		return
	}
	if it.Disabled != "" {
		g.showError(it.Disabled)
		return
	}
	g.closeMenu()
	if it.OnPress != nil {
		it.OnPress()
	}
}

// ---------- confirmation / prompt ----------

func (g *Gui) showConfirm(title, message string, onConfirm func()) {
	g.confirm = &confirmState{title: title, message: message, onConfirm: onConfirm}
	g.pushContext(g.ctx["confirmation"])
}

func (g *Gui) showConfirmWithCancel(title, message string, onConfirm, onCancel func()) {
	g.confirm = &confirmState{title: title, message: message, onConfirm: onConfirm, onCancel: onCancel}
	g.pushContext(g.ctx["confirmation"])
}

func (g *Gui) showError(msg string) {
	g.confirm = &confirmState{title: "Error", message: fgRed.Sprint(msg), isError: true}
	g.pushContext(g.ctx["confirmation"])
}

func (g *Gui) showPrompt(title, initial string, onConfirm func(string)) {
	e := NewEditor(initial)
	g.confirm = &confirmState{title: title, prompt: true, input: e}
	g.confirm.onConfirm = func() { onConfirm(e.String()) }
	g.pushContext(g.ctx["confirmation"])
}

func (g *Gui) closeConfirm() {
	g.confirm = nil
	g.removeContext("confirmation")
}

func (g *Gui) showToast(msg string) {
	g.toast = msg
}
EOF"}

