{"command":"cd /workspace/src; cat > editor.go <<'EOF'
package main

import "strings"

type Editor struct {
	lines     [][]rune
	cy, cx    int
	multiline bool
}

func NewEditor(s string) *Editor {
	e := &Editor{}
	e.SetText(s)
	return e
}

func (e *Editor) SetText(s string) {
	e.lines = nil
	for _, l := range strings.Split(s, "\n") {
		e.lines = append(e.lines, []rune(l))
	}
	e.cy = len(e.lines) - 1
	e.cx = len(e.lines[e.cy])
}

func (e *Editor) String() string {
	var parts []string
	for _, l := range e.lines {
		parts = append(parts, string(l))
	}
	return strings.Join(parts, "\n")
}

func (e *Editor) Insert(r rune) {
	l := e.lines[e.cy]
	nl := make([]rune, 0, len(l)+1)
	nl = append(nl, l[:e.cx]...)
	nl = append(nl, r)
	nl = append(nl, l[e.cx:]...)
	e.lines[e.cy] = nl
	e.cx++
}

func (e *Editor) InsertString(s string) {
	for _, r := range s {
		if r == '\n' {
			if e.multiline {
				e.Newline()
			}
			continue
		}
		if r == '\r' {
			continue
		}
		e.Insert(r)
	}
}

func (e *Editor) Newline() {
	l := e.lines[e.cy]
