{"command":"cd /workspace/src; cat > popuplayout.go <<'EOF'
package main

import (
	"strconv"
	"strings"
)

func (g *Gui) popupPanelWidth() int {
	w := g.w
	pw := 4 * w / 7
	minW := 80
	if pw < minW {
		if w-2 < minW {
			pw = w - 2
		} else {
			pw = minW
		}
	}
	return pw
}

func (g *Gui) popupDims(panelWidth, panelHeight int) (int, int, int, int) {
	w, h := g.w, g.h
	if panelHeight > h*3/4 {
		panelHeight = h * 3 / 4
	}
	return w/2 - panelWidth/2,
		h/2 - panelHeight/2 - panelHeight%2 - 1,
		w/2 + panelWidth/2,
		h/2 + panelHeight/2
}

func messageHeight(msg string, width int) int {
	return len(wrapStringLines(msg, width))
}

func (g *Gui) layoutMain(dims map[string]Dimensions, cur *Context, setFrame func(*View, bool), place func(*View, Dimensions, bool)) {
	static := g.currentStaticContext()
	mainName, secName := "main", "secondary"
	if static.Key == "staging" || static.Key == "stagingSecondary" {
		mainName, secName = "staging", "stagingSecondary"
	}
	if d, ok := dims["main"]; ok {
		v := g.views[mainName]
		place(v, d, true)
		focused := static.Key == mainName
		setFrame(v, focused)
		if mainName == "main" {
			v.TitlePrefix = ""
			if g.cfg.ShowPanelJumps {
				v.TitlePrefix = "[0]"
			}
		} else {
			v.TitlePrefix = ""
		}
		v.Tabs = nil
		if static.Key == "staging" || static.Key == "stagingSecondary" {
			v.Highlight = g.staging != nil && static.Key == "staging"
		} else {
			v.Highlight = false
		}
		g.clampMainOrigin(v)
	}
	if d, ok := dims["secondary"]; ok {
		v := g.views[secName]
		place(v, d, true)
		focused := static.Key == secName
		setFrame(v, focused)
		v.TitlePrefix = ""
		v.Tabs = nil
		v.Highlight = static.Key == "stagingSecondary" && g.staging != nil
		g.clampMainOrigin(v)
	}
}

func (g *Gui) clampMainOrigin(v *View) {
	n := v.ViewLinesHeight()
	ih := v.InnerHeight()
	maxOY := n - ih
	if v.CanScrollPastBottom {
		maxOY = n - 1
	}
	if v.OY > maxOY {
		v.OY = maxOY
	}
	if v.OY < 0 {
		v.OY = 0
	}
}

func (g *Gui) layoutPopups(cur *Context, setFrame func(*View, bool)) {
	// keep popup views ordered on top: menu, confirmation etc.
	if g.commitMsg != nil {
		g.layoutCommitMsg(cur, setFrame)
	}
	if g.menu != nil {
		g.layoutMenu(cur, setFrame)
	}
	if g.confirm != nil {
		g.layoutConfirm(cur, setFrame)
	}
}

func (g *Gui) layoutMenu(cur *Context, setFrame func(*View, bool)) {
	m := g.menu
	v := g.views["menu"]
	pw := g.popupPanelWidth()
	contentWidth := pw - 2
	promptLines := 0
	if m.prompt != "" {
		promptLines = messageHeight(m.prompt, contentWidth)
	}
	count := g.menuItemCount()
	x0, y0, x1, y1 := g.popupDims(pw, count+3+promptLines)
	menuBottom := y1 - 3
	v.X0, v.Y0, v.X1, v.Y1 = x0, y0, x1, menuBottom
	v.Visible = true
	v.Title = m.title
	setFrame(v, cur.Key == "menu")
	lines, _ := g.menuLines()
	v.SetLines(lines)
	v.Highlight = true
	sb := themeBgStyle(g.cfg.SelectedLineBgColor)
	v.SelBg = sb.Bg
	v.SelAttr = sb.Attr | AttrBold
	v.SelLine = m.sel
	v.RangeStart, v.RangeEnd = -1, -1
	if count > 0 {
		v.Footer = strconv.Itoa(g.menuSelIndexAmongItems()+1) + " of " + strconv.Itoa(count)
	} else {
		v.Footer = "0 of 0"
	}
	// keep selection visible
	ih := v.InnerHeight()
	if m.sel < v.OY {
		v.OY = m.sel
	}
	if m.sel >= v.OY+ih {
		v.OY = m.sel - ih + 1
	}
	if v.OY > len(lines)-ih {
		v.OY = maxInt(0, len(lines)-ih)
	}
	// tooltip
	tip := ""
	if m.sel >= 0 && m.sel < len(m.items) {
		it := m.items[m.sel]
		tip = it.Tooltip
		if it.Disabled != "" {
			if tip != "" {
				tip += "\n\n"
			}
			tip += fgRed.Sprint("Disabled: " + it.Disabled)
		}
	}
	tv := g.views["tooltip"]
	if tip != "" {
		th := messageHeight(tip, contentWidth) + 2
		top := menuBottom + 1
		tv.X0, tv.Y0, tv.X1, tv.Y1 = x0, top, x1, top+th-1
		tv.Visible = true
		tv.SetContent(tip)
		tv.Title = ""
		tv.FrameFg, tv.FrameAttr = ColorDefault, 0
	}
}

func (g *Gui) layoutConfirm(cur *Context, setFrame func(*View, bool)) {
	c := g.confirm
	v := g.views["confirmation"]
	pw := g.popupPanelWidth()
	var h int
	if c.prompt {
		h = 1
		if c.input.multiline {
			h = maxInt(1, len(c.input.lines))
		}
	} else {
		h = messageHeight(c.message, pw-2)
	}
	x0, y0, x1, y1 := g.popupDims(pw, h)
	v.X0, v.Y0, v.X1, v.Y1 = x0, y0, x1, y1
	v.Visible = true
	v.Title = c.title
	setFrame(v, true)
	v.Highlight = false
	v.Footer = ""
	if c.prompt {
		v.Wrap = false
		v.SetLines(strings.Split(c.input.String(), "\n"))
		if c.mask {
			v.Mask = '*'
		} else {
			v.Mask = 0
		}
		// horizontal scroll to keep cursor visible
		iw := v.InnerWidth()
		cx := c.input.cx
		if cx-v.OX >= iw {
			v.OX = cx - iw + 1
		}
		if cx < v.OX {
			v.OX = cx
		}
	} else {
		v.Mask = 0
		v.Wrap = true
		v.OX = 0
		v.SetContent(c.message)
	}
	if c.suggestions != nil {
		sugs := c.suggestions(c.input.String())
		sv := g.views["suggestions"]
		if len(sugs) > 0 {
			sh := minInt(len(sugs), 11)
			sv.X0, sv.Y0, sv.X1, sv.Y1 = x0, y1, x1, y1+sh+1
			sv.Visible = true
			sv.Title = "Suggestions"
			sv.SetLines(sugs)
			sv.FrameFg, sv.FrameAttr = ColorDefault, 0
			sv.Highlight = false
			sv.Footer = ""
		}
	}
}

func (g *Gui) layoutCommitMsg(cur *Context, setFrame func(*View, bool)) {
	cm := g.commitMsg
	pw := g.popupPanelWidth()
	sv := g.views["commitMessage"]
	dv := g.views["commitDescription"]
	descLines := 8
	x0, y0, x1, y1 := g.popupDims(pw, 1+descLines+2)
	_ = y1
	sv.X0, sv.Y0, sv.X1, sv.Y1 = x0, y0, x1, y0+2
	sv.Visible = true
	sv.Title = cm.title
	sv.Subtitle = " " + strconv.Itoa(len([]rune(cm.summary.String()))) + " "
	setFrame(sv, !cm.focusDesc)
	sv.SetLines([]string{cm.summary.String()})
	sv.Wrap = false
	sv.Highlight = false
	dv.X0, dv.Y0, dv.X1, dv.Y1 = x0, y0+3, x1, y1
	dv.Visible = true
	dv.Title = "Commit description"
	dv.Subtitle = "Press <tab> to toggle focus, <c-o> to open menu"
	setFrame(dv, cm.focusDesc)
	dv.SetLines(strings.Split(cm.description.String(), "\n"))
	dv.Highlight = false
}

func (g *Gui) cursorPos() (int, int, bool) {
	if g.confirm != nil && g.confirm.prompt {
		v := g.views["confirmation"]
		return v.X0 + 1 + g.confirm.input.cx - v.OX, v.Y0 + 1 + g.confirm.input.cy, true
	}
	if g.commitMsg != nil && g.menu == nil && g.confirm == nil {
		if g.commitMsg.focusDesc {
			v := g.views["commitDescription"]
			return v.X0 + 1 + g.commitMsg.description.cx, v.Y0 + 1 + g.commitMsg.description.cy, true
		}
		v := g.views["commitMessage"]
		return v.X0 + 1 + g.commitMsg.summary.cx, v.Y0 + 1, true
	}
	if g.searchState != nil && g.searchState.typing {
		v := g.views["search"]
		return v.X0 + 1 + g.searchState.input.cx, v.Y0 + 1, true
	}
	return 0, 0, false
}
EOF"}

