package main

import (
	"strings"
)

type binding struct {
	cfgKey   string
	key      string // literal key (used if cfgKey == "")
	fn       func()
	short    string // options bar description
	display  bool
	disabled func() string
}

func (g *Gui) bkey(b *binding) string {
	if b.cfgKey != "" {
		return g.cfg.Key(b.cfgKey)
	}
	return b.key
}

func (g *Gui) matches(b *binding, k Key) bool {
	return keyMatches(g.bkey(b), k)
}

// options bar items for the current context
func (g *Gui) optionsItems() []string {
	cur := g.currentContext()
	var res []string
	for _, b := range g.localBindings(cur) {
		if !b.display {
			continue
		}
		if b.disabled != nil && b.disabled() != "" {
			continue
		}
		res = append(res, b.short+": "+keyLabel(g.bkey(b)))
	}
	switch cur.Key {
	case "menu":
		return []string{"Execute: " + g.cfg.Key("universal.confirm"), "Close/Cancel: " + g.cfg.Key("universal.return")}
	case "confirmation":
		if g.confirm != nil && g.confirm.prompt {
			return []string{"Confirm: " + g.cfg.Key("universal.confirm"), "Close/Cancel: " + g.cfg.Key("universal.return")}
		}
		return []string{"Confirm: " + g.cfg.Key("universal.confirm"), "Close/Cancel: " + g.cfg.Key("universal.return"), "Copy to clipboard: " + g.cfg.Key("universal.copyToClipboard")}
	case "commitMessage", "commitDescription":
		return nil
	}
	res = append(res, "Keybindings: "+g.cfg.Key("universal.optionMenu-alt1"))
	return res
}

func (g *Gui) handlePaste(s string) {
	if g.confirm != nil && g.confirm.prompt {
		g.confirm.input.InsertString(s)
		return
	}
	if g.commitMsg != nil {
		if g.commitMsg.focusDesc {
			g.commitMsg.description.InsertString(s)
		} else {
			g.commitMsg.summary.InsertString(strings.ReplaceAll(s, "\n", " "))
		}
		return
	}
	if g.searchState != nil && g.searchState.typing {
		g.searchState.input.InsertString(s)
		g.onSearchInputChanged()
	}
}

func (g *Gui) handleMouse(ev Event) {
	if !g.cfg.MouseEvents {
		return
	}
	switch ev.MBtn {
	case MouseWheelDown, MouseWheelUp:
		delta := g.cfg.ScrollHeight
		if ev.MBtn == MouseWheelUp {
			delta = -delta
		}
		// find view under cursor
		for i := len(g.viewOrder) - 1; i >= 0; i-- {
			v := g.views[g.viewOrder[i]]
			if !v.Visible || ev.MX < v.X0 || ev.MX > v.X1 || ev.MY < v.Y0 || ev.MY > v.Y1 {
				continue
			}
			if v.Name == "main" || v.Name == "secondary" || v.Name == "extras" || v.Name == "staging" || v.Name == "stagingSecondary" {
				g.scrollView(v, delta)
			} else {
				for _, c := range g.ctx {
					if c.View == v && c.IsList && c.Kind == KindSide {
						if delta > 0 {
							v.OY += delta
						} else {
							v.OY += delta
						}
						if v.OY < 0 {
							v.OY = 0
						}
					}
				}
			}
			return
		}
	case MouseLeft:
		if g.currentContext().Kind == KindPopup {
			return
		}
		for i := len(g.viewOrder) - 1; i >= 0; i-- {
			v := g.views[g.viewOrder[i]]
			if !v.Visible || ev.MX < v.X0 || ev.MX > v.X1 || ev.MY < v.Y0 || ev.MY > v.Y1 {
				continue
			}
			for _, c := range g.ctx {
				if c.View == v && c.Kind == KindSide {
					if g.currentContext() != c {
						g.pushContext(c)
					}
					if c.IsList && ev.MY > v.Y0 && ev.MY < v.Y1 {
						idx := ev.MY - v.Y0 - 1 + v.OY
						if idx < c.Len() {
							c.sel = idx
							g.onSelectionChanged(c)
						}
					}
					return
				}
			}
			if v.Name == "main" || v.Name == "secondary" {
				g.focusMain()
			}
			return
		}
	}
}

func (g *Gui) scrollView(v *View, delta int) {
	v.OY += delta
	if v.OY < 0 {
		v.OY = 0
	}
	g.clampMainOrigin(v)
}

func (g *Gui) handleKey(k Key) {
	if g.confirm != nil {
		g.handleConfirmKey(k)
		return
	}
	if g.menu != nil {
		g.handleMenuKey(k)
		return
	}
	if g.commitMsg != nil {
		g.handleCommitMsgKey(k)
		return
	}
	if g.searchState != nil && g.searchState.typing {
		g.handleSearchKey(k)
		return
	}
	cur := g.currentContext()
	for _, b := range g.localBindings(cur) {
		if g.matches(b, k) {
			if b.disabled != nil {
				if r := b.disabled(); r != "" {
					g.showError(r)
					return
				}
			}
			b.fn()
			return
		}
	}
	if g.handleGlobalKey(k) {
		return
	}
	if cur.IsList && g.handleListNav(cur, k) {
		return
	}
}

func (g *Gui) keyIs(k Key, names ...string) bool {
	for _, n := range names {
		if keyMatches(g.cfg.Key(n), k) {
			return true
		}
	}
	return false
}

func (g *Gui) handleListNav(c *Context, k Key) bool {
	n := c.Len()
	move := func(newSel int) {
		if n == 0 {
			return
		}
		if newSel < 0 {
			newSel = 0
		}
		if newSel >= n {
			newSel = n - 1
		}
		if c.rangeActive && !c.rangeSticky {
			c.rangeActive = false
		}
		if newSel != c.sel {
			c.sel = newSel
			g.onSelectionChanged(c)
		}
	}
	ih := c.View.InnerHeight()
	switch {
	case g.keyIs(k, "universal.prevItem", "universal.prevItem-alt"):
		move(c.sel - 1)
	case g.keyIs(k, "universal.nextItem", "universal.nextItem-alt"):
		move(c.sel + 1)
	case g.keyIs(k, "universal.prevPage"):
		move(c.sel - ih)
	case g.keyIs(k, "universal.nextPage"):
		move(c.sel + ih)
	case g.keyIs(k, "universal.gotoTop", "universal.gotoTop-alt"):
		move(0)
	case g.keyIs(k, "universal.gotoBottom", "universal.gotoBottom-alt"):
		move(n - 1)
	case g.keyIs(k, "universal.toggleRangeSelect"):
		if c.rangeActive {
			c.rangeActive = false
		} else if n > 0 {
			c.rangeActive = true
			c.rangeSticky = true
			c.rangeStart = c.sel
		}
		g.mainKey = ""
	case g.keyIs(k, "universal.rangeSelectDown"):
		if n == 0 {
			return true
		}
		if !c.rangeActive {
			c.rangeActive = true
			c.rangeSticky = false
			c.rangeStart = c.sel
		}
		if c.sel < n-1 {
			c.sel++
		}
		g.mainKey = ""
	case g.keyIs(k, "universal.rangeSelectUp"):
		if n == 0 {
			return true
		}
		if !c.rangeActive {
			c.rangeActive = true
			c.rangeSticky = false
			c.rangeStart = c.sel
		}
		if c.sel > 0 {
			c.sel--
		}
		g.mainKey = ""
	case g.keyIs(k, "universal.scrollLeft"):
		if c.View.OX > 0 {
			c.View.OX--
		}
	case g.keyIs(k, "universal.scrollRight"):
		c.View.OX++
	default:
		return false
	}
	return true
}

func (g *Gui) onSelectionChanged(c *Context) {
	g.mainKey = ""
}

func (g *Gui) sideWindowIndex(w string) int {
	for i, s := range sideWindows {
		if s == w {
			return i
		}
	}
	return 0
}

func (g *Gui) handleGlobalKey(k Key) bool {
	cur := g.currentContext()
	switch {
	case g.keyIs(k, "universal.quit", "universal.quit-alt1"):
		g.handleQuit()
	case g.keyIs(k, "universal.quitWithoutChangingDirectory"):
		g.quitting = true
	case g.keyIs(k, "universal.return"):
		g.handleEscape()
	case g.keyIs(k, "universal.optionMenu", "universal.optionMenu-alt1"):
		g.openKeybindingsMenu()
	case k.Code == KeyRune && k.Mod == 0 && g.jumpIndex(k) >= 0:
		idx := g.jumpIndex(k)
		w := sideWindows[idx]
		if g.cfg.Key("gui.switchTabsWithPanelJumpKeys") == "true" {
		}
		g.focusWindow(w)
	case g.keyIs(k, "universal.focusMainView"):
		g.focusMain()
	case cur.Kind == KindSide && g.keyIs(k, "universal.nextBlock", "universal.nextBlock-alt", "universal.nextBlock-alt2"):
		i := g.sideWindowIndex(cur.Window)
		g.focusWindow(sideWindows[(i+1)%len(sideWindows)])
	case cur.Kind == KindSide && g.keyIs(k, "universal.prevBlock", "universal.prevBlock-alt", "universal.prevBlock-alt2"):
		i := g.sideWindowIndex(cur.Window)
		g.focusWindow(sideWindows[(i+len(sideWindows)-1)%len(sideWindows)])
	case cur.Kind == KindSide && g.keyIs(k, "universal.nextTab"):
		g.switchTab(1)
	case cur.Kind == KindSide && g.keyIs(k, "universal.prevTab"):
		g.switchTab(-1)
	case g.keyIs(k, "universal.nextScreenMode"):
		g.screenMode = (g.screenMode + 1) % 3
		g.mainKey = ""
	case g.keyIs(k, "universal.prevScreenMode"):
		g.screenMode = (g.screenMode + 2) % 3
		g.mainKey = ""
	case g.keyIs(k, "universal.scrollUpMain", "universal.scrollUpMain-alt1", "universal.scrollUpMain-alt2"):
		g.scrollMain(-g.cfg.ScrollHeight)
	case g.keyIs(k, "universal.scrollDownMain", "universal.scrollDownMain-alt1", "universal.scrollDownMain-alt2"):
		g.scrollMain(g.cfg.ScrollHeight)
	case g.keyIs(k, "universal.refresh"):
		g.refreshAll()
	case g.keyIs(k, "universal.increaseContextInDiffView"):
		g.diffContext++
		g.toast = ""
		g.mainKey = ""
	case g.keyIs(k, "universal.decreaseContextInDiffView"):
		if g.diffContext > 0 {
			g.diffContext--
		}
		g.mainKey = ""
	case g.keyIs(k, "universal.increaseRenameSimilarityThreshold"):
		g.renameThreshold = minInt(100, g.renameThreshold+5)
		g.refreshFiles()
		g.mainKey = ""
	case g.keyIs(k, "universal.decreaseRenameSimilarityThreshold"):
		g.renameThreshold = maxInt(5, g.renameThreshold-5)
		g.refreshFiles()
		g.mainKey = ""
	case g.keyIs(k, "universal.toggleWhitespaceInDiffView"):
		g.ignoreWhitespace = !g.ignoreWhitespace
		g.mainKey = ""
	case g.keyIs(k, "universal.extrasMenu"):
		g.openExtrasMenu()
	case g.keyIs(k, "universal.executeShellCommand"):
		g.openShellCommandPrompt()
	case g.keyIs(k, "universal.pushFiles"):
		g.handlePush()
	case g.keyIs(k, "universal.pullFiles"):
		g.handlePull()
	case g.keyIs(k, "universal.createRebaseOptionsMenu"):
		g.openMergeRebaseMenu()
	case g.keyIs(k, "universal.diffingMenu", "universal.diffingMenu-alt"):
		g.openDiffingMenu()
	case g.keyIs(k, "universal.filteringMenu"):
		g.openFilteringMenu()
	case g.keyIs(k, "universal.openRecentRepos"):
		g.openRecentReposMenu()
	case g.keyIs(k, "universal.undo"):
		g.handleUndo()
	case g.keyIs(k, "universal.redo"):
		g.handleRedo()
	case g.keyIs(k, "universal.startSearch"):
		g.startSearch(cur)
	case g.keyIs(k, "universal.nextMatch"):
		g.nextMatch(1)
	case g.keyIs(k, "universal.prevMatch"):
		g.nextMatch(-1)
	case g.keyIs(k, "universal.suspendApp"):
		g.suspend()
	case g.keyIs(k, "universal.createPatchOptionsMenu"):
		g.showError("No patch created yet. To start building a patch, use 'space' on a commit file or enter to add specific lines")
	case g.keyIs(k, "universal.cyclePagers"):
		g.showError("No pagers configured")
	default:
		return false
	}
	return true
}

func (g *Gui) jumpIndex(k Key) int {
	for i := 0; i < 5; i++ {
		key := g.cfg.Key("universal.jumpToBlock." + itoa(i))
		if keyMatches(key, k) {
			return i
		}
	}
	return -1
}

func itoa(i int) string {
	return strings.TrimSpace(strings.Repeat(" ", 0) + string(rune('0'+i)))
}

func (g *Gui) switchTab(delta int) {
	cur := g.currentContext()
	tabs := g.windowTabs(cur.Window)
	if len(tabs) == 0 {
		return
	}
	idx := -1
	for i, t := range tabs {
		if t == cur.Key {
			idx = i
		}
	}
	if idx < 0 {
		// in a sub-context; tabs relative to parent
		idx = 0
		if cur.parentKey != "" {
			for i, t := range tabs {
				if t == cur.parentKey {
					idx = i
				}
			}
		}
	}
	ni := (idx + delta + len(tabs)) % len(tabs)
	g.pushContext(g.ctx[tabs[ni]])
}

func (g *Gui) scrollMain(delta int) {
	static := g.currentStaticContext()
	v := g.views["main"]
	if static.Key == "secondary" {
		v = g.views["secondary"]
	}
	if static.Key == "staging" || static.Key == "stagingSecondary" {
		v = g.views[static.Key]
	}
	g.scrollView(v, delta)
}

func (g *Gui) focusMain() {
	side := g.currentSideContext()
	if side.Key == "files" {
		n := g.selectedFileNode()
		if n != nil && !n.IsDir() {
			g.enterStaging(n.File, false)
			return
		}
	}
	g.pushContext(g.ctx["main"])
}

func (g *Gui) handleQuit() {
	if g.cfg.ConfirmOnQuit {
		g.showConfirm("", "Are you sure you want to quit?", func() { g.quitting = true })
		return
	}
	g.quitting = true
}

func (g *Gui) handleEscape() {
	cur := g.currentContext()
	switch cur.Key {
	case "main", "secondary", "extras":
		g.popContext()
		return
	case "subCommits", "remoteBranches":
		if cur.parentKey != "" {
			g.pushContext(g.ctx[cur.parentKey])
			return
		}
	case "commitFiles":
		if cur.parentKey != "" {
			g.pushContext(g.ctx[cur.parentKey])
			return
		}
	}
	if g.searchState != nil {
		g.clearSearch()
		return
	}
	if cur.IsList && cur.rangeActive {
		cur.rangeActive = false
		g.mainKey = ""
		return
	}
	if g.diffName != "" {
		g.diffName = ""
		g.mainKey = ""
		return
	}
	if len(g.cherryPicked) > 0 {
		g.cherryPicked = map[string]bool{}
		return
	}
	if g.cfg.QuitOnTopLevelReturn {
		g.handleQuit()
	}
}
