func (g *Gui) handleMenuKey(k Key) {
	m := g.menu
	switch {
	case g.keyIs(k, "universal.return"):
		g.closeMenu()
		if m.onClose != nil {
			m.onClose()
		}
		return
	case g.keyIs(k, "universal.confirmMenu"), k.Code == KeyRune && k.Ch == ' ' && !m.keyMenu && false:
		if m.sel >= 0 && m.sel < len(m.items) {
			g.menuPress(m.items[m.sel])
		}
		return
	case g.keyIs(k, "universal.prevItem", "universal.prevItem-alt"):
		g.menuMove(-1)
		return
	case g.keyIs(k, "universal.nextItem", "universal.nextItem-alt"):
		g.menuMove(1)
		return
	case g.keyIs(k, "universal.gotoTop", "universal.gotoTop-alt"):
		for i := range m.items {
			if g.menuSelectable(i) {
				m.sel = i
				break
			}
		}
		return
	case g.keyIs(k, "universal.gotoBottom", "universal.gotoBottom-alt"):
		for i := len(m.items) - 1; i >= 0; i-- {
			if g.menuSelectable(i) {
				m.sel = i
				break
			}
		}
		return
	case g.keyIs(k, "universal.prevPage"):
		ih := g.views["menu"].InnerHeight()
		for i := 0; i < ih; i++ {
			g.menuMove(-1)
		}
		return
	case g.keyIs(k, "universal.nextPage"):
		ih := g.views["menu"].InnerHeight()
		for i := 0; i < ih; i++ {
			g.menuMove(1)
		}
		return
	}
	// item hotkeys
	if !m.keyMenu {
		for _, it := range m.items {
			if it.Key != "" && keyMatches(it.Key, k) {
				g.menuPress(it)
				return
			}
		}
	} else {
		for _, it := range m.items {
			if it.IsSection || it.Key == "" {
				continue
			}
			if keyMatches(it.Key, k) {
				g.menuPress(it)
				return
			}
		}
	}
	if g.keyIs(k, "universal.quit") && !m.keyMenu {
		g.closeMenu()
		g.handleQuit()
	}
}

func (g *Gui) handleConfirmKey(k Key) {
	c := g.confirm
	if c.prompt {
		switch {
		case g.keyIs(k, "universal.return"):
			g.closeConfirm()
			if c.onCancel != nil {
				c.onCancel()
			}
			return
		case k.Code == KeyEnter && k.Mod == 0:
			g.closeConfirm()
			if c.onConfirm != nil {
				c.onConfirm()
			}
			return
		case k.Code == KeyTab && c.suggestions != nil:
			sugs := c.suggestions(c.input.String())
			if len(sugs) > 0 {
				c.input.SetText(decolorise(sugs[0]))
			}
			return
		}
		c.input.HandleKey(k)
		return
	}
	switch {
	case g.keyIs(k, "universal.return"):
		g.closeConfirm()
		if c.onCancel != nil {
			c.onCancel()
		}
	case g.keyIs(k, "universal.confirm"), k.Code == KeyRune && k.Ch == 'y' && false:
		g.closeConfirm()
		if c.onConfirm != nil {
			c.onConfirm()
		}
	case g.keyIs(k, "universal.quit") && c.isError:
		g.closeConfirm()
	}
}

func (g *Gui) handleCommitMsgKey(k Key) {
	cm := g.commitMsg
	switch {
	case g.keyIs(k, "universal.return"):
		g.commitMsgDraft = cm.summary.String()
		g.commitDescDraft = cm.description.String()
		g.commitMsg = nil
		g.removeContext("commitMessage")
		g.removeContext("commitDescription")
		return
	case k.Code == KeyTab:
		cm.focusDesc = !cm.focusDesc
		return
	case k.Code == KeyEnter && k.Mod == 0 && !cm.focusDesc:
		summary := cm.summary.String()
		if strings.TrimSpace(summary) == "" {
			g.showError("Commit message cannot be empty")
			return
		}
		desc := cm.description.String()
		g.commitMsg = nil
		g.removeContext("commitMessage")
		g.removeContext("commitDescription")
		g.commitMsgDraft, g.commitDescDraft = "", ""
		if cm.onConfirm != nil {
			cm.onConfirm(summary, desc)
		}
		return
	case k.Code == KeyEnter && k.Mod == 0 && cm.focusDesc:
		cm.description.Newline()
		return
	}
	if cm.focusDesc {
		cm.description.HandleKey(k)
	} else {
		cm.summary.HandleKey(k)
	}
}
