package main

import (
	"os"
	"os/exec"
	"strings"
	"syscall"
)

func (g *Gui) openKeybindingsMenu() {
	cur := g.currentContext()
	key := cur.menuKey
	if key == "" {
		key = cur.Key
	}
	kb, ok := keybindingMenus[key]
	if !ok {
		kb = keybindingMenus["files"]
	}
	var items []*menuItem
	addSection := func(name string, entries []kbEntry, first bool) {
		if len(entries) == 0 {
			return
		}
		if !first {
			items = append(items, &menuItem{IsSection: true, Label: ""})
		}
		items = append(items, &menuItem{IsSection: true, Label: name})
		for _, e := range entries {
			e := e
			items = append(items, &menuItem{Key: e.Key, Label: e.Desc, Tooltip: e.Tooltip, OnPress: func() {
				g.executeKeyFromMenu(e.Key)
			}})
		}
	}
	addSection("Local", kb.Local, true)
	addSection("Global", kb.Global, len(kb.Local) == 0)
	addSection("Navigation", kb.Navigation, false)
	g.showMenu("Keybindings", items)
	g.menu.keyMenu = true
}

func (g *Gui) executeKeyFromMenu(label string) {
	if k, ok := parseKeyString(label); ok {
		g.handleKey(k)
	}
}

