func (g *Gui) showIntroPopup() {
	done := func() {
		g.state.StartupPopupVersion = 5
		g.state.Save()
	}
	g.confirm = &confirmState{title: "", message: g.introMessage(), onConfirm: done, onCancel: done}
	g.pushContext(g.ctx["confirmation"])
}

func (g *Gui) suspend() {
	g.t.Suspend()
	syscall.Kill(os.Getpid(), syscall.SIGTSTP)
	g.t.Resume()
	g.fullRedraw = true
}

func (g *Gui) runSubprocess(args []string) error {
	g.t.Suspend()
	cmd := exec.Command(args[0], args[1:]...)
	cmd.Stdin, cmd.Stdout, cmd.Stderr = os.Stdin, os.Stdout, os.Stderr
