package main

import "strings"

func (g *Gui) startSearch(c *Context) {
	if !c.IsList && c.Kind != KindMain {
		return
	}
	filter := false
	switch c.Key {
	case "files", "worktrees", "submodules", "localBranches", "remotes", "remoteBranches", "tags", "reflogCommits", "stash":
		filter = c.Key != "files"
	}
	g.searchState = &searchState{view: c.View.Name, typing: true, input: NewEditor(""), filter: filter}
}

func (g *Gui) handleSearchKey(k Key) {
	s := g.searchState
	switch {
	case k.Code == KeyEsc:
		g.clearSearch()
		return
	case k.Code == KeyEnter:
		s.typing = false
		s.query = s.input.String()
		if s.query == "" {
			g.clearSearch()
		}
		return
	}
	s.input.HandleKey(k)
	g.onSearchInputChanged()
}

func (g *Gui) onSearchInputChanged() {
	s := g.searchState
	if s == nil {
		return
	}
	s.query = s.input.String()
	cur := g.currentContext()
	if !cur.IsList || s.filter {
		return
	}
	lines := cur.render()
	s.matches = nil
	q := strings.ToLower(s.query)
	for i, l := range lines {
		if q != "" && strings.Contains(strings.ToLower(decolorise(l)), q) {
			s.matches = append(s.matches, i)
		}
	}
	if len(s.matches) > 0 {
		for _, m := range s.matches {
			if m >= cur.sel {
				cur.sel = m
				g.mainKey = ""
				return
			}
		}
		cur.sel = s.matches[0]
		g.mainKey = ""
	}
}

func (g *Gui) nextMatch(d int) {
	s := g.searchState
	if s == nil || len(s.matches) == 0 {
		return
	}
	cur := g.currentContext()
	idx := 0
	for i, m := range s.matches {
		if m == cur.sel {
			idx = i
		}
	}
	idx = (idx + d + len(s.matches)) % len(s.matches)
	cur.sel = s.matches[idx]
	g.mainKey = ""
}

func (g *Gui) clearSearch() {
	g.searchState = nil
}
