func (g *Gui) toggleStageSelected() {
	n := g.selectedFileNode()
	if n == nil {
		return
	}
	if n.IsDir() {
		path := n.Path
		if path == "" {
			path = "."
		}
		if n.anyUnstaged() {
			g.logAction("Stage file")
			g.runGitLogged("add", "--", path)
		} else {
			g.logAction("Unstage file")
			g.unstagePaths(n.Files(), []string{path})
		}
	} else {
		f := n.File
		if f.HasMergeConflicts {
			g.logAction("Stage file")
			g.runGitLogged("add", "--", f.Name)
		} else if f.HasUnstagedChanges {
			g.logAction("Stage file")
			g.runGitLogged("add", "--", f.Name)
		} else {
			g.logAction("Unstage file")
			g.unstagePaths([]*File{f}, []string{f.Name})
		}
	}
	g.refreshFiles()
	g.mainKey = ""
}

func (g *Gui) headExists() bool {
	_, err := runGit("rev-parse", "--verify", "--quiet", "HEAD")
	return err == nil
}

func (g *Gui) unstagePaths(files []*File, paths []string) {
	if len(files) == 1 && len(paths) == 1 && paths[0] == files[0].Name {
		f := files[0]
		if !f.Tracked || !g.headExists() {
			g.runGitLogged("rm", "--cached", "--force", "--", f.Name)
			return
		}
		if f.IsRename() {
			g.runGitLogged("reset", "HEAD", "--", f.Name, f.PreviousName)
			return
		}
		g.runGitLogged("reset", "HEAD", "--", f.Name)
		return
	}
	if !g.headExists() {
		g.runGitLogged(append([]string{"rm", "--cached", "--force", "-r", "--"}, paths...)...)
		return
	}
	g.runGitLogged(append([]string{"reset", "HEAD", "--"}, paths...)...)
}

func (g *Gui) toggleStageAll() {
	anyUnstaged := false
	for _, f := range g.files {
		if f.HasUnstagedChanges {
			anyUnstaged = true
		}
	}
	if anyUnstaged {
		g.logAction("Stage all files")
		g.runGitLogged("add", "-A")
	} else {
		g.logAction("Unstage all files")
		if g.headExists() {
			g.runGitLogged("reset")
		} else {
			g.runGitLogged("rm", "--cached", "--force", "-r", "--", ".")
		}
	}
	g.refreshFiles()
	g.mainKey = ""
}

func (g *Gui) filesEnter() {
