				if msg != "" {
					args = append(args, "-m", msg)
				}
				g.runGitLogged(args...)
				g.refreshAll()
			})
		}},
		{Key: "U", Label: "Stash all changes including untracked files", OnPress: func() {
			g.showPrompt("Stash changes", "", func(msg string) {
				g.logAction("Stash all changes including untracked files")
				args := []string{"stash", "push", "--include-untracked"}
				if msg != "" {
					args = append(args, "-m", msg)
				}
				g.runGitLogged(args...)
				g.refreshAll()
			})
		}},
		{Key: "s", Label: "Stash staged changes", OnPress: func() {
			g.showPrompt("Stash changes", "", func(msg string) {
				g.logAction("Stash staged changes")
				args := []string{"stash", "push", "--staged"}
				if msg != "" {
					args = append(args, "-m", msg)
				}
				g.runGitLogged(args...)
				g.refreshAll()
			})
		}},
		{Key: "u", Label: "Stash unstaged changes", OnPress: func() {
			g.showPrompt("Stash changes", "", func(msg string) {
				g.logAction("Stash unstaged changes")
				args := []string{"stash", "push", "--keep-index"}
				if msg != "" {
					args = append(args, "-m", msg)
				}
				g.runGitLogged(args...)
				g.refreshAll()
			})
		}},
		{Label: "Cancel"},
	}
	g.showMenu("Stash options", items)
}

func (g *Gui) openIgnoreMenu() {
	n := g.selectedFileNode()
	if n == nil {
		return
	}
	path := n.Path
	items := []*menuItem{
		{Key: "i", Label: "Add to .gitignore", OnPress: func() {
			g.logAction("Ignore file")
			appendLine(".gitignore", path)
			g.refreshFiles()
		}},
		{Key: "e", Label: "Add to .git/info/exclude", OnPress: func() {
			g.logAction("Exclude file")
			appendLine(g.gitDir+"/info/exclude", path)
			g.refreshFiles()
		}},
		{Label: "Cancel"},
	}
	g.showMenu("Ignore or exclude file", items)
}

func appendLine(file, line string) {
	data, _ := os.ReadFile(file)
	s := string(data)
	if s != "" && !strings.HasSuffix(s, "\n") {
		s += "\n"
	}
	s += line + "\n"
	os.WriteFile(file, []byte(s), 0o644)
}
