func (g *Gui) toggleStageSelected() {
	n := g.selectedFileNode()
	if n == nil {
		return
	}
	if n.IsDir() {
		path := n.Path
		if path == "" {
			path = "."
		}
		if n.anyUnstaged() {
			g.logAction("Stage file")
			g.runGitLogged("add", "--", path)
		} else {
			g.logAction("Unstage file")
			g.unstagePaths(n.Files(), []string{path})
		}
	} else {
		f := n.File
		if f.HasMergeConflicts {
			g.logAction("Stage file")
			g.runGitLogged("add", "--", f.Name)
		} else if f.HasUnstagedChanges {
			g.logAction("Stage file")
			g.runGitLogged("add", "--", f.Name)
		} else {
			g.logAction("Unstage file")
			g.unstagePaths([]*File{f}, []string{f.Name})
		}
	}
	g.refreshFiles()
	g.mainKey = ""
}

func (g *Gui) headExists() bool {
	_, err := runGit("rev-parse", "--verify", "--quiet", "HEAD")
	return err == nil
}

func (g *Gui) unstagePaths(files []*File, paths []string) {
	if len(files) == 1 && len(paths) == 1 && paths[0] == files[0].Name {
		f := files[0]
		if !f.Tracked || !g.headExists() {
			g.runGitLogged("rm", "--cached", "--force", "--", f.Name)
			return
		}
		if f.IsRename() {
			g.runGitLogged("reset", "HEAD", "--", f.Name, f.PreviousName)
			return
		}
		g.runGitLogged("reset", "HEAD", "--", f.Name)
		return
	}
	if !g.headExists() {
		g.runGitLogged(append([]string{"rm", "--cached", "--force", "-r", "--"}, paths...)...)
		return
	}
	g.runGitLogged(append([]string{"reset", "HEAD", "--"}, paths...)...)
}

func (g *Gui) toggleStageAll() {
	anyUnstaged := false
	for _, f := range g.files {
		if f.HasUnstagedChanges {
			anyUnstaged = true
		}
	}
	if anyUnstaged {
		g.logAction("Stage all files")
		g.runGitLogged("add", "-A")
	} else {
		g.logAction("Unstage all files")
		if g.headExists() {
			g.runGitLogged("reset")
		} else {
			g.runGitLogged("rm", "--cached", "--force", "-r", "--", ".")
		}
	}
	g.refreshFiles()
	g.mainKey = ""
}

func (g *Gui) filesEnter() {
	n := g.selectedFileNode()
	if n == nil {
		return
	}
	if n.IsDir() {
		g.collapsedDirs[n.Path] = !g.collapsedDirs[n.Path]
		g.fileNodes = flattenTree(g.fileRoot, g.collapsedDirs, g.cfg.ShowRootItemInFileTree && g.showTree)
		g.mainKey = ""
		return
	}
	g.enterStaging(n.File, false)
}

func (g *Gui) toggleTreeView() {
	g.showTree = !g.showTree
	g.refreshFiles()
	g.mainKey = ""
}

func (g *Gui) collapseAll() {
	var walk func(n *FileNode)
	walk = func(n *FileNode) {
		if n.IsDir() {
			if n.Path != "" {
				g.collapsedDirs[n.Path] = true
			}
			for _, c := range n.Children {
				walk(c)
			}
		}
	}
	walk(g.fileRoot)
	g.fileNodes = flattenTree(g.fileRoot, g.collapsedDirs, g.cfg.ShowRootItemInFileTree && g.showTree)
	g.ctx["files"].clampSel()
	g.mainKey = ""
}

func (g *Gui) expandAll() {
	g.collapsedDirs = map[string]bool{}
	g.fileNodes = flattenTree(g.fileRoot, g.collapsedDirs, g.cfg.ShowRootItemInFileTree && g.showTree)
	g.mainKey = ""
}

func (g *Gui) anyStagedFiles() bool {
	for _, f := range g.files {
		if f.HasStagedChanges {
			return true
		}
	}
	return false
}

func (g *Gui) handleCommitPress() { g.handleCommitPressOpts(false) }

func (g *Gui) handleCommitPressOpts(noVerify bool) {
	if len(g.files) == 0 {
		g.showError("There are no files to commit")
		return
	}
	if !g.anyStagedFiles() {
		if g.cfg.SkipNoStagedFilesWarning {
			g.logAction("Stage all files")
			g.runGitLogged("add", "-A")
			g.refreshFiles()
			g.openCommitMessage(noVerify)
			return
		}
		g.showConfirm("No files staged", "You have not staged any files. Commit all files?", func() {
			g.logAction("Stage all files")
			g.runGitLogged("add", "-A")
			g.refreshFiles()
			g.openCommitMessage(noVerify)
		})
		return
	}
	g.openCommitMessage(noVerify)
}

func (g *Gui) openCommitMessage(noVerify bool) {
	summary := g.commitMsgDraft
	desc := g.commitDescDraft
	if summary == "" && desc == "" {
		summary = g.commitPrefix()
	}
	cm := &commitMsgState{summary: NewEditor(summary), description: NewEditor(desc), title: "Commit summary"}
	cm.description.multiline = true
	cm.onConfirm = func(s, d string) {
		g.doCommit(s, d, noVerify)
	}
	g.commitMsg = cm
	g.pushContext(g.ctx["commitMessage"])
}

func (g *Gui) commitPrefix() string {
	if strings.TrimSpace(g.cfg.SkipHookPrefix) == "" {
		return ""
	}
	return ""
}

func (g *Gui) doCommit(summary, desc string, noVerify bool) {
	g.logAction("Commit")
	args := []string{"commit"}
	if noVerify || (g.cfg.SkipHookPrefix != "" && strings.HasPrefix(summary, g.cfg.SkipHookPrefix)) {
		args = append(args, "--no-verify")
	}
	if g.cfg.SignOff {
		args = append(args, "--signoff")
	}
	args = append(args, "-m", summary)
	if strings.TrimSpace(desc) != "" {
		args = append(args, "-m", desc)
	}
	out, err := g.runGitLogged(args...)
	if err != nil {
		g.showError(strings.TrimSpace(out))
	}
	g.refreshAll()
}

func (g *Gui) commitWithEditor() {
	g.runSubprocess([]string{"git", "commit"})
	g.refreshAll()
}

func (g *Gui) handleAmend() {
	if len(g.commits) == 0 {
		g.showError("There are no commits to amend")
		return
	}
	g.showConfirm("Amend last commit", "Are you sure you want to amend last commit? Afterwards, you can change the commit message from the commits panel.", func() {
		g.logAction("Amend commit")
		out, err := g.runGitLogged("commit", "--amend", "--no-edit", "--allow-empty")
		if err != nil {
			g.showError(strings.TrimSpace(out))
		}
		g.refreshAll()
	})
}

func (g *Gui) editSelectedFile() {
	n := g.selectedFileNode()
	if n == nil || n.IsDir() {
		return
	}
	g.editFile(n.Path)
}

func (g *Gui) editFile(path string) {
	editor := g.cfg.OsEdit
	if editor != "" {
		cmd := strings.ReplaceAll(editor, "{{filename}}", shellQuoteIfNeeded(path))
		g.runSubprocessNoPrompt([]string{"sh", "-c", cmd})
		g.refreshAll()
		return
	}
	ed := os.Getenv("GIT_EDITOR")
	if ed == "" {
		if out, err := runGit("config", "core.editor"); err == nil {
			ed = strings.TrimSpace(out)
		}
	}
	if ed == "" {
		ed = os.Getenv("VISUAL")
	}
	if ed == "" {
		ed = os.Getenv("EDITOR")
	}
	if ed == "" {
		ed = "vi"
	}
	g.runSubprocessNoPrompt([]string{"sh", "-c", ed + " " + shellQuoteIfNeeded(path)})
	g.refreshAll()
}

func (g *Gui) runSubprocessNoPrompt(args []string) {
	save := g.cfg.PromptToReturnFromSubprocess
	g.cfg.PromptToReturnFromSubprocess = false
	g.runSubprocess(args)
	g.cfg.PromptToReturnFromSubprocess = save
}

func (g *Gui) openDiscardMenu() {
	n := g.selectedFileNode()
	if n == nil {
		return
	}
	name := n.Path
	if name == "" {
		name = "."
	}
	if !n.IsDir() && n.File.HasMergeConflicts {
		g.showError("Cannot discard changes in a file with merge conflicts")
		return
	}
	items := []*menuItem{
		{Key: "x", Label: "Discard all changes", Tooltip: "Discard both staged and unstaged changes in '" + name + "'.", OnPress: func() {
			g.logAction("Discard all changes in file")
			g.discardAll(n)
			g.refreshFiles()
			g.mainKey = ""
		}},
	}
	if n.anyStaged() && n.anyUnstaged() || n.IsDir() || (n.File != nil && n.File.HasStagedChanges && n.File.HasUnstagedChanges) {
		items = append(items, &menuItem{Key: "u", Label: "Discard unstaged changes", Tooltip: "Discard unstaged changes in '" + name + "'.", OnPress: func() {
			g.logAction("Discard unstaged changes in file")
			g.discardUnstaged(n)
			g.refreshFiles()
			g.mainKey = ""
		}})
	} else if n.File != nil && !n.File.HasStagedChanges {
		items = append(items, &menuItem{Key: "u", Label: "Discard unstaged changes", Tooltip: "Discard unstaged changes in '" + name + "'.", OnPress: func() {
			g.logAction("Discard unstaged changes in file")
			g.discardUnstaged(n)
			g.refreshFiles()
			g.mainKey = ""
		}})
	}
	items = append(items, &menuItem{Label: "Cancel"})
	g.showMenu("Discard changes", items)
}

func (g *Gui) discardAll(n *FileNode) {
	if n.IsDir() {
		path := n.Path
		if path == "" {
			path = "."
		}
		anyTracked := false
		for _, f := range n.Files() {
			if f.Tracked {
				anyTracked = true
			}
		}
		if anyTracked && g.headExists() {
			g.runGitLogged("reset", "--", path)
			g.runGitLogged("checkout", "--", path)
		}
		g.runGitLogged("clean", "-fd", "--", path)
		return
	}
	f := n.File
	if f.IsRename() {
		g.runGitLogged("reset", "--", f.Name, f.PreviousName)
		g.runGitLogged("checkout", "--", f.PreviousName)
		os.Remove(f.Name)
		return
	}
	if f.Added && !f.Tracked {
		if f.HasStagedChanges {
			g.runGitLogged("rm", "--cached", "--force", "--", f.Name)
		}
		os.RemoveAll(f.Name)
		return
	}
	if f.ShortStatus == "A " || f.ShortStatus == "AM" || f.ShortStatus == "AD" {
		g.runGitLogged("rm", "--cached", "--force", "--", f.Name)
		os.RemoveAll(f.Name)
		return
	}
	if f.HasStagedChanges {
		g.runGitLogged("reset", "--", f.Name)
	}
	g.runGitLogged("checkout", "--", f.Name)
}

func (g *Gui) discardUnstaged(n *FileNode) {
	path := n.Path
	if path == "" {
		path = "."
	}
	if n.IsDir() {
		g.runGitLogged("checkout", "--", path)
		g.runGitLogged("clean", "-fd", "--", path)
		return
	}
	f := n.File
	if !f.Tracked {
		os.RemoveAll(f.Name)
		return
	}
	g.runGitLogged("checkout", "--", f.Name)
}

func (g *Gui) openResetMenu() {
	items := []*menuItem{
		{Key: "x", Columns: []string{"Nuke working tree", fgRed.Sprint("git reset --hard HEAD && git clean -fd")}, Tooltip: "If you want to make all the changes in the worktree go away, this is the way to do it. If there are dirty submodule changes this will stash those changes in the submodule(s).", OnPress: func() {
			g.logAction("Nuke working tree")
			g.runGitLogged("reset", "--hard", "HEAD")
			g.runGitLogged("clean", "-fd")
			g.refreshAll()
		}},
		{Key: "u", Columns: []string{"Discard unstaged changes", fgRed.Sprint("git checkout -- .")}, Tooltip: "This will discard all unstaged changes in the worktree, leaving staged changes intact.", OnPress: func() {
			g.logAction("Discard unstaged changes")
			g.runGitLogged("checkout", "--", ".")
			g.refreshAll()
		}},
		{Key: "c", Columns: []string{"Discard untracked files", fgRed.Sprint("git clean -fd")}, Tooltip: "This will delete all untracked files and directories.", OnPress: func() {
			g.logAction("Discard untracked files")
			g.runGitLogged("clean", "-fd")
			g.refreshAll()
		}},
		{Key: "S", Columns: []string{"Discard staged changes", fgRed.Sprint("stash staged and drop stash")}, Tooltip: "This will discard all staged changes in the worktree, leaving unstaged changes intact.", OnPress: func() {
			g.logAction("Discard staged changes")
			g.runGitLogged("stash", "push", "--staged")
			g.runGitLogged("stash", "drop")
			g.refreshAll()
		}},
		{Key: "s", Columns: []string{"Soft reset", fgRed.Sprint("git reset --soft HEAD")}, Tooltip: "Reset HEAD to the chosen commit, and keep the changes between the current and chosen commit as staged changes.", OnPress: func() {
			g.logAction("Soft reset")
			g.runGitLogged("reset", "--soft", "HEAD")
			g.refreshAll()
		}},
		{Key: "m", Columns: []string{"mixed reset", fgRed.Sprint("git reset --mixed HEAD")}, Tooltip: "Reset HEAD to the chosen commit, and keep the changes between the current and chosen commit as unstaged changes.", OnPress: func() {
			g.logAction("Mixed reset")
			g.runGitLogged("reset", "--mixed", "HEAD")
			g.refreshAll()
		}},
		{Key: "h", Columns: []string{"Hard reset", fgRed.Sprint("git reset --hard HEAD")}, Tooltip: "Reset HEAD to the chosen commit, and discard all changes between the current and chosen commit, as well as all current modifications in the working tree.", OnPress: func() {
			g.logAction("Hard reset")
			g.runGitLogged("reset", "--hard", "HEAD")
			g.refreshAll()
		}},
		{Label: "Cancel", Columns: []string{"Cancel", ""}},
	}
	g.showMenu("", items)
}

func (g *Gui) handleStashAll() {
	if len(g.files) == 0 {
