func (g *Gui) newBranchPrompt(base string, display string) {
	title := "New branch name (branch is off of '" + display + "')"
	g.showPrompt(title, g.cfg.BranchPrefix, func(name string) {
		name = strings.ReplaceAll(strings.TrimSpace(name), " ", "-")
		if name == "" {
			g.showError("Branch name cannot be blank")
			return
		}
		g.logAction("Create branch")
		out, err := g.runGitLogged("checkout", "-b", name, base)
		if err != nil {
			g.showError(strings.TrimSpace(out))
		}
		g.refreshAll()
		g.ctx["localBranches"].sel = 0
		g.ctx["commits"].sel = 0
		g.pushContext(g.ctx["localBranches"])
	})
}

func (g *Gui) checkoutByName() {
	g.showPrompt("Branch name:", "", func(name string) {
		if strings.TrimSpace(name) == "" {
			return
		}
		g.doCheckout(strings.TrimSpace(name))
	})
}

func (g *Gui) renameSelectedBranch() {
	b := g.selectedBranch()
	if b == nil {
		return
	}
	g.showPrompt("Enter new branch name for branch '"+b.Name+"'", b.Name, func(name string) {
		name = strings.TrimSpace(name)
		if name == "" {
			return
		}
		g.logAction("Rename branch")
		out, err := g.runGitLogged("branch", "--move", b.Name, name)
		if err != nil {
			g.showError(strings.TrimSpace(out))
		}
		g.refreshAll()
	})
