		return
	}
	g.showError(strings.TrimSpace(out))
}

func (g *Gui) openMergeMenu() {
	b := g.selectedBranch()
	if b == nil || g.headBranch == nil {
		return
	}
	if b.Head {
		g.showError("You cannot merge a branch into itself")
		return
	}
	cur := g.headBranch.Name
	doMerge := func(extra ...string) {
		g.logAction("Merge")
		args := append([]string{"merge", "--no-edit"}, extra...)
		if g.cfg.MergingArgs != "" {
			args = append(args, splitArgs(g.cfg.MergingArgs)...)
		}
