func (g *Gui) doCheckout(ref string) {
	g.logAction("Checkout branch")
	out, err := g.runGitLogged("checkout", ref)
	if err != nil {
		msg := strings.TrimSpace(out)
		if strings.Contains(msg, "would be overwritten") || strings.Contains(msg, "Please commit your changes") {
			g.showConfirm("Auto-stash changes", "You are about to checkout "+ref+" but you have uncommitted changes. Do you want to stash them and re-apply them after checking out?", func() {
				g.logAction("Checkout branch")
				g.runGitLogged("stash", "push", "-m", "Auto-stashing changes for "+ref)
				g.runGitLogged("checkout", ref)
				g.runGitLogged("stash", "pop")
				g.refreshAll()
			})
			return
		}
		g.showError(msg)
	}
	g.refreshAll()
	g.ctx["localBranches"].sel = 0
	g.ctx["commits"].sel = 0
}

