	title := "New branch name (branch is off of '" + display + "')"
	g.showPrompt(title, g.cfg.BranchPrefix, func(name string) {
		name = strings.ReplaceAll(strings.TrimSpace(name), " ", "-")
		if name == "" {
			g.showError("Branch name cannot be blank")
			return
		}
		g.logAction("Create branch")
