func (g *Gui) toggleCherryPick(c *Commit) {
	if g.cherryPicked[c.Hash] {
		delete(g.cherryPicked, c.Hash)
	} else {
		g.cherryPicked[c.Hash] = true
	}
}

func (g *Gui) pasteCommits() {
	if len(g.cherryPicked) == 0 {
		return
	}
	g.showConfirm("Cherry-pick", "Are you sure you want to cherry-pick the copied commits onto this branch?", func() {
		g.logAction("Cherry-pick")
		var hashes []string
		// preserve order oldest first
		for i := len(g.commits) - 1; i >= 0; i-- {
			if g.cherryPicked[g.commits[i].Hash] {
				hashes = append(hashes, g.commits[i].Hash)
			}
		}
		for h := range g.cherryPicked {
			found := false
			for _, x := range hashes {
				if x == h {
					found = true
				}
			}
			if !found {
				hashes = append(hashes, h)
			}
		}
		args := append([]string{"cherry-pick", "--allow-empty"}, hashes...)
		out, err := g.runGitLogged(args...)
		if err != nil {
			g.showError(strings.TrimSpace(out))
		}
		g.cherryPicked = map[string]bool{}
		g.refreshAll()
	})
