		return
	}
	msg := trimNL(gitOut("log", "-1", "--format=%B", c.Hash))
	parts := strings.SplitN(msg, "\n", 2)
	summary := parts[0]
	desc := ""
	if len(parts) > 1 {
		desc = strings.TrimLeft(parts[1], "\n")
	}
	cm := &commitMsgState{summary: NewEditor(summary), description: NewEditor(desc), title: "Reword commit"}
	cm.description.multiline = true
	sel := g.ctx["commits"].sel
	cm.onConfirm = func(s, d string) {
		g.logAction("Reword commit")
		full := s
		if strings.TrimSpace(d) != "" {
			full += "\n\n" + d
		}
		if sel == 0 {
			out, err := g.runGitLogged("commit", "--allow-empty", "--amend", "--only", "-m", s, "-m", d)
			if strings.TrimSpace(d) == "" {
				_ = out
			}
			if err != nil {
				g.showError(strings.TrimSpace(out))
			}
		} else {
