func (g *Gui) rebaseTodo(hash, action string) error {
	// run an interactive rebase with a sequence editor that changes the action
	script := "sed -i -e 's/^pick " + hash[:7] + "/" + action + " " + hash[:7] + "/' \"$1\""
	_ = script
	cmd := gitCmd("-c", "rebase.autoSquash=false", "rebase", "--interactive", "--autostash", "--keep-empty", "--no-autosquash", "--rebase-merges", hash+"^")
	cmd.Env = append(cmd.Env, "GIT_SEQUENCE_EDITOR=sed -i -e 's/^pick "+hash[:7]+"\\([0-9a-f]*\\)/"+action+" "+hash[:7]+"\\1/'", "GIT_EDITOR=true")
	out, err := cmd.CombinedOutput()
	if err != nil {
		return &gitError{msg: strings.TrimSpace(string(out))}
	}
	return nil
}

func (g *Gui) rebaseReword(hash, msg string) {
	cmd := gitCmd("-c", "rebase.autoSquash=false", "rebase", "--interactive", "--autostash", "--keep-empty", "--no-autosquash", hash+"^")
	cmd.Env = append(cmd.Env, "GIT_SEQUENCE_EDITOR=sed -i -e 's/^pick "+hash[:7]+"\\([0-9a-f]*\\)/edit "+hash[:7]+"\\1/'", "GIT_EDITOR=true")
	cmd.CombinedOutput()
	runGit("commit", "--amend", "--allow-empty", "-m", msg)
	c2 := gitCmd("rebase", "--continue")
	c2.Env = append(c2.Env, "GIT_EDITOR=true")
	c2.CombinedOutput()
