func (g *Gui) openCommitFiles(ref, parentRef, parent string) {
	g.commitFilesRef = ref
	g.commitFilesParentRef = parentRef
	var out string
	if parentRef != "" {
		out, _ = runGit("diff", "--submodule", "--no-ext-diff", "--name-status", "-z", "--no-renames", parentRef, ref)
	} else {
		out, _ = runGit("diff-tree", "--root", "--no-commit-id", "-r", "--name-status", "-z", "--no-renames", ref)
	}
	parts := strings.Split(out, "\x00")
	var files []*File
	for i := 0; i+1 < len(parts); i += 2 {
		st := parts[i]
		if st == "" {
			break
		}
		files = append(files, &File{Name: parts[i+1], ShortStatus: st[:1]})
	}
	g.commitFiles = files
	if g.showTree {
		root := buildFileTree(files)
		g.commitFileNodes = flattenTreeKeyed(root, g.collapsedDirs, "cf:", true)
	} else {
		root := buildFlatListSorted(files)
		g.commitFileNodes = flattenTreeKeyed(root, g.collapsedDirs, "cf:", false)
	}
	c := g.ctx["commitFiles"]
	c.Window = g.ctx[parent].Window
	c.parentKey = parent
	c.sel = 0
	c.View.OY = 0
	short := ref
	if len(short) > 7 {
		short = short[:7]
	}
	g.commitFilesTitle = short
	if parent == "stash" {
		for _, s := range g.stash {
			if s.Hash == ref {
				g.commitFilesTitle = s.RefName()
			}
		}
	}
	g.pushContext(c)
}

func flattenTreeKeyed(root *FileNode, collapsed map[string]bool, prefix string, showRoot bool) []*FileNode {
	m := map[string]bool{}
	for k, v := range collapsed {
		if strings.HasPrefix(k, prefix) {
			m[strings.TrimPrefix(k, prefix)] = v
		}
	}
	return flattenTree(root, m, showRoot)
}

func (g *Gui) commitFilesBindings() []*binding {
	return []*binding{
		{cfgKey: "universal.goInto", fn: func() {
			n := g.selectedCommitFileNode()
			if n == nil {
				return
			}
			if n.IsDir() {
				g.collapsedDirs["cf:"+n.Path] = !g.collapsedDirs["cf:"+n.Path]
				g.reflattenCommitFiles()
			}
		}},
		{cfgKey: "commitFiles.checkoutCommitFile", fn: func() {
			n := g.selectedCommitFileNode()
			if n == nil {
				return
			}
			g.logAction("Checkout file")
			g.runGitLogged("checkout", g.commitFilesRef, "--", n.Path)
			g.refreshFiles()
		}},
	}
}

func (g *Gui) reflattenCommitFiles() {
	files := g.commitFiles
	if g.showTree {
		g.commitFileNodes = flattenTreeKeyed(buildFileTree(files), g.collapsedDirs, "cf:", true)
	} else {
		g.commitFileNodes = flattenTreeKeyed(buildFlatListSorted(files), g.collapsedDirs, "cf:", false)
	}
	g.ctx["commitFiles"].clampSel()
	g.mainKey = ""
}

func (g *Gui) subCommitsBindings(c *Context) []*binding {
	sel := func() *Commit {
		if c.Key == "reflogCommits" {
			return g.selectedReflog()
		}
		return g.selectedSubCommit()
	}
	return []*binding{
		{cfgKey: "commits.checkoutCommit", fn: func() {
			if x := sel(); x != nil {
				g.checkoutCommit(x)
			}
		}, short: "Checkout", display: true},
		{cfgKey: "universal.new", fn: func() {
			if x := sel(); x != nil {
				g.newBranchPrompt(x.Hash, x.ShortHash())
			}
		}, short: "New branch", display: true},
		{cfgKey: "commits.viewResetOptions", fn: func() {
			if x := sel(); x != nil {
				g.openResetToRefMenu(x.Hash)
			}
		}, short: "Reset", display: true},
		{cfgKey: "commits.cherryPickCopy", fn: func() {
			if x := sel(); x != nil {
				g.toggleCherryPick(x)
			}
		}, short: "Copy (cherry-pick)", display: true},
		{cfgKey: "universal.goInto", fn: func() {
			if x := sel(); x != nil {
				if c.Key == "reflogCommits" {
					g.openSubCommits(x.Hash, x.ShortHash(), "reflogCommits")
				} else {
					g.openCommitFiles(x.Hash, "", "subCommits")
				}
			}
		}},
	}
}
