func (g *Gui) withStatus(msg string, fn func() (string, error), after func(string, error)) {
	g.appStatus = msg + " " + g.spinnerFrame()
	g.statusBase = msg
	go func() {
		out, err := fn()
		g.t.events <- Event{Type: EvFunc, Fn: func() {
			g.appStatus = ""
			g.statusBase = ""
			after(out, err)
		}}
	}()
	go func() {
		for {
			time.Sleep(time.Duration(maxInt(g.cfg.SpinnerRate, 20)) * time.Millisecond)
			done := false
			g.t.events <- Event{Type: EvFunc, Fn: func() {
				if g.statusBase == "" {
					done = true
					return
				}
				g.appStatus = g.statusBase + " " + g.spinnerFrame()
			}}
			time.Sleep(5 * time.Millisecond)
			if done || g.statusBase == "" {
				return
			}
		}
	}()
}

func (g *Gui) handlePush() {
	b := g.headBranch
	if b == nil || b.DetachedHead {
		g.showError("Cannot push from a detached head")
		return
	}
	if !b.IsTrackingRemote() {
		remote := "origin"
		if len(g.remotes) > 0 {
			remote = g.remotes[0].Name
		}
		if len(g.remotes) == 0 {
			g.showError("No remotes configured")
			return
		}
		g.showPrompt("Enter upstream as '<remote> <branchname>'", remote+" "+b.Name, func(s string) {
			parts := strings.Fields(s)
			if len(parts) < 2 {
				return
			}
			g.logAction("Push")
			g.logCommand("git push --set-upstream "+parts[0]+" "+b.Name+":"+parts[1], true)
			g.withStatus("Pushing", func() (string, error) {
				return runGitCombined("push", "--set-upstream", parts[0], b.Name+":"+parts[1])
			}, func(out string, err error) {
				if err != nil {
					g.showError(strings.TrimSpace(out))
				}
				g.refreshAll()
			})
		})
		return
	}
	g.logAction("Push")
	g.logCommand("git push", true)
	g.withStatus("Pushing", func() (string, error) {
		return runGitCombined("push")
	}, func(out string, err error) {
		if err != nil {
			if strings.Contains(out, "rejected") || strings.Contains(out, "non-fast-forward") {
				if g.cfg.DisableForcePushing {
					g.showError("Force push is disabled")
					return
				}
				g.showConfirm("Force push", "Your branch has diverged from the remote branch. Press <esc> to cancel, or <enter> to force push.", func() {
					g.logAction("Force push")
					g.logCommand("git push --force-with-lease", true)
					g.withStatus("Pushing", func() (string, error) { return runGitCombined("push", "--force-with-lease") }, func(out string, err error) {
						if err != nil {
							g.showError(strings.TrimSpace(out))
						}
						g.refreshAll()
					})
				})
				return
			}
			g.showError(strings.TrimSpace(out))
		}
		g.refreshAll()
	})
}

func (g *Gui) handlePull() {
	b := g.headBranch
	if b == nil || b.DetachedHead {
		g.showError("Cannot pull on a detached head")
		return
	}
	if !b.IsTrackingRemote() {
		if len(g.remotes) == 0 {
			g.showError("No remotes configured")
			return
		}
		g.showPrompt("Enter upstream as '<remote> <branchname>'", g.remotes[0].Name+" "+b.Name, func(s string) {
			parts := strings.Fields(s)
			if len(parts) < 2 {
				return
			}
			g.logAction("Pull")
			runGit("branch", "--set-upstream-to="+parts[0]+"/"+parts[1], b.Name)
			g.doPull()
		})
		return
	}
	g.logAction("Pull")
	g.doPull()
}

func (g *Gui) doPull() {
	g.logCommand("git pull --no-edit", true)
	g.withStatus("Pulling", func() (string, error) {
		return runGitCombined("pull", "--no-edit")
	}, func(out string, err error) {
		if err != nil {
			g.showError(strings.TrimSpace(out))
		}
		g.refreshAll()
	})
}

func (g *Gui) handleFetch() {
	g.logAction("Fetch")
	args := []string{"fetch"}
	if g.cfg.FetchAll {
		args = append(args, "--all")
	}
	g.logCommand("git "+strings.Join(args, " "), true)
	g.withStatus("Fetching", func() (string, error) {
		return runGitCombined(args...)
	}, func(out string, err error) {
		if err != nil {
			g.showError(strings.TrimSpace(out))
		}
		g.refreshAll()
	})
}

func (g *Gui) openMergeRebaseMenu() {
	state := g.workingTreeState()
	if state == "" {
		g.showError("Not merging or rebasing")
		return
	}
	cmd := "rebase"
	if state == "merging" {
		cmd = "merge"
	} else if state == "cherry-picking" {
		cmd = "cherry-pick"
	} else if state == "reverting" {
		cmd = "revert"
	}
	run := func(sub string) func() {
		return func() {
			g.logAction(strings.Title(sub) + " " + cmd)
			c := gitCmd(cmd, "--"+sub)
			c.Env = append(c.Env, "GIT_EDITOR=true")
			out, err := c.CombinedOutput()
			g.logCommand("git "+cmd+" --"+sub, true)
			if err != nil {
				g.showError(strings.TrimSpace(string(out)))
			}
			g.refreshAll()
		}
	}
	items := []*menuItem{
		{Key: "c", Label: "continue", OnPress: run("continue")},
		{Key: "a", Label: "abort", OnPress: run("abort")},
	}
	if cmd != "merge" {
		items = append(items, &menuItem{Key: "s", Label: "skip", OnPress: run("skip")})
	}
	items = append(items, &menuItem{Label: "Cancel"})
	title := strings.Title(cmd) + " options"
	g.showMenu(title, items)
}

func execSelfIn(path string) {
	os.Chdir(path)
	exe, err := os.Executable()
	if err != nil {
		os.Exit(0)
	}
	syscall.Exec(exe, os.Args, os.Environ())
	cmd := exec.Command(exe)
	cmd.Run()
	os.Exit(0)
}

