package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

type patchLineKind int

const (
	plHeader patchLineKind = iota
	plHunkHeader
	plContext
	plAdd
	plDel
	plNewline
)

type patchLine struct {
	kind patchLineKind
	text string
}

type patchHunk struct {
	headerIdx          int // index in lines
	oldStart, oldLen   int
	newStart, newLen   int
	headerContext      string
	firstIdx, lastIdx  int // body line indexes (inclusive)
}

type Patch struct {
	lines []patchLine
	hunks []*patchHunk
	header []string
}

var hunkHeaderRe = regexp.MustCompile(`^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@(.*)$`)

func parsePatch(diff string) *Patch {
	p := &Patch{}
	diff = strings.TrimSuffix(diff, "\n")
	if diff == "" {
		return p
	}
	var cur *patchHunk
	for _, l := range strings.Split(diff, "\n") {
		if m := hunkHeaderRe.FindStringSubmatch(l); m != nil {
			h := &patchHunk{headerIdx: len(p.lines)}
			h.oldStart, _ = strconv.Atoi(m[1])
			h.oldLen = 1
			if m[2] != "" {
				h.oldLen, _ = strconv.Atoi(m[2])
			}
			h.newStart, _ = strconv.Atoi(m[3])
			h.newLen = 1
			if m[4] != "" {
				h.newLen, _ = strconv.Atoi(m[4])
			}
			h.headerContext = m[5]
			h.firstIdx = len(p.lines) + 1
			h.lastIdx = len(p.lines)
			p.hunks = append(p.hunks, h)
			p.lines = append(p.lines, patchLine{kind: plHunkHeader, text: l})
			cur = h
			continue
		}
		if cur == nil {
			p.lines = append(p.lines, patchLine{kind: plHeader, text: l})
			p.header = append(p.header, l)
			continue
		}
		k := plContext
		switch {
		case strings.HasPrefix(l, "+"):
			k = plAdd
		case strings.HasPrefix(l, "-"):
			k = plDel
		case strings.HasPrefix(l, "\\"):
			k = plNewline
		}
		p.lines = append(p.lines, patchLine{kind: k, text: l})
		cur.lastIdx = len(p.lines) - 1
	}
	return p
}

func (p *Patch) containsChanges() bool {
	for _, l := range p.lines {
		if l.kind == plAdd || l.kind == plDel {
			return true
		}
	}
	return false
}

func (p *Patch) isChange(i int) bool {
	return i >= 0 && i < len(p.lines) && (p.lines[i].kind == plAdd || p.lines[i].kind == plDel)
}

func (p *Patch) nextChangeIdx(from int) int {
	if from < 0 {
		from = 0
	}
	for i := from; i < len(p.lines); i++ {
		if p.isChange(i) {
			return i
		}
	}
	for i := len(p.lines) - 1; i >= 0; i-- {
		if p.isChange(i) {
			return i
		}
	}
	return 0
}

func (p *Patch) hunkIdxContaining(line int) int {
	for i := len(p.hunks) - 1; i >= 0; i-- {
		if line >= p.hunks[i].headerIdx {
			return i
		}
	}
	return 0
}

func (p *Patch) hunkChangeRange(hi int) (int, int) {
	h := p.hunks[hi]
	first, last := -1, -1
	for i := h.firstIdx; i <= h.lastIdx; i++ {
		if p.isChange(i) {
			if first < 0 {
				first = i
			}
			last = i
		}
	}
	if first < 0 {
		return h.headerIdx, h.headerIdx
	}
	return first, last
}

func (p *Patch) render() []string {
	if !p.containsChanges() {
		return nil
	}
	var res []string
	for _, l := range p.lines {
		switch l.kind {
		case plHeader:
			res = append(res, styleDefault.Bold().Sprint(l.text))
		case plHunkHeader:
			m := hunkHeaderRe.FindStringSubmatch(l.text)
			start := strings.TrimSuffix(l.text, m[5])
			res = append(res, fgCyan.Sprint(start)+m[5])
		case plAdd:
			res = append(res, fgGreen.Sprint(l.text))
		case plDel:
			res = append(res, fgRed.Sprint(l.text))
		default:
			res = append(res, l.text)
		}
	}
	return res
}

// transform builds a patch including only selected changes.
// reverse=false: for applying forward (staging): unselected '-' -> context, unselected '+' dropped.
// reverse=true: for applying in reverse (unstaging/discarding): unselected '+' -> context, unselected '-' dropped.
func (p *Patch) transform(selStart, selEnd int, reverse bool) string {
	var b strings.Builder
	for _, h := range p.header {
		b.WriteString(h + "\n")
	}
	offset := 0
	any := false
	for _, h := range p.hunks {
		var body []string
		oldLen, newLen := 0, 0
		hasChange := false
		for i := h.firstIdx; i <= h.lastIdx; i++ {
			l := p.lines[i]
			sel := i >= selStart && i <= selEnd
			switch l.kind {
			case plContext:
				body = append(body, l.text)
				oldLen++
				newLen++
			case plAdd:
				if sel {
					body = append(body, l.text)
					newLen++
					hasChange = true
				} else if reverse {
					body = append(body, " "+l.text[1:])
					oldLen++
					newLen++
				} else {
					// dropped; also drop a following "\ No newline" marker
					if i+1 <= h.lastIdx && p.lines[i+1].kind == plNewline {
						i++
					}
				}
			case plDel:
				if sel {
					body = append(body, l.text)
					oldLen++
					hasChange = true
				} else if !reverse {
					body = append(body, " "+l.text[1:])
					oldLen++
					newLen++
				} else {
					if i+1 <= h.lastIdx && p.lines[i+1].kind == plNewline {
						i++
					}
				}
			case plNewline:
				body = append(body, l.text)
			}
		}
		if !hasChange {
			continue
		}
		any = true
		oldStart := h.oldStart
		if reverse {
			oldStart = h.newStart
		}
		newStart := oldStart + offset
		if oldLen == 0 && oldStart > 0 {
			// insertion at start uses the line before
		}
		if oldStart == 0 && oldLen > 0 {
			oldStart = 1
		}
		if newLen == 0 {
			newStart = newStart - 1
			if newStart < 0 {
				newStart = 0
			}
		}
		b.WriteString(fmt.Sprintf("@@ -%d,%d +%d,%d @@%s\n", oldStart, oldLen, newStart, newLen, h.headerContext))
		for _, l := range body {
			b.WriteString(l + "\n")
		}
		offset += newLen - oldLen
	}
	if !any {
		return ""
	}
	return b.String()
}
EOF
