	if !p.containsChanges() {
		return nil
	}
	var res []string
	for _, l := range p.lines {
		switch l.kind {
		case plHeader:
			res = append(res, styleDefault.Bold().Sprint(l.text))
		case plHunkHeader:
			m := hunkHeaderRe.FindStringSubmatch(l.text)
			start := strings.TrimSuffix(l.text, m[5])
			res = append(res, fgCyan.Sprint(start)+m[5])
		case plAdd:
			res = append(res, fgGreen.Sprint(l.text))
		case plDel:
			res = append(res, fgRed.Sprint(l.text))
		default:
			res = append(res, l.text)
		}
	}
	return res
}

// transform builds a patch including only selected changes.
// reverse=false: for applying forward (staging): unselected '-' -> context, unselected '+' dropped.
// reverse=true: for applying in reverse (unstaging/discarding): unselected '+' -> context, unselected '-' dropped.
func (p *Patch) transform(selStart, selEnd int, reverse bool) string {
	var b strings.Builder
	for _, h := range p.header {
		b.WriteString(h + "\n")
	}
	offset := 0
	any := false
	for _, h := range p.hunks {
		var body []string
		oldLen, newLen := 0, 0
		hasChange := false
		for i := h.firstIdx; i <= h.lastIdx; i++ {
			l := p.lines[i]
			sel := i >= selStart && i <= selEnd
			switch l.kind {
			case plContext:
				body = append(body, l.text)
				oldLen++
				newLen++
			case plAdd:
				if sel {
					body = append(body, l.text)
					newLen++
					hasChange = true
				} else if reverse {
					body = append(body, " "+l.text[1:])
					oldLen++
					newLen++
				} else {
					// dropped; also drop a following "\ No newline" marker
					if i+1 <= h.lastIdx && p.lines[i+1].kind == plNewline {
						i++
					}
				}
			case plDel:
				if sel {
					body = append(body, l.text)
					oldLen++
					hasChange = true
				} else if !reverse {
					body = append(body, " "+l.text[1:])
					oldLen++
					newLen++
				} else {
					if i+1 <= h.lastIdx && p.lines[i+1].kind == plNewline {
						i++
					}
				}
			case plNewline:
				body = append(body, l.text)
			}
		}
		if !hasChange {
			continue
		}
		any = true
		oldStart := h.oldStart
		if reverse {
			oldStart = h.newStart
		}
		newStart := oldStart + offset
		if oldLen == 0 && oldStart > 0 {
			// insertion at start uses the line before
		}
		if oldStart == 0 && oldLen > 0 {
			oldStart = 1
		}
		if newLen == 0 {
			newStart = newStart - 1
			if newStart < 0 {
				newStart = 0
			}
		}
		b.WriteString(fmt.Sprintf("@@ -%d,%d +%d,%d @@%s\n", oldStart, oldLen, newStart, newLen, h.headerContext))
		for _, l := range body {
			b.WriteString(l + "\n")
		}
		offset += newLen - oldLen
	}
	if !any {
		return ""
	}
	return b.String()
}
