	selHunk
)

type patchState struct {
	diff        string
	patch       *Patch
	sel         int
	rangeStart  int
	mode        int
	rangeSticky bool
	userHunk    bool
	origin      int
}

type stagingState struct {
	path     string
	file     *File
	unstaged *patchState
	staged   *patchState
	hintShown bool
}

func (g *Gui) newPatchState(diff string, old *patchState) *patchState {
	p := parsePatch(diff)
	if !p.containsChanges() {
		return nil
	}
	if old != nil && old.diff == diff {
		return old
	}
	s := &patchState{diff: diff, patch: p}
	if g.cfg.raw == nil {
	}
	s.mode = selHunk
	if !g.useHunkMode() {
		s.mode = selLine
	}
	if old != nil {
		if old.mode == selLine || old.mode == selRange {
			if old.userHunk || old.mode == selLine {
				s.mode = old.mode
				if s.mode == selRange {
					s.mode = selLine
				}
			}
		}
		s.userHunk = old.userHunk
		s.sel = p.nextChangeIdx(old.sel)
		s.origin = old.origin
	} else {
		s.sel = p.nextChangeIdx(0)
	}
	s.rangeStart = s.sel
	return s
}

func (g *Gui) useHunkMode() bool { return true }

func (s *patchState) selectedRange() (int, int) {
	switch s.mode {
	case selHunk:
		hi := s.patch.hunkIdxContaining(s.sel)
		return s.patch.hunkChangeRange(hi)
	case selRange:
		a, b := s.rangeStart, s.sel
		if a > b {
			a, b = b, a
		}
		return a, b
	}
	return s.sel, s.sel
}

func (s *patchState) needWant() (int, int) {
	a, b := s.selectedRange()
	switch s.mode {
	case selLine:
		return s.sel, s.sel
	case selRange:
		if s.sel == a {
			return a, b
		}
		return b, a
	}
	return a, b
}

func (s *patchState) focusSelection(height int) {
	need, want := s.needWant()
	numLines := len(s.patch.lines)
	origin := s.origin
	if need < origin || need >= origin+height {
		origin = maxInt(minInt(need-height/2, numLines-height), 0)
	}
	bottom := origin + height
	if want < origin {
		required := origin - want
		allowed := bottom - need
		origin -= minInt(required, allowed)
	} else if want >= bottom {
		required := want + 1 - bottom
		allowed := need - origin
		origin += minInt(required, allowed)
	}
	s.origin = origin
}

func (s *patchState) cycle(forward bool) {
	if s.mode == selHunk {
		hi := s.patch.hunkIdxContaining(s.sel)
		if forward {
			hi++
		} else {
			hi--
		}
		if hi < 0 || hi >= len(s.patch.hunks) {
			return
		}
		a, _ := s.patch.hunkChangeRange(hi)
		s.sel = a
		return
	}
	if s.mode == selRange && !s.rangeSticky {
		s.mode = selLine
	}
	d := 1
	if !forward {
		d = -1
	}
	s.selectLine(s.sel + d)
}

func (s *patchState) selectLine(i int) {
	if i < 0 {
		i = 0
	}
	if i > len(s.patch.lines)-1 {
		i = len(s.patch.lines) - 1
	}
	s.sel = i
}

func (g *Gui) loadStagingDiffs() (string, string) {
	st := g.staging
	var f *File
	for _, x := range g.files {
		if x.Name == st.path {
			f = x
		}
	}
	st.file = f
	unstaged := ""
	staged := ""
	if f != nil {
		if f.HasUnstagedChanges || !f.Tracked {
			unstaged = g.plainDiff(f, false)
		}
		if f.HasStagedChanges {
			staged = g.plainDiff(f, true)
		}
	}
	return unstaged, staged
}

func (g *Gui) plainDiff(f *File, cached bool) string {
	args := []string{"-c", "diff.noprefix=false", "diff", "--submodule", "--no-ext-diff", "--unified=" + itoaInt(g.diffContext), "--color=never"}
	if g.ignoreWhitespace {
		args = append(args, "--ignore-all-space")
	}
	if cached {
		args = append(args, "--cached")
	}
	if !f.Tracked && !f.HasStagedChanges && !cached {
		args = append(args, "--no-index", "--", "/dev/null", f.Name)
	} else {
		args = append(args, "--find-renames="+itoaInt(g.renameThreshold)+"%", "--", f.Name)
	}
	out, _ := runGit(args...)
	return out
}

func itoaInt(i int) string { return fmt.Sprint(i) }

func (g *Gui) enterStaging(f *File, secondary bool) {
	if f.HasInlineConflicts {
		g.showError("Merge conflicts are not supported yet")
		return
	}
	g.staging = &stagingState{path: f.Name, file: f}
	u, s := g.loadStagingDiffs()
	g.staging.unstaged = g.newPatchState(u, nil)
	g.staging.staged = g.newPatchState(s, nil)
	if g.staging.unstaged == nil && g.staging.staged == nil {
		g.staging = nil
		return
	}
	if secondary || g.staging.unstaged == nil {
		g.pushContext(g.ctx["stagingSecondary"])
	} else {
		g.pushContext(g.ctx["staging"])
	}
	g.layoutForStaging()
	if !g.state.DidShowHunkStagingHint {
		g.state.DidShowHunkStagingHint = true
		g.state.Save()
		g.showConfirm("", hunkHintMessage, nil)
	}
}

const hunkHintMessage = "Hunk selection mode is now the default for staging. If you want to stage individual lines, press 'a' to switch to line-by-line mode.\n\nIf you prefer to use line-by-line mode by default (as in earlier lazygit versions), add\n\ngui:\n  useHunkModeInStagingView: false\n\nto your lazygit config."

func (g *Gui) layoutForStaging() {
	g.layout()
	st := g.staging
	if st == nil {
		return
	}
	if st.unstaged != nil {
		st.unstaged.focusSelection(g.views["staging"].InnerHeight())
	}
	if st.staged != nil {
		st.staged.focusSelection(g.views["stagingSecondary"].InnerHeight())
	}
}

func (g *Gui) refreshStaging() {
	st := g.staging
	if st == nil {
		return
	}
	g.refreshFiles()
	u, s := g.loadStagingDiffs()
	st.unstaged = g.newPatchState(u, st.unstaged)
	st.staged = g.newPatchState(s, st.staged)
	cur := g.currentStaticContext()
	if st.unstaged == nil && st.staged == nil {
		g.exitStaging()
		return
	}
	if cur.Key == "staging" && st.unstaged == nil {
		g.pushContext(g.ctx["stagingSecondary"])
	} else if cur.Key == "stagingSecondary" && st.staged == nil {
		g.pushContext(g.ctx["staging"])
	}
	g.layoutForStaging()
}

func (g *Gui) exitStaging() {
	g.staging = nil
	g.pushContext(g.ctx["files"])
	g.mainKey = ""
}

func (g *Gui) updateStagingContent() {
	st := g.staging
	if st == nil {
		return
	}
	cur := g.currentStaticContext()
	v := g.views["staging"]
	v.Title = "Unstaged changes"
	v.Wrap = true
	v2 := g.views["stagingSecondary"]
	v2.Title = "Staged changes"
	v2.Wrap = true
	apply := func(view *View, ps *patchState, focused bool) {
		if ps == nil {
			view.SetLines(nil)
			view.Highlight = false
			view.OY = 0
			return
		}
		view.SetLines(ps.patch.render())
		a, b := ps.selectedRange()
		view.RangeStart, view.RangeEnd = a, b
		view.SelLine = ps.sel
		view.Highlight = focused
		sb := themeBgStyle(g.cfg.SelectedLineBgColor)
		view.SelBg = sb.Bg
		view.SelAttr = sb.Attr | AttrBold
		view.OY = ps.origin
	}
	apply(v, st.unstaged, cur.Key == "staging")
	apply(v2, st.staged, cur.Key == "stagingSecondary")
	g.splitMain = true
}

func (g *Gui) currentPatchState(c *Context) *patchState {
	if g.staging == nil {
		return nil
	}
	if c.Key == "staging" {
		return g.staging.unstaged
	}
	return g.staging.staged
}

func (g *Gui) stagingBindings(c *Context) []*binding {
	ps := func() *patchState { return g.currentPatchState(c) }
	height := func() int { return g.views[c.Key].InnerHeight() }
	after := func() {
		if p := ps(); p != nil {
			p.focusSelection(height())
		}
	}
	modeLabel := func() string {
		if p := ps(); p != nil && p.mode == selHunk {
			return "Select line-by-line"
		}
		return "Select hunks"
	}
	escLabel := "Return to files panel"
	if p := ps(); p != nil && p.mode == selRange {
		escLabel = "Dismiss range select"
	}
	return []*binding{
		{cfgKey: "main.toggleSelectHunk", fn: func() {
			p := ps()
			if p == nil {
				return
			}
			if p.mode == selHunk {
				p.mode = selLine
			} else {
				p.mode = selHunk
				p.userHunk = true
			}
			after()
		}, short: modeLabel(), display: true},
		{cfgKey: "universal.select", fn: func() { g.stagingToggleSelection(c) }, short: "Stage", display: true},
		{cfgKey: "universal.remove", fn: func() { g.stagingDiscard(c) }, short: "Discard", display: true},
		{cfgKey: "universal.return", fn: func() {
			p := ps()
			if p != nil && p.mode == selRange {
				p.mode = selLine
				return
			}
			g.exitStaging()
		}, short: escLabel, display: true},
		{cfgKey: "universal.togglePanel", fn: func() {
			if c.Key == "staging" && g.staging.staged != nil {
				g.pushContext(g.ctx["stagingSecondary"])
			} else if c.Key == "stagingSecondary" && g.staging.unstaged != nil {
				g.pushContext(g.ctx["staging"])
			}
		}, short: "Switch view", display: true},
		{cfgKey: "universal.prevItem", fn: func() {
			if p := ps(); p != nil {
				p.cycle(false)
				after()
			}
		}},
		{cfgKey: "universal.prevItem-alt", fn: func() {
			if p := ps(); p != nil {
				p.cycle(false)
				after()
			}
		}},
		{cfgKey: "universal.nextItem", fn: func() {
			if p := ps(); p != nil {
				p.cycle(true)
				after()
			}
		}},
		{cfgKey: "universal.nextItem-alt", fn: func() {
			if p := ps(); p != nil {
				p.cycle(true)
				after()
			}
		}},
		{cfgKey: "universal.prevBlock", fn: func() {
			if p := ps(); p != nil {
				m := p.mode
				p.mode = selHunk
				p.cycle(false)
				p.mode = m
				if m == selRange {
					p.mode = selLine
				}
				after()
			}
		}},
		{cfgKey: "universal.nextBlock", fn: func() {
			if p := ps(); p != nil {
				m := p.mode
				p.mode = selHunk
				p.cycle(true)
				p.mode = m
				if m == selRange {
					p.mode = selLine
				}
				after()
			}
		}},
		{cfgKey: "universal.toggleRangeSelect", fn: func() {
			p := ps()
			if p == nil {
				return
			}
			if p.mode == selRange {
				p.mode = selLine
			} else {
				if p.mode == selHunk {
					a, _ := p.selectedRange()
					p.sel = a
				}
				p.mode = selRange
				p.rangeSticky = true
				p.rangeStart = p.sel
			}
			after()
		}},
		{cfgKey: "universal.rangeSelectDown", fn: func() { g.stagingRangeMove(ps(), true); after() }},
		{cfgKey: "universal.rangeSelectUp", fn: func() { g.stagingRangeMove(ps(), false); after() }},
		{cfgKey: "universal.gotoTop", fn: func() {
			if p := ps(); p != nil {
				p.sel = p.patch.nextChangeIdx(0)
				after()
			}
		}},
		{cfgKey: "universal.gotoBottom", fn: func() {
			if p := ps(); p != nil {
				p.sel = len(p.patch.lines) - 1
				after()
			}
		}},
		{cfgKey: "universal.edit", fn: func() {
			if g.staging != nil {
				g.editFile(g.staging.path)
			}
		}},
		{cfgKey: "files.commitChanges", fn: g.handleCommitPress},
	}
}

func (g *Gui) stagingRangeMove(p *patchState, down bool) {
	if p == nil {
		return
	}
	if p.mode != selRange {
		if p.mode == selHunk {
			a, _ := p.selectedRange()
			p.sel = a
		}
		p.mode = selRange
		p.rangeSticky = false
		p.rangeStart = p.sel
	}
	if down {
		p.selectLine(p.sel + 1)
	} else {
		p.selectLine(p.sel - 1)
	}
}

var patchTmpDir string

func (g *Gui) writePatchFile(content string) string {
	if patchTmpDir == "" {
		base := filepath.Join(os.TempDir(), fmt.Sprintf("lazygit-%d", os.Getuid()))
		os.MkdirAll(base, 0o700)
		patchTmpDir = filepath.Join(base, fmt.Sprintf("lazygit-%d", rand.New(rand.NewSource(time.Now().UnixNano())).Int31()))
		os.MkdirAll(patchTmpDir, 0o700)
	}
	dir := filepath.Join(patchTmpDir, g.repoName)
	os.MkdirAll(dir, 0o700)
	name := time.Now().Format("Jan _2 15.04.05.000000000") + ".patch"
	p := filepath.Join(dir, name)
	os.WriteFile(p, []byte(content), 0o644)
	return p
}

func (g *Gui) applyPatch(content string, args ...string) error {
	path := g.writePatchFile(content)
	g.logCommand("Creating file '"+path+"'", false)
	full := append([]string{"apply"}, args...)
	g.logCommand("git "+strings.Join(full, " ")+" \""+path+"\"", true)
	runArgs := append(append([]string{"apply"}, args...), "--recount", path)
	out, err := runGitCombined(runArgs...)
	if err != nil {
		return &gitError{msg: strings.TrimSpace(out)}
	}
	return nil
}

func (g *Gui) stagingToggleSelection(c *Context) {
	p := g.currentPatchState(c)
	if p == nil {
		return
	}
	a, b := p.selectedRange()
	reverse := c.Key == "stagingSecondary"
	patch := p.patch.transform(a, b, reverse)
	if patch == "" {
		return
	}
	g.logAction("Apply patch")
	var err error
	if reverse {
		err = g.applyPatch(patch, "--cached", "--reverse")
	} else {
		err = g.applyPatch(patch, "--cached")
	}
	if err != nil {
		g.showError(err.Error())
	}
	if p.mode == selRange {
		p.mode = selLine
	}
	g.refreshStaging()
}

func (g *Gui) stagingDiscard(c *Context) {
	p := g.currentPatchState(c)
	if p == nil {
		return
	}
	if c.Key == "stagingSecondary" {
		g.showError("You can only discard unstaged changes. Switch to the unstaged view to discard changes.")
		return
	}
	do := func() {
		a, b := p.selectedRange()
		patch := p.patch.transform(a, b, true)
		if patch == "" {
			return
		}
		g.logAction("Apply patch")
		if err := g.applyPatch(patch, "--reverse"); err != nil {
			g.showError(err.Error())
		}
		if p.mode == selRange {
			p.mode = selLine
		}
		g.refreshStaging()
	}
	if g.cfg.SkipDiscardChangeWarning {
		do()
		return
	}
	g.showConfirm("Discard change", "Are you sure you want to discard this change (git reset)? It is irreversible.\nTo disable this dialogue set the config key of 'gui.skipDiscardChangeWarning' to true", do)
}
