import re
# add disabled: g.needItem(...) to bindings lacking disabled in various files
files={'commit_actions.go':None,'other_actions.go':None,'branch_actions.go':None}
def patch_bindings(path, funcname, ctxkey, exclude):
    s=open(path).read()
    i=s.index('func (g *Gui) '+funcname)
    j=s.index('\n}\n', i)
    body=s[i:j]
    lines=body.split('\n')
    out=[]
    for l in lines:
        m=re.match(r'^(\s*\{cfgKey: "([^"]+)".*?)(\},?)$', l)
        if m and 'disabled:' not in l and m.group(2) not in exclude:
            l=m.group(1)+', disabled: g.needItem("'+ctxkey+'")'+m.group(3)
        # multi-line binding endings "}, short: ..., display: true},"
        m2=re.match(r'^(\s*\}, short: .*?)(\},?)$', l)
        if m2 and 'disabled:' not in l:
            l=m2.group(1)+', disabled: g.needItem("'+ctxkey+'")'+m2.group(2)
        out.append(l)
    s=s[:i]+'\n'.join(out)+s[j:]
    open(path,'w').write(s)
