			return
		}
		var out string
		var err error
		if strings.TrimSpace(desc) != "" {
			g.logAction("Create annotated tag")
			out, err = g.runGitLogged("tag", name, ref, "-m", desc)
		} else {
			g.logAction("Create lightweight tag")
			out, err = g.runGitLogged("tag", "--", name, ref)
		}
		if err != nil {
			g.showError(strings.TrimSpace(out))
		}
		g.refreshAll()
	}
	g.commitMsg = cm
	g.pushContext(g.ctx["commitMessage"])
}

