sub('commit_actions.go','''func (g *Gui) rebaseTodo(hash, action string) error {''','''func (g *Gui) rebaseTodo(hash, action string) error {
	base := hash + "^"
	if action == "squash" || strings.HasPrefix(action, "fixup") {
		base = hash + "^^"
	}
	baseHash := trimNL(gitOut("rev-parse", base))
	g.logCommand("Changing TODO actions:", false)
	g.logCommand(hash+":"+strings.Fields(action)[0], false)
	g.logCommand("git rebase --interactive --autostash --keep-empty --no-autosquash --rebase-merges "+baseHash, true)
	return g.rebaseTodoRun(hash, action, baseHash)
}

func (g *Gui) rebaseTodoRun(hash, action, base string) error {
	cmd := gitCmd("-c", "rebase.autoSquash=false", "rebase", "--interactive", "--autostash", "--keep-empty", "--no-autosquash", "--rebase-merges", base)
	script := "sed -i -e 's/^pick " + hash[:7] + "[0-9a-f]*/" + action + " " + hash + "/' \\"$1\\""
	cmd.Env = append(cmd.Env, "GIT_SEQUENCE_EDITOR=sh -c '"+strings.ReplaceAll(script, "'", "'\\\\''")+"' --", "GIT_EDITOR=true")
	out, err := cmd.CombinedOutput()
	if err != nil {
		if strings.Contains(string(out), "CONFLICT") {
			return nil
		}
		if action == "edit" && strings.Contains(string(out), "Stopped at") {
			return nil
		}
		return &gitError{msg: strings.TrimSpace(string(out))}
	}
	return nil
}

