package main

import (
	"os"
	"path/filepath"
	"strings"
)

func (g *Gui) isRebasing() bool {
	return fileExists(filepath.Join(g.gitDir, "rebase-merge")) || fileExists(filepath.Join(g.gitDir, "rebase-apply"))
}

func (g *Gui) isInteractiveRebase() bool {
	return fileExists(filepath.Join(g.gitDir, "rebase-merge", "git-rebase-todo"))
}

func (g *Gui) loadRebaseTodos() []*Commit {
	data, err := os.ReadFile(filepath.Join(g.gitDir, "rebase-merge", "git-rebase-todo"))
	if err != nil {
		return nil
	}
	var todos []*Commit
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fields := strings.Fields(line)
		action := fields[0]
		switch action {
		case "p":
			action = "pick"
		case "r":
			action = "reword"
		case "e":
			action = "edit"
		case "s":
			action = "squash"
		case "f":
			action = "fixup"
		case "d":
			action = "drop"
		}
		switch action {
		case "pick", "reword", "edit", "squash", "fixup", "drop":
		default:
			continue
		}
		if len(fields) < 2 {
			continue
		}
		hashField := fields[1]
		if hashField == "-C" || hashField == "-c" {
			if len(fields) < 3 {
				continue
			}
			hashField = fields[2]
		}
		todos = append(todos, &Commit{Hash: hashField, Action: action, Status: "rebasing"})
	}
	// resolve full hashes & info
	for _, t := range todos {
		out, err := runGit("log", "--no-walk", "-1", "--format=%H%x00%aN%x00%ae%x00%s%x00%at%x00%P", t.Hash)
		if err == nil {
			p := strings.SplitN(trimNL(out), "\x00", 6)
			if len(p) == 6 {
				t.Hash, t.AuthorName, t.AuthorEmail, t.Name = p[0], p[1], p[2], p[3]
				if p[5] != "" {
					t.Parents = strings.Split(p[5], " ")
				}
			}
		}
	}
	// reverse
	for i, j := 0, len(todos)-1; i < j; i, j = i+1, j-1 {
		todos[i], todos[j] = todos[j], todos[i]
	}
	return todos
}

func (g *Gui) commitsNonModel() []nonModelItem {
	if g.todoCount == 0 {
		return nil
	}
	return []nonModelItem{{0, "--- Pending rebase todos ---"}, {g.todoCount, "--- Commits ---"}}
}
