	c := g.ctx["commits"]
	return c.sel >= 0 && c.sel < g.todoCount
}

func (g *Gui) rebaseCommitsBindings() []*binding {
	todoOnly := func() string {
		if !g.selectedIsTodo() {
			return "This action is only available on rebase todo items"
		}
		return ""
	}
	nonTodo := func() string {
		if len(g.commits) == 0 {
