		if g.selectedIsTodo() {
			return "This action is not available on rebase todo items"
		}
		return ""
	}
	setAction := func(action string) func() {
		return func() {
			c := g.selectedCommit()
			if c == nil {
				return
			}
			g.setTodoAction(c.Hash, action)
			g.refreshCommits()
		}
	}
	need := g.needItem("commits")
	return []*binding{
		{cfgKey: "commits.squashDown", fn: setAction("squash"), short: "Squash", display: true, disabled: todoOnly},
		{cfgKey: "commits.markCommitAsFixup", fn: setAction("fixup"), short: "Fixup", display: true, disabled: todoOnly},
		{cfgKey: "commits.renameCommit", fn: g.rewordCommit, short: "Reword", display: true, disabled: nonTodo},
		{cfgKey: "universal.remove", fn: setAction("drop"), short: "Drop", display: true, disabled: todoOnly},
		{cfgKey: "universal.edit", fn: setAction("edit"), short: "Edit", display: true, disabled: todoOnly},
		{cfgKey: "commits.pickCommit", fn: setAction("pick"), short: "Pick", disabled: todoOnly},
		{cfgKey: "commits.amendToCommit", fn: g.amendToCommit, short: "Amend", display: true, disabled: nonTodo},
		{cfgKey: "commits.checkoutCommit", fn: func() {
			if c := g.selectedCommit(); c != nil {
				g.checkoutCommitMenu(c)
			}
		}, short: "Checkout", display: true, disabled: need},
		{cfgKey: "commits.viewResetOptions", fn: func() {
			if c := g.selectedCommit(); c != nil {
				g.openResetToRefMenu(c.Hash)
			}
		}, short: "Reset", display: true, disabled: need},
		{cfgKey: "commits.cherryPickCopy", fn: func() {
			if c := g.selectedCommit(); c != nil {
				g.toggleCherryPick(c)
			}
		}, short: "Copy (cherry-pick)", display: true, disabled: need},
		{cfgKey: "universal.return", fn: g.confirmAbortRebase, short: "Abort rebase", display: true},
		{cfgKey: "universal.goInto", fn: func() {
			if c := g.selectedCommit(); c != nil {
				g.openCommitFiles(c.Hash, "", "commits")
			}
		}, disabled: need},
	}
}

func (g *Gui) confirmAbortRebase() {
	g.showConfirm("Abort rebase", "Are you sure you want to abort the current rebase?", func() {
		g.logAction("Abort rebase")
		g.logCommand("git rebase --abort", true)
		c := gitCmd("rebase", "--abort")
		out, err := c.CombinedOutput()
		if err != nil {
			g.showError(strings.TrimSpace(string(out)))
		}
		g.refreshAll()
	})
}

func (g *Gui) setTodoAction(hash, action string) {
	p := filepath.Join(g.gitDir, "rebase-merge", "git-rebase-todo")
	data, err := os.ReadFile(p)
	if err != nil {
		return
	}
	lines := strings.Split(string(data), "\n")
	for i, l := range lines {
		f := strings.Fields(l)
		if len(f) >= 2 && !strings.HasPrefix(l, "#") && (strings.HasPrefix(hash, f[1]) || strings.HasPrefix(f[1], hash)) {
			f[0] = action
			lines[i] = strings.Join(f, " ")
		}
	}
	os.WriteFile(p, []byte(strings.Join(lines, "\n")), 0o644)
}
