		case (strings.HasPrefix(l, ">>>>>>> ") || l == ">>>>>>>") && cur.start >= 0 && cur.middle >= 0:
			cur.end = i
			res = append(res, cur)
			cur = conflict{start: -1, ancestor: -1, middle: -1, end: -1}
		}
	}
	return res
}

func (g *Gui) loadMergeState(path string, old *mergeState) *mergeState {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	content := strings.TrimSuffix(string(data), "\n")
	lines := strings.Split(content, "\n")
	ms := &mergeState{path: path, lines: lines, conflicts: parseConflicts(lines)}
	if old != nil && old.path == path {
		ms.idx = old.idx
		ms.side = old.side
		ms.origin = old.origin
		ms.history = old.history
		if ms.idx >= len(ms.conflicts) {
			ms.idx = len(ms.conflicts) - 1
		}
		if ms.idx < 0 {
			ms.idx = 0
		}
	}
	return ms
}

func (ms *mergeState) selectedRange() (int, int) {
	if len(ms.conflicts) == 0 {
		return -1, -1
	}
	c := ms.conflicts[ms.idx]
	if ms.side == 0 {
		if c.ancestor >= 0 {
			return c.start, c.ancestor
		}
		return c.start, c.middle
	}
	return c.middle, c.end
}

func (ms *mergeState) render() []string {
	var res []string
	inConflict := map[int]bool{}
	for _, c := range ms.conflicts {
		inConflict[c.start] = true
		inConflict[c.middle] = true
		inConflict[c.end] = true
		if c.ancestor >= 0 {
			inConflict[c.ancestor] = true
		}
	}
	for i, l := range ms.lines {
		if inConflict[i] {
			res = append(res, fgRed.Sprint(l))
		} else {
			res = append(res, l)
		}
	}
	return res
}

func (g *Gui) selectedConflictFile() *File {
	n := g.selectedFileNode()
	if n == nil || n.IsDir() || n.File == nil {
		return nil
	}
	if n.File.HasInlineConflicts {
		return n.File
	}
	return nil
}

func (g *Gui) hasConflicts() bool {
	for _, f := range g.files {
		if f.HasMergeConflicts {
			return true
		}
	}
	return false
}

func (g *Gui) enterMergeConflicts(f *File) {
	g.merge = g.loadMergeState(f.Name, nil)
	if g.merge == nil {
		return
	}
	g.pushContext(g.ctx["mergeConflicts"])
}

func (g *Gui) updateMergeView(focused bool) {
	ms := g.merge
	v := g.views["mergeConflicts"]
	v.Title = "Diff"
	v.Wrap = false
	v.SetLines(ms.render())
	a, b := ms.selectedRange()
	v.RangeStart, v.RangeEnd = a, b
	v.Highlight = focused && a >= 0
	sb := themeBgStyle(g.cfg.SelectedLineBgColor)
	v.SelBg = sb.Bg
	v.SelAttr = sb.Attr | AttrBold
	v.OY = ms.origin
}

func (g *Gui) mergeFocusSelection() {
	ms := g.merge
	if ms == nil || len(ms.conflicts) == 0 {
		return
	}
	h := g.views["mergeConflicts"].InnerHeight()
	a, b := ms.selectedRange()
	need, want := a, b
	numLines := len(ms.lines)
	origin := ms.origin
	if need < origin || need >= origin+h {
		origin = maxInt(minInt(need-h/2, numLines-h), 0)
	}
	bottom := origin + h
	if want < origin {
		origin -= minInt(origin-want, bottom-need)
	} else if want >= bottom {
		origin += minInt(want+1-bottom, need-origin)
	}
	ms.origin = origin
}

func (g *Gui) resolveConflict(mode string) {
	ms := g.merge
	if ms == nil || len(ms.conflicts) == 0 {
		return
	}
	c := ms.conflicts[ms.idx]
	var keep []string
	ours := ms.lines[c.start+1 : func() int {
		if c.ancestor >= 0 {
			return c.ancestor
		}
		return c.middle
	}()]
	theirs := ms.lines[c.middle+1 : c.end]
	switch mode {
	case "top":
		keep = ours
	case "bottom":
		keep = theirs
	case "all":
		keep = append(append([]string{}, ours...), theirs...)
	}
	var nl []string
	nl = append(nl, ms.lines[:c.start]...)
	nl = append(nl, keep...)
	nl = append(nl, ms.lines[c.end+1:]...)
	ms.history = append(ms.history, strings.Join(ms.lines, "\n")+"\n")
	g.logAction("Resolve merge conflict")
	switch mode {
	case "top":
		g.logCommand("Picking top hunk", false)
	case "bottom":
		g.logCommand("Picking bottom hunk", false)
	case "all":
		g.logCommand("Picking all hunks", false)
	}
	os.WriteFile(ms.path, []byte(strings.Join(nl, "\n")+"\n"), 0o644)
	g.afterConflictChange()
}

func (g *Gui) afterConflictChange() {
	ms := g.merge
	nm := g.loadMergeState(ms.path, ms)
	if nm == nil || len(nm.conflicts) == 0 {
		g.merge = nil
		g.logAction("Stage files whose merge conflicts were resolved")
		g.runGitLogged("add", "--", ms.path)
		g.refreshFiles()
		g.pushContext(g.ctx["files"])
		if !g.hasConflicts() {
			g.promptContinue()
		}
		return
	}
	g.merge = nm
	g.mergeFocusSelection()
}

func (g *Gui) promptContinue() {
	st := g.workingTreeState()
	what := "merge"
	if st == "rebasing" {
		what = "rebase"
	}
	g.showConfirm("Continue", "All merge conflicts resolved. Continue the "+what+"?", func() {
		g.continueOperation()
	})
}

func (g *Gui) continueOperation() {
	st := g.workingTreeState()
	cmd := map[string]string{"rebasing": "rebase", "merging": "merge", "cherry-picking": "cherry-pick", "reverting": "revert"}[st]
	if cmd == "" {
		return
	}
	g.logAction("Merge/Rebase: continue")
	g.logCommand("git "+cmd+" --continue", true)
	c := gitCmd(cmd, "--continue")
	c.Env = append(c.Env, "GIT_EDITOR=true")
	out, err := c.CombinedOutput()
	if err != nil {
		if strings.Contains(string(out), "CONFLICT") {
			g.refreshAll()
			return
		}
		g.showError(strings.TrimSpace(string(out)))
	}
	g.refreshAll()
}

func (g *Gui) mergeBindings() []*binding {
	move := func(d int) func() {
		return func() {
			ms := g.merge
			if ms == nil {
				return
			}
			ms.side += d
			if ms.side < 0 {
				ms.side = 0
			}
			if ms.side > 1 {
				ms.side = 1
			}
			g.mergeFocusSelection()
		}
	}
	conf := func(d int) func() {
		return func() {
			ms := g.merge
			if ms == nil {
				return
			}
			ni := ms.idx + d
			if ni >= 0 && ni < len(ms.conflicts) {
				ms.idx = ni
			}
			g.mergeFocusSelection()
		}
	}
	return []*binding{
		{cfgKey: "universal.select", fn: func() {
			if g.merge == nil {
				return
			}
			if g.merge.side == 0 {
				g.resolveConflict("top")
			} else {
				g.resolveConflict("bottom")
			}
		}, short: "Pick hunk", display: true},
		{cfgKey: "main.pickBothHunks", fn: func() { g.resolveConflict("all") }, short: "Pick all hunks", display: true},
		{cfgKey: "universal.prevItem", fn: move(-1), short: "Previous hunk", display: true},
		{cfgKey: "universal.nextItem", fn: move(1), short: "Next hunk", display: true},
		{cfgKey: "universal.prevItem-alt", fn: move(-1)},
		{cfgKey: "universal.nextItem-alt", fn: move(1)},
		{cfgKey: "universal.prevBlock", fn: conf(-1), short: "Previous conflict", display: true},
		{cfgKey: "universal.nextBlock", fn: conf(1), short: "Next conflict", display: true},
		{cfgKey: "universal.prevBlock-alt", fn: conf(-1)},
		{cfgKey: "universal.nextBlock-alt", fn: conf(1)},
		{cfgKey: "universal.undo", fn: func() {
			ms := g.merge
			if ms == nil || len(ms.history) == 0 {
				return
			}
			last := ms.history[len(ms.history)-1]
			ms.history = ms.history[:len(ms.history)-1]
			g.logAction("Restoring file to previous state")
			os.WriteFile(ms.path, []byte(last), 0o644)
			g.merge = g.loadMergeState(ms.path, ms)
		}, short: "Undo", display: true},
		{cfgKey: "universal.edit", fn: func() {
			if g.merge != nil {
				g.editFile(g.merge.path)
			}
		}, short: "Edit file", display: true},
		{cfgKey: "files.openMergeOptions", fn: func() {}, short: "View merge conflict options", display: true},
		{cfgKey: "universal.return", fn: func() {
			g.merge = nil
			g.pushContext(g.ctx["files"])
		}},
	}
}
