		for _, x := range g.tags {
			r = append(r, x.Name)
		}
		return r
	}
	g.ctx["reflogCommits"].filterStrings = func() []string {
		var r []string
		for _, x := range g.reflog {
			r = append(r, x.ShortHash()+" "+x.Name)
		}
		return r
	}
