cat > branch_menus.go <<'EOF'
package main

import (
	"strings"
)

func (g *Gui) baseBranchFor(branch string) string {
	// closest main branch by merge-base distance
	best := ""
	bestCount := -1
	for _, ref := range g.determineMainBranches() {
		mb, err := runGit("merge-base", branch, ref)
		if err != nil {
			continue
		}
		mb = strings.TrimSpace(mb)
		cnt, _ := runGit("rev-list", "--count", mb+".."+branch)
		n := 0
		for _, c := range strings.TrimSpace(cnt) {
			n = n*10 + int(c-'0')
		}
		if bestCount < 0 || n < bestCount {
			bestCount = n
			best = ref
		}
	}
	best = strings.TrimPrefix(best, "refs/remotes/")
	best = strings.TrimPrefix(best, "refs/heads/")
	return best
}

func (g *Gui) openUpstreamMenu() {
	b := g.selectedBranch()
	if b == nil {
		return
	}
	noUpstream := ""
	if !b.IsTrackingRemote() || b.UpstreamGone {
		noUpstream = "The selected branch has no upstream (or the upstream is not stored locally)"
	}
	base := g.baseBranchFor(b.Name)
	upstreamLabel := "upstream of selected branch"
	if noUpstream == "" {
		upstreamLabel = b.Upstream
	}
	items := []*menuItem{
		{Label: "View divergence from upstream", Disabled: noUpstream, OnPress: func() {}},
		{Key: "b", Label: "View divergence from base branch (" + base + ")", OnPress: func() {}},
		{Key: "u", Label: "Unset upstream of selected branch", Disabled: noUpstream, OnPress: func() {
			g.logAction("Unset branch upstream")
			g.runGitLogged("branch", "--unset-upstream", b.Name)
			g.refreshAll()
		}},
		{Key: "s", Label: "Set upstream of selected branch", OnPress: func() {
			g.showPrompt("Enter upstream as '<remote> <branchname>'", "origin "+b.Name, func(s string) {
				parts := strings.Fields(s)
				if len(parts) != 2 {
					return
				}
				g.logAction("Set branch upstream")
				g.runGitLogged("branch", "--set-upstream-to="+parts[0]+"/"+parts[1], b.Name)
				g.refreshAll()
			})
		}},
		{Key: "g", Label: "Reset checked-out branch onto " + upstreamLabel + "...", Disabled: noUpstream, OpensMenu: true,
			Tooltip: "View options for resetting the checked-out branch onto " + upstreamLabel + ". Note: this will not reset the selected branch onto the upstream, it will reset the checked-out branch onto the upstream.",
			OnPress: func() { g.openResetToRefMenu(b.Upstream) }},
		{Key: "r", Label: "Rebase checked-out branch onto " + upstreamLabel + "...", Disabled: noUpstream, OpensMenu: true,
			Tooltip: "View options for rebasing the checked-out branch onto " + upstreamLabel + ". Note: this will not rebase the selected branch onto the upstream, it will rebase the checked-out branch onto the upstream.",
			OnPress: func() {}},
	}
	g.showMenu("Upstream options", items)
}

func (g *Gui) openRebaseBranchMenu() {
	b := g.selectedBranch()
	if b == nil || g.headBranch == nil {
		return
	}
	cur := g.headBranch.Name
	selfDisabled := ""
	if b.Head {
		selfDisabled = "You cannot rebase a branch onto itself"
	}
	base := g.baseBranchFor(cur)
	doRebase := func(onto string) {
		g.logAction("Rebase branch")
		out, err := g.runGitLogged("rebase", "--interactive", "--autostash", "--keep-empty", "--no-autosquash", "--rebase-merges", onto)
		_ = out
		if err != nil {
			g.handleRebaseResult(out)
		}
		g.refreshAll()
	}
	items := []*menuItem{
		{Key: "s", Label: "Simple rebase onto '" + b.Name + "'", Disabled: selfDisabled, OnPress: func() { doRebase(b.Name) }},
		{Key: "i", Label: "Interactive rebase onto '" + b.Name + "'", Disabled: selfDisabled,
			Tooltip: "Begin an interactive rebase with a break at the start, so you can update the TODO commits before continuing.", OnPress: func() {}},
		{Key: "b", Label: "Rebase onto base branch (" + base + ")",
			Tooltip: "Rebase the checked out branch onto its base branch (i.e. the closest main branch).", OnPress: func() { doRebase(base) }},
	}
	g.showMenu("Rebase '"+cur+"'", items)
}

func (g *Gui) openBranchSortMenu() {
	cur := g.cfg.LocalBranchSortOrder
	radio := func(o string) string {
		if o == cur {
			return "(•)"
		}
		return "( )"
	}
	set := func(o string) func() {
		return func() {
			g.cfg.LocalBranchSortOrder = o
			g.refreshBranches()
		}
	}
	items := []*menuItem{
		{Key: "r", Columns: []string{radio("recency"), "Recency", "(based on reflog)"}, OnPress: set("recency")},
		{Key: "a", Columns: []string{radio("alphabetical"), "Alphabetical", "--sort=refname"}, OnPress: set("alphabetical")},
		{Key: "d", Columns: []string{radio("date"), "Date", "--sort=-committerdate"}, OnPress: set("date")},
		{Label: "Cancel", Columns: []string{"", "Cancel", ""}},
	}
	g.showMenu("Sort order", items)
	g.menu.prompt = "The default sort order for local branches can be set in the config file with the key 'git.localBranchSortOrder'."
}
