{"command":"cd /workspace/src; cat > undo.go <<'EOF'
package main

import (
	"regexp"
	"strings"
)

type reflogAction struct {
	kind     string // checkout, commit, rebase, currentRebase
	from, to string
}

var (
	reUndo        = regexp.MustCompile(`^\[lazygit undo\]`)
	reRedo        = regexp.MustCompile(`^\[lazygit redo\]`)
	reRebaseEnd   = regexp.MustCompile(`^rebase (-i )?\((abort|finish)\)`)
	reCheckout    = regexp.MustCompile(`^checkout: moving from ([\S]+) to ([\S]+)`)
	reCommitLike  = regexp.MustCompile(`^commit|^reset: moving to|^pull`)
	reRebaseStart = regexp.MustCompile(`^rebase (-i )?\(start\)`)
)

func (g *Gui) parseReflogForActions(onAction func(counter int, a reflogAction) bool) {
	reflog := loadReflogCommits(0)
	counter := 0
	rebaseFinishHash := ""
	for i, rc := range reflog {
		var action *reflogAction
		prevHash := ""
		if i+1 < len(reflog) {
			prevHash = reflog[i+1].Hash
		}
		if rebaseFinishHash == "" {
			switch {
			case reUndo.MatchString(rc.Name):
				counter++
			case reRedo.MatchString(rc.Name):
				counter--
			case reRebaseEnd.MatchString(rc.Name):
				rebaseFinishHash = rc.Hash
			case reCheckout.MatchString(rc.Name):
				m := reCheckout.FindStringSubmatch(rc.Name)
				action = &reflogAction{kind: "checkout", from: m[1], to: m[2]}
			case reCommitLike.MatchString(rc.Name):
				action = &reflogAction{kind: "commit", from: prevHash, to: rc.Hash}
			case reRebaseStart.MatchString(rc.Name):
				action = &reflogAction{kind: "currentRebase", from: prevHash}
			}
		} else if rc.Hash == rebaseFinishHash {
			// nothing
		} else if reRebaseStart.MatchString(rc.Name) {
			action = &reflogAction{kind: "rebase", from: prevHash, to: rebaseFinishHash}
			rebaseFinishHash = ""
		}
		if action != nil {
			if action.kind != "currentRebase" && action.from == action.to {
				continue
			}
			if onAction(counter, *action) {
				return
			}
			counter--
		}
	}
}

func short8(h string) string {
	if len(h) > 8 {
		return h[:8]
	}
	return h
}

func (g *Gui) handleUndo() {
	if g.workingTreeState() == "rebasing" {
		g.showError("Can't undo while rebasing")
		return
	}
	g.parseReflogForActions(func(counter int, a reflogAction) bool {
		if counter != 0 {
			return false
		}
		switch a.kind {
		case "commit":
			g.showConfirm("Undo", "Are you sure you want to soft reset to '"+short8(a.from)+"'?", func() {
				g.logAction("Undo")
				g.runReflogCmd("[lazygit undo]", "reset", "--soft", a.from)
			})
		case "rebase":
			g.showConfirm("Undo", "Are you sure you want to hard reset to '"+short8(a.from)+"'? An auto-stash will be performed if necessary.", func() {
				g.logAction("Undo")
				g.runReflogCmd("[lazygit undo]", "reset", "--hard", a.from)
			})
		case "checkout":
			g.showConfirm("Undo", "Are you sure you want to checkout '"+a.from+"'? An auto-stash will be performed if necessary.", func() {
				g.logAction("Undo")
				g.runReflogCmd("[lazygit undo]", "checkout", a.from)
			})
		}
		return true
	})
}

func (g *Gui) handleRedo() {
	if g.workingTreeState() == "rebasing" {
		g.showError("Can't redo while rebasing")
		return
	}
	g.parseReflogForActions(func(counter int, a reflogAction) bool {
		if counter == 0 {
			return true
		} else if counter > 1 {
			return false
		}
		switch a.kind {
		case "commit", "rebase":
			g.showConfirm("Redo", "Are you sure you want to hard reset to '"+short8(a.to)+"'? An auto-stash will be performed if necessary.", func() {
				g.logAction("Redo")
				g.runReflogCmd("[lazygit redo]", "reset", "--hard", a.to)
			})
		case "checkout":
			g.showConfirm("Redo", "Are you sure you want to checkout '"+a.to+"'? An auto-stash will be performed if necessary.", func() {
				g.logAction("Redo")
				g.runReflogCmd("[lazygit redo]", "checkout", a.to)
			})
		}
		return true
	})
}

func (g *Gui) runReflogCmd(reflogAction string, args ...string) {
	g.logCommand("git "+quoteArgs(args), true)
	cmd := gitCmd(args...)
	cmd.Env = append(cmd.Env, "GIT_REFLOG_ACTION="+reflogAction)
	out, err := cmd.CombinedOutput()
	if err != nil {
		g.showError(strings.TrimSpace(string(out)))
	}
	g.refreshAll()
}
