func (g *Gui) openFilesStatusFilterMenu() {
	cur := g.fileStatusFilter
	radio := func(o string) string {
		if o == cur {
			return "(•)"
		}
		return "( )"
	}
	set := func(o string) func() {
		return func() {
			g.fileStatusFilter = o
			g.refreshFiles()
			g.mainKey = ""
		}
	}
	items := []*menuItem{
		{Key: "s", Columns: []string{radio("staged"), "Show only staged files"}, OnPress: set("staged")},
		{Key: "u", Columns: []string{radio("unstaged"), "Show only unstaged files"}, OnPress: set("unstaged")},
		{Key: "t", Columns: []string{radio("tracked"), "Show only tracked files"}, OnPress: set("tracked")},
		{Key: "T", Columns: []string{radio("untracked"), "Show only untracked files"}, OnPress: set("untracked")},
		{Key: "r", Columns: []string{radio(""), "No filter"}, OnPress: set("")},
		{Label: "Cancel", Columns: []string{"", "Cancel"}},
	}
	g.showMenu("Filtering", items)
}

func (g *Gui) openFilteringMenu() {
	var items []*menuItem
	side := g.currentSideContext()
	filterBy := ""
	switch side.Key {
	case "files":
		if n := g.selectedFileNode(); n != nil {
			filterBy = n.Path
			if filterBy == "" {
				filterBy = "."
			}
		}
	case "commits":
		if c := g.selectedCommit(); c != nil {
			filterBy = c.AuthorName + " <" + c.AuthorEmail + ">"
		}
	case "commitFiles":
		if n := g.selectedCommitFileNode(); n != nil {
			filterBy = n.Path
		}
	}
	if filterBy != "" {
		items = append(items, &menuItem{Label: "Filter by '" + filterBy + "'", OnPress: func() {}})
	}
	items = append(items,
		&menuItem{Label: "Enter path to filter by", OnPress: func() {}},
		&menuItem{Label: "Enter author to filter by", OnPress: func() {}},
	)
	g.showMenu("Filtering", items)
}

func (g *Gui) openDiffingMenu() {
	var items []*menuItem
	side := g.currentSideContext()
	var names []string
	switch side.Key {
	case "localBranches":
		if b := g.selectedBranch(); b != nil {
			names = append(names, b.Name)
			if b.IsTrackingRemote() {
				names = append(names, b.Name+"@{u}")
			}
		}
	case "commits":
		if c := g.selectedCommit(); c != nil {
			names = append(names, c.Hash)
		}
	case "reflogCommits":
		if c := g.selectedReflog(); c != nil {
			names = append(names, c.Hash)
		}
	case "subCommits":
		if c := g.selectedSubCommit(); c != nil {
			names = append(names, c.Hash)
		}
	case "tags":
		if t := g.selectedTag(); t != nil {
			names = append(names, t.Name)
		}
	case "remoteBranches":
		if rb := g.selectedRemoteBranch(); rb != nil {
			names = append(names, rb.FullName())
		}
	case "stash":
		if s := g.selectedStash(); s != nil {
			names = append(names, s.RefName())
		}
	}
	for _, n := range names {
		n := n
		items = append(items, &menuItem{Label: "Diff " + n, OnPress: func() {
			g.diffName = n
			g.mainKey = ""
		}})
	}
	items = append(items, &menuItem{Label: "Enter ref to diff", OnPress: func() {
		g.showPrompt("Enter ref to diff:", "", func(s string) {
			g.diffName = s
			g.mainKey = ""
		})
		g.confirm.suggestions = g.refSuggestions
	}})
	g.showMenu("Diffing", items)
}

func (g *Gui) openCommitCopyMenu(c *Commit) {
	items := []*menuItem{
		{Label: "Commit hash", OnPress: func() { g.copyToClipboard(c.Hash) }},
		{Key: "s", Label: "Commit subject", OnPress: func() { g.copyToClipboard(c.Name) }},
		{Key: "m", Label: "Commit message (subject and body)", OnPress: func() {}},
		{Key: "b", Label: "Commit message body", OnPress: func() {}},
		{Key: "u", Label: "Commit URL", OnPress: func() {}},
		{Key: "d", Label: "Commit diff", OnPress: func() {}},
		{Key: "a", Label: "Commit author", OnPress: func() {}},
		{Key: "t", Label: "Commit tags", OnPress: func() {}},
	}
	g.showMenu("Copy to clipboard", items)
}

func (g *Gui) openFileCopyMenu() {
	n := g.selectedFileNode()
	if n == nil {
		return
	}
	items := []*menuItem{
		{Key: "n", Label: "File name", OnPress: func() { g.copyToClipboard(filepath.Base(n.Path)) }},
		{Key: "p", Label: "Relative path", OnPress: func() { g.copyToClipboard(n.Path) }},
		{Key: "P", Label: "Absolute path", OnPress: func() { g.copyToClipboard(filepath.Join(g.repoRoot, n.Path)) }},
		{Key: "s", Label: "Diff of selected file", OnPress: func() {}},
		{Key: "a", Label: "Diff of all files", OnPress: func() {}},
	}
	g.showMenu("Copy to clipboard", items)
}

func (g *Gui) copyToClipboard(s string) {
	for _, tool := range [][]string{{"xclip", "-selection", "clipboard"}, {"xsel", "--clipboard", "--input"}, {"wl-copy"}, {"pbcopy"}} {
		if _, err := lookPath(tool[0]); err == nil {
			cmd := execCommand(tool[0], tool[1:]...)
			cmd.Stdin = strings.NewReader(s)
			if cmd.Run() == nil {
				g.showToast("'" + truncateWithEllipsis(s, 50) + "' copied to clipboard")
				return
			}
		}
	}
	g.showError("Could not find a clipboard tool")
}

