func (g *Gui) moveCommit(up bool) {
	c := g.ctx["commits"]
	i := c.sel
	j := i + 1
	if up {
		j = i - 1
	}
	if i < 0 || i >= len(g.commits) || j < 0 || j >= len(g.commits) {
		return
	}
	if g.isRebasing() {
		return
	}
	a, b := g.commits[i], g.commits[j]
	top, bottom := a, b
	if up {
		top, bottom = b, a
	}
	// base is the commit below the lower of the two
	lowIdx := maxInt(i, j)
	base := "--root"
	if lowIdx+1 < len(g.commits) {
		base = g.commits[lowIdx+1].Hash
	}
	if up {
		g.logAction("Move commit up")
	} else {
		g.logAction("Move commit down")
	}
	g.logCommand("git rebase --interactive --autostash --keep-empty --no-autosquash --rebase-merges "+base, true)
	// in the todo file, older commits come first: bottom then top; swap them
	script := "awk -v a='" + bottom.Hash[:7] + "' -v b='" + top.Hash[:7] + "' '{ if ($1==\"pick\" && index($2,a)==1) {la=$0; next} if ($1==\"pick\" && index($2,b)==1) {print; if (la!=\"\") print la; la=\"\"; next} print }' \"$1\" > \"$1.tmp\" && mv \"$1.tmp\" \"$1\""
	cmd := gitCmd("rebase", "--interactive", "--autostash", "--keep-empty", "--no-autosquash", "--rebase-merges", base)
	cmd.Env = append(cmd.Env, "GIT_SEQUENCE_EDITOR=sh -c '"+strings.ReplaceAll(script, "'", "'\\''")+"' --", "GIT_EDITOR=true")
	out, err := cmd.CombinedOutput()
	if err != nil && !strings.Contains(string(out), "CONFLICT") {
		g.showError(strings.TrimSpace(string(out)))
	}
	g.refreshAll()
	c.sel = j
	c.clampSel()
}

func (g *Gui) startInteractiveRebase() {
	base := ""
	for _, c := range g.commits {
		if c.Status == "merged" {
			base = c.Hash
			break
		}
	}
	if base == "" {
		base = "--root"
	}
	g.logAction("Edit commit")
	g.logCommand("Beginning interactive rebase at '"+base+"'", false)
	g.logCommand("git rebase --interactive --autostash --keep-empty --no-autosquash --rebase-merges "+base, true)
	cmd := gitCmd("rebase", "--interactive", "--autostash", "--keep-empty", "--no-autosquash", "--rebase-merges", base)
	cmd.Env = append(cmd.Env, "GIT_SEQUENCE_EDITOR=sed -i -e '1i break'", "GIT_EDITOR=true")
	cmd.CombinedOutput()
	g.refreshAll()
}
